struct AppState {
    app_handle: Option<AppHandle>,
    settings_path: PathBuf,
    db_path: PathBuf,
    files_base_dir: PathBuf,
    default_download_dir: PathBuf,
    settings: Mutex<Settings>,
    supabase_sessions: Mutex<HashMap<String, supabase_auth::SupabaseSession>>,
    supabase_binding_flows: Mutex<HashMap<String, SupabaseBindingFlow>>,
    supabase_auth_guard: AsyncMutex<()>,
    sync_status: Mutex<SyncStatus>,
    sync_guard: Arc<AsyncMutex<()>>,
    storage_transfer_targets: Mutex<HashSet<String>>,
    sync_cancel: Mutex<Option<oneshot::Sender<()>>>,
    sync_loop_signal: watch::Sender<u64>,
    http: Client,
    registered_hotkey: Mutex<Option<Shortcut>>,
    registered_system_dictation_hotkey: Mutex<Option<Shortcut>>,
    telegram_bridge: Mutex<TelegramBridgeManager>,
    telegram_bridge_generation: std::sync::atomic::AtomicU64,
    local_http_api: Mutex<LocalHttpApiManager>,
    update_guard: AsyncMutex<()>,
    auto_backup_guard: AsyncMutex<()>,
    pending_webdav_conflict: Mutex<Option<WebDavConflict>>,
    #[cfg(target_os = "macos")]
    system_dictation_hidden_main_position: Mutex<Option<PhysicalPosition<i32>>>,
    media_playback: media_playback::PlaybackRegistry,
    media_preview_jobs: AsyncMutex<HashMap<String, Arc<MediaPreviewJob>>>,
}

