#[cfg(desktop)]
fn load_app_icon() -> Result<tauri::image::Image<'static>, String> {
    tauri::image::Image::from_bytes(include_bytes!("../icons/icon.png"))
        .map(|image| image.to_owned())
        .map_err(|err| format!("加载图标失败: {err}"))
}

