async fn run_storage_transfer(
    state: &AppState,
    input: StorageTransferRequest,
) -> Result<StorageTransferProgressResult, String> {
    let context = storage_transfer_context(state, &input).await?;
    let _target_guard = lock_storage_transfer_target(
        state,
        context.target.profile_id(),
        &context.target_owner_scope,
    )?;
    refresh_storage_transfer_source(state, &context.source).await?;
    let (messages, tags) =
        storage_transfer_messages_and_tags(state, &context.source, &context.source_owner_scope)?;
    let batch_id = storage_import_batch_id(
        context.source.profile_id(),
        context.target.profile_id(),
        &context.source_owner_scope,
        &context.target_owner_scope,
    );
    if db::get_storage_transfer_progress(&state.db_path, &batch_id)
        .map_err(|error| error.to_string())?
        .is_none()
    {
        let plan_token = uuid::Uuid::new_v4().to_string();
        refresh_storage_transfer_source(state, &context.target).await?;
        let items = prepare_storage_transfer_items(state, &context, &plan_token, &messages, &tags)?;
        db::create_or_resume_storage_transfer(
            &state.db_path,
            &db::NewStorageTransferBatch {
                batch_id: &batch_id,
                source_profile_id: context.source.profile_id(),
                target_profile_id: context.target.profile_id(),
                source_provider_kind: context.source.provider_kind(),
                target_provider_kind: context.target.provider_kind(),
                source_owner_scope: &context.source_owner_scope,
                target_owner_scope: &context.target_owner_scope,
                items: &items,
                now_ms: now_ms(),
            },
        )
        .map_err(|error| format!("保存数据传输计划失败: {error}"))?;
    }
    if !db::mark_storage_transfer_running(&state.db_path, &batch_id, now_ms())
        .map_err(|error| format!("启动数据传输失败: {error}"))?
    {
        return Err("数据传输计划不存在或已取消".to_string());
    }

    let result = run_storage_transfer_batch(state, &context, &batch_id, messages, tags).await;
    if let Err(error) = &result {
        let _ = db::mark_storage_transfer_interrupted(&state.db_path, &batch_id, error, now_ms());
    }
    result
}

async fn run_storage_transfer_batch(
    state: &AppState,
    context: &StorageTransferContext,
    batch_id: &str,
    messages: Vec<Message>,
    tags: Vec<MarkedTag>,
) -> Result<StorageTransferProgressResult, String> {
    let source_messages = messages
        .into_iter()
        .map(|message| (message.filename.clone(), message))
        .collect::<HashMap<_, _>>();
    let source_tags = tags
        .into_iter()
        .map(|tag| (tag.id.clone(), tag))
        .collect::<HashMap<_, _>>();
    let pending = db::list_storage_transfer_items(&state.db_path, &batch_id, &["pending", "error"])
        .map_err(|error| error.to_string())?;
    for pending_item in pending {
        if db::storage_transfer_is_cancelled(&state.db_path, batch_id)
            .map_err(|error| error.to_string())?
        {
            return Err("数据传输已取消".to_string());
        }
        let result = if pending_item.item_type == "tag" {
            transfer_storage_tag(
                state,
                context,
                batch_id,
                &pending_item,
                source_tags
                    .get(&pending_item.source_key)
                    .ok_or_else(|| "来源标签已不存在".to_string())?,
            )
            .await
        } else {
            let source_message = source_messages
                .get(&pending_item.source_key)
                .ok_or_else(|| "来源消息已不存在".to_string())?;
            if !storage_transfer_source_matches(&pending_item, source_message) {
                Err("来源数据在预览后已发生变化，已记录冲突".to_string())
            } else {
                transfer_storage_message(state, context, batch_id, &pending_item, source_message)
                    .await
            }
        };
        if let Err(error) = result {
            let item_state = if error.contains("冲突") {
                "conflict"
            } else {
                "error"
            };
            db::mark_storage_transfer_item_state(
                &state.db_path,
                batch_id,
                &pending_item.item_type,
                &pending_item.source_key,
                item_state,
                Some(&error),
                now_ms(),
            )
            .map_err(|db_error| db_error.to_string())?;
        }
    }

    if db::storage_transfer_is_cancelled(&state.db_path, batch_id)
        .map_err(|error| error.to_string())?
    {
        return Err("数据传输已取消".to_string());
    }

    if let (storage_provider::ProviderConfig::Supabase(target), Some(session)) =
        (&context.target, context.target_session.as_ref())
    {
        let _sync_guard = state.sync_guard.lock().await;
        push_supabase_outbox(state, target, session, true, Some(batch_id))
            .await
            .map_err(|error| format!("上传数据到目标 Supabase 失败: {error}"))?;
        if db::storage_transfer_is_cancelled(&state.db_path, batch_id)
            .map_err(|error| error.to_string())?
        {
            return Err("数据传输已取消".to_string());
        }
        let remaining = db::count_pending_import_outbox(&state.db_path, batch_id)
            .map_err(|error| format!("检查目标上传状态失败: {error}"))?;
        if remaining > 0 {
            return Err(format!("目标 Supabase 仍有 {remaining} 项数据等待上传"));
        }
        let conflicts = db::count_import_conflicts(&state.db_path, batch_id)
            .map_err(|error| format!("检查目标冲突失败: {error}"))?;
        if conflicts > 0 {
            return Err(format!("目标 Supabase 产生 {conflicts} 项数据冲突"));
        }
        let _ = pull_supabase_changes(state, target, session).await?;
        verify_storage_transfer_supabase_target(
            state,
            target,
            session,
            batch_id,
            &source_messages,
            &source_tags,
        )
        .await
        .map_err(|error| format!("核验目标 Supabase 数据失败: {error}"))?;
        let _ = refresh_supabase_status(state, None);
    }
    if matches!(&context.target, storage_provider::ProviderConfig::Webdav(_)) {
        if db::storage_transfer_is_cancelled(&state.db_path, batch_id)
            .map_err(|error| error.to_string())?
        {
            return Err("数据传输已取消".to_string());
        }
        verify_storage_transfer_webdav_target(
            state,
            context,
            batch_id,
            &source_messages,
            &source_tags,
        )
        .await
        .map_err(|error| format!("核验目标 WebDAV 数据失败: {error}"))?;
    }
    let _ = db::mark_storage_transfer_completed(&state.db_path, batch_id, now_ms())
        .map_err(|error| format!("完成数据传输任务失败: {error}"))?;
    let progress = db::get_storage_transfer_progress(&state.db_path, batch_id)
        .map_err(|error| error.to_string())?
        .ok_or_else(|| "数据传输批次不存在".to_string())?;
    let progress = storage_transfer_progress_result(&state.db_path, progress)?;
    if progress.status == "completed" {
        let _ = fs::remove_dir_all(
            state
                .files_base_dir
                .join("storage-transfers")
                .join(batch_id),
        );
    }
    Ok(progress)
}

async fn transfer_storage_tag(
    state: &AppState,
    context: &StorageTransferContext,
    batch_id: &str,
    item: &db::StorageTransferItem,
    source_tag: &MarkedTag,
) -> Result<(), String> {
    let mut target_tags = storage_transfer_target_tags(state, context)?;
    let mut remote_matching_tag = false;
    if let (storage_provider::ProviderConfig::Supabase(target), Some(session)) =
        (&context.target, context.target_session.as_ref())
    {
        let config = target
            .supabase
            .as_ref()
            .ok_or_else(|| "Supabase 存储空间配置不完整".to_string())?;
        if let Some(snapshot) =
            supabase_sync::fetch_tag_by_name(&state.http, config, session, &source_tag.name).await?
        {
            if let (Some(id), Some(name), Some(revision)) = (
                snapshot["id"].as_str(),
                snapshot["name"].as_str(),
                snapshot["revision"].as_i64(),
            ) {
                remote_matching_tag = true;
                target_tags.push((
                    MarkedTag {
                        id: id.to_string(),
                        name: name.to_string(),
                    },
                    revision,
                ));
            }
        }
    }
    let normalized_name = normalize_storage_transfer_tag_name(&source_tag.name);
    if let Some((existing, _)) =
        storage_transfer_matching_target_tag(&target_tags, source_tag, &item.entity_id).filter(
            |(tag, revision)| {
                normalize_storage_transfer_tag_name(&tag.name) == normalized_name
                    && (!matches!(
                        &context.target,
                        storage_provider::ProviderConfig::Supabase(_)
                    ) || remote_matching_tag
                        || *revision > 0)
            },
        )
    {
        db::supersede_storage_transfer_item_operations(
            &state.db_path,
            batch_id,
            &item.item_type,
            &item.source_key,
            now_ms(),
        )
        .map_err(|error| error.to_string())?;
        if let storage_provider::ProviderConfig::Supabase(target) = &context.target {
            let mapped_tag_id = remap_storage_transfer_tag_ids(
                context.source.profile_id(),
                &context.source_owner_scope,
                std::slice::from_ref(&source_tag.id),
            )
            .into_iter()
            .next()
            .unwrap_or_default();
            if mapped_tag_id != existing.id {
                db::delete_unconfirmed_tag(
                    &state.db_path,
                    &target.id,
                    &context.target_owner_scope,
                    &mapped_tag_id,
                )
                .map_err(|error| error.to_string())?;
            }
        }
        if existing.id != item.entity_id {
            db::update_storage_transfer_item_entity_id(
                &state.db_path,
                batch_id,
                &item.item_type,
                &item.source_key,
                &existing.id,
                now_ms(),
            )
            .map_err(|error| error.to_string())?;
        }
        return db::mark_storage_transfer_item_state(
            &state.db_path,
            batch_id,
            &item.item_type,
            &item.source_key,
            "skipped",
            None,
            now_ms(),
        )
        .map_err(|error| error.to_string());
    }
    let target_tag = MarkedTag {
        id: item.entity_id.clone(),
        name: source_tag.name.clone(),
    };
    match &context.target {
        storage_provider::ProviderConfig::Webdav(target) => {
            write_storage_transfer_tag_to_webdav(state, target, &target_tag).await?;
            db::mark_storage_transfer_item_state(
                &state.db_path,
                batch_id,
                &item.item_type,
                &item.source_key,
                "applied",
                None,
                now_ms(),
            )
            .map_err(|error| error.to_string())
        }
        storage_provider::ProviderConfig::Supabase(target) => {
            let session = context
                .target_session
                .as_ref()
                .ok_or_else(|| "目标 Supabase 存储空间尚未登录".to_string())?;
            let base_revision = target_tags
                .iter()
                .find(|(tag, _)| tag.id == target_tag.id)
                .map(|(_, revision)| *revision)
                .unwrap_or_default();
            let operation = outbox_operation_with_id(
                &item.message_operation_id,
                &target.id,
                &session.user_id,
                "tag",
                &target_tag.id,
                "upsert",
                base_revision,
                serde_json::json!({"name":target_tag.name}),
            )?;
            db::apply_imported_tag(
                &state.db_path,
                batch_id,
                &item.source_key,
                &target.id,
                &session.user_id,
                &target_tag,
                &operation,
                now_ms(),
            )
            .map_err(|error| error.to_string())
        }
    }
}

async fn transfer_storage_message(
    state: &AppState,
    context: &StorageTransferContext,
    batch_id: &str,
    item: &db::StorageTransferItem,
    source_message: &Message,
) -> Result<(), String> {
    match &context.target {
        storage_provider::ProviderConfig::Webdav(target) => {
            let result = write_storage_transfer_message_to_webdav(
                state,
                &context.source,
                context.source_session.as_ref(),
                target,
                batch_id,
                item,
                source_message,
            )
            .await?;
            db::mark_storage_transfer_item_state(
                &state.db_path,
                batch_id,
                &item.item_type,
                &item.source_key,
                result,
                None,
                now_ms(),
            )
            .map_err(|error| error.to_string())
        }
        storage_provider::ProviderConfig::Supabase(target) => {
            let session = context
                .target_session
                .as_ref()
                .ok_or_else(|| "目标 Supabase 存储空间尚未登录".to_string())?;
            import_storage_message_to_supabase(
                state,
                &context.source,
                context.source_session.as_ref(),
                target,
                session,
                batch_id,
                item,
                source_message,
            )
            .await
        }
    }
}

#[allow(clippy::too_many_arguments)]
async fn import_storage_message_to_supabase(
    state: &AppState,
    source: &storage_provider::ProviderConfig,
    source_session: Option<&supabase_auth::SupabaseSession>,
    target: &StorageProfile,
    session: &supabase_auth::SupabaseSession,
    batch_id: &str,
    item: &db::StorageImportItem,
    source_message: &Message,
) -> Result<(), String> {
    let mut message = DbMessage {
        endpoint_id: target.id.clone(),
        filename: storage_transfer_target_filename(source_message, &item.entity_id),
        sender: source_message.sender.clone(),
        timestamp_ms: source_message.timestamp_ms,
        size: source_message.size,
        kind: source_message.kind.clone(),
        original_name: source_message.original_name.clone(),
        etag: None,
        mtime: None,
        content: source_message.content.clone(),
        local_path: None,
        remote_path: None,
        file_hash: source_message.file_hash.clone(),
        marked: source_message.marked,
        marked_tag_ids: map_storage_transfer_tag_ids(
            &storage_transfer_tag_mapping_for_batch(state, batch_id)?,
            &source_message.marked_tag_ids,
        ),
        marked_pinned: source_message.marked_pinned,
        marked_due_date: source_message.marked_due_date.clone(),
        format: source_message.format.clone(),
        transcript_source: source_message.transcript_source.clone(),
        source_audio_mime_type: source_message.source_audio_mime_type.clone(),
        transcript_raw_text: source_message.transcript_raw_text.clone(),
        source_kind: source_message.source_kind.clone(),
        source_channel_id: source_message.source_channel_id.clone(),
        source_message_id: source_message.source_message_id.clone(),
    };
    let mut message_base_revision = 0;
    let existing_by_id = db::get_message_by_id_for_scope(
        &state.db_path,
        &target.id,
        &session.user_id,
        &item.entity_id,
    )
    .map_err(|error| error.to_string())?;
    let existing = if existing_by_id.is_some() {
        existing_by_id
    } else {
        db::get_message_for_scope(
            &state.db_path,
            &target.id,
            &session.user_id,
            &message.filename,
        )
        .map_err(|error| error.to_string())?
        .map(|message| {
            let revision = db::get_message_sync_identity(
                &state.db_path,
                &target.id,
                &session.user_id,
                &message.filename,
            )
            .map_err(|error| error.to_string())?
            .map(|(_, revision)| revision)
            .unwrap_or_default();
            Ok::<_, String>((message, revision))
        })
        .transpose()?
    };
    if let Some((existing, revision)) = existing {
        if storage_transfer_message_matches_with_tags(
            &existing,
            source_message,
            &message.marked_tag_ids,
        ) {
            return db::mark_storage_transfer_item_state(
                &state.db_path,
                batch_id,
                &item.item_type,
                &item.source_key,
                "skipped",
                None,
                now_ms(),
            )
            .map_err(|error| error.to_string());
        }
        message_base_revision = revision;
    }
    let mut attachment_data = None;
    if let Some(attachment_id) = item.attachment_id.as_deref() {
        let (cache_path, size, sha256) = cache_storage_transfer_attachment(
            state,
            source,
            source_session,
            batch_id,
            item,
            source_message,
        )
        .await?;
        let local_dir = endpoint_files_dir(state, &target.id)
            .join(&session.user_id)
            .join("attachments")
            .join(attachment_id);
        fs::create_dir_all(&local_dir).map_err(|error| format!("创建导入附件目录失败: {error}"))?;
        let local_path = local_dir.join(&message.original_name);
        fs::copy(&cache_path, &local_path).map_err(|error| format!("保存导入附件失败: {error}"))?;
        let object_path = supabase_attachment_object_path(
            &session.user_id,
            target
                .supabase
                .as_ref()
                .map(|config| config.space_id.as_str())
                .unwrap_or_default(),
            attachment_id,
            &message.original_name,
        );
        let preview_object_path =
            media_preview::media_preview_kind(&message.original_name).map(|_| {
                supabase_attachment_preview_object_path(
                    &session.user_id,
                    target
                        .supabase
                        .as_ref()
                        .map(|config| config.space_id.as_str())
                        .unwrap_or_default(),
                    attachment_id,
                )
            });
        let preview_object_path = if let Some(preview_object_path) = preview_object_path {
            let preview_path = media_preview::isolated_preview_cache_path(
                &endpoint_files_dir(state, &target.id),
                &session.user_id,
                attachment_id,
                &preview_object_path,
            );
            match generate_preview_file(
                local_path.clone(),
                message.original_name.clone(),
                preview_path,
            )
            .await
            {
                Ok(true) => Some(preview_object_path),
                Ok(false) => None,
                Err(error) => {
                    log::warn!("generate transferred attachment preview failed: {error}");
                    None
                }
            }
        } else {
            None
        };
        message.size = size;
        message.local_path = Some(local_path.to_string_lossy().to_string());
        message.remote_path = Some(object_path.clone());
        message.file_hash = Some(sha256);
        attachment_data = Some((attachment_id.to_string(), object_path, preview_object_path));
    }
    let message_operation = outbox_operation_with_id(
        &item.message_operation_id,
        &target.id,
        &session.user_id,
        "message",
        &item.entity_id,
        "upsert",
        message_base_revision,
        supabase_message_payload(&message),
    )?;
    let attachment = if let Some((attachment_id, object_path, preview_object_path)) =
        attachment_data.as_ref()
    {
        let operation_id = item
            .attachment_operation_id
            .as_deref()
            .ok_or_else(|| "导入附件操作 ID 缺失".to_string())?;
        let payload = serde_json::json!({"messageId":item.entity_id,"originalName":message.original_name,
            "objectPath":object_path,"previewObjectPath":preview_object_path,"mimeType":attachment_mime_type(&message.original_name),
            "size":message.size,"sha256":message.file_hash,"uploadStatus":"uploaded"});
        let attachment_base_revision = db::get_attachment_sync_identity(
            &state.db_path,
            &target.id,
            &session.user_id,
            attachment_id,
        )
        .map_err(|error| error.to_string())?
        .map(|(_, revision)| revision)
        .unwrap_or_default();
        Some((
            attachment_id.clone(),
            object_path.clone(),
            preview_object_path.clone(),
            outbox_operation_with_id(
                operation_id,
                &target.id,
                &session.user_id,
                "attachment",
                attachment_id,
                "upsert",
                attachment_base_revision,
                payload,
            )?,
        ))
    } else {
        None
    };
    db::apply_imported_message(
        &state.db_path,
        batch_id,
        &item.source_key,
        &message,
        &message_operation,
        attachment.as_ref().map(
            |(attachment_id, object_path, preview_object_path, operation)| {
                (
                    attachment_id.as_str(),
                    object_path.as_str(),
                    preview_object_path.as_deref(),
                    Some(attachment_mime_type(&message.original_name)),
                    operation,
                )
            },
        ),
        now_ms(),
    )
    .map_err(|error| error.to_string())
}

fn storage_transfer_remote_field_matches(
    snapshot: &serde_json::Value,
    field: &str,
    expected: &serde_json::Value,
) -> bool {
    snapshot.get(field).unwrap_or(&serde_json::Value::Null) == expected
}

#[allow(clippy::too_many_arguments)]
async fn verify_storage_transfer_supabase_target(
    state: &AppState,
    target: &StorageProfile,
    session: &supabase_auth::SupabaseSession,
    batch_id: &str,
    source_messages: &HashMap<String, Message>,
    source_tags: &HashMap<String, MarkedTag>,
) -> Result<(), String> {
    let config = target
        .supabase
        .as_ref()
        .ok_or_else(|| "Supabase 存储空间配置不完整".to_string())?;
    let items = db::list_storage_transfer_items(&state.db_path, batch_id, &["applied", "skipped"])
        .map_err(|error| format!("读取待核验项目失败: {error}"))?;
    let expected_count = items.len();
    let mut verified_count = 0usize;

    for item in items {
        let verification = async {
            if item.item_type == "tag" {
                let source = source_tags
                    .get(&item.source_key)
                    .ok_or_else(|| format!("来源标签已不存在: {}", item.source_key))?;
                let snapshot = supabase_sync::fetch_entity_snapshot(
                    &state.http,
                    config,
                    session,
                    "tag",
                    &item.entity_id,
                )
                .await?
                .ok_or_else(|| format!("远端标签不存在: {}", item.entity_id))?;
                if !snapshot["deleted_at"].is_null()
                    || normalize_storage_transfer_tag_name(
                        snapshot["name"].as_str().unwrap_or_default(),
                    ) != normalize_storage_transfer_tag_name(&source.name)
                {
                    return Err(format!("远端标签内容不一致: {}", item.entity_id));
                }
                return Ok(());
            }

            let source = source_messages
                .get(&item.source_key)
                .ok_or_else(|| format!("来源消息已不存在: {}", item.source_key))?;
            let mapped_tag_ids = map_storage_transfer_tag_ids(
                &storage_transfer_tag_mapping_for_batch(state, batch_id)?,
                &source.marked_tag_ids,
            );
            let target_filename = storage_transfer_target_filename(source, &item.entity_id);
            let expected_size = if item.attachment_id.is_some() {
                item.total_bytes
            } else {
                source.size
            };
            let expected_file_hash = if item.attachment_id.is_some() {
                item.source_hash.as_ref()
            } else {
                source.file_hash.as_ref()
            };
            let message_snapshot = supabase_sync::fetch_entity_snapshot(
                &state.http,
                config,
                session,
                "message",
                &item.entity_id,
            )
            .await?
            .ok_or_else(|| format!("远端消息不存在: {}", item.entity_id))?;
            let expected_fields = [
                ("sender", serde_json::json!(source.sender)),
                ("timestamp_ms", serde_json::json!(source.timestamp_ms)),
                ("size", serde_json::json!(expected_size)),
                ("kind", serde_json::json!(source.kind)),
                ("original_name", serde_json::json!(source.original_name)),
                ("content", serde_json::json!(source.content)),
                ("format", serde_json::json!(source.format)),
                ("file_hash", serde_json::json!(expected_file_hash)),
                ("legacy_filename", serde_json::json!(target_filename)),
                ("marked", serde_json::json!(source.marked)),
                ("marked_tag_ids", serde_json::json!(mapped_tag_ids)),
                ("marked_pinned", serde_json::json!(source.marked_pinned)),
                ("marked_due_date", serde_json::json!(source.marked_due_date)),
                (
                    "transcript_source",
                    serde_json::json!(source.transcript_source),
                ),
                (
                    "source_audio_mime_type",
                    serde_json::json!(source.source_audio_mime_type),
                ),
                (
                    "transcript_raw_text",
                    serde_json::json!(source.transcript_raw_text),
                ),
            ];
            if !message_snapshot["deleted_at"].is_null()
                || expected_fields.iter().any(|(field, expected)| {
                    !storage_transfer_remote_field_matches(&message_snapshot, field, expected)
                })
            {
                return Err(format!("远端消息内容不一致: {}", item.entity_id));
            }

            if let Some(attachment_id) = item.attachment_id.as_deref() {
                let attachment_snapshot = supabase_sync::fetch_entity_snapshot(
                    &state.http,
                    config,
                    session,
                    "attachment",
                    attachment_id,
                )
                .await?
                .ok_or_else(|| format!("远端附件记录不存在: {attachment_id}"))?;
                let expected_hash = item
                    .source_hash
                    .as_deref()
                    .ok_or_else(|| format!("附件摘要缺失: {attachment_id}"))?;
                let object_path = attachment_snapshot["object_path"]
                    .as_str()
                    .ok_or_else(|| format!("远端附件 Storage 路径缺失: {attachment_id}"))?;
                if !attachment_snapshot["deleted_at"].is_null()
                    || attachment_snapshot["message_id"].as_str() != Some(item.entity_id.as_str())
                    || attachment_snapshot["size"].as_i64() != Some(item.total_bytes)
                    || attachment_snapshot["sha256"].as_str() != Some(expected_hash)
                {
                    return Err(format!("远端附件记录不一致: {attachment_id}"));
                }
                let mut download = supabase_sync::download_storage_object_stream(
                    &state.http,
                    config,
                    session,
                    object_path,
                )
                .await?;
                let mut size = 0i64;
                let mut hasher = Sha256::new();
                while let Some(chunk) = download.stream.next().await {
                    let chunk =
                        chunk.map_err(|error| format!("读取远端附件校验数据失败: {error}"))?;
                    size += chunk.len() as i64;
                    hasher.update(&chunk);
                }
                let actual_hash = format!("{:x}", hasher.finalize());
                if size != item.total_bytes || actual_hash != expected_hash {
                    return Err(format!(
                        "远端附件文件不一致: {attachment_id}（大小 {size}/{}, 摘要 {}）",
                        item.total_bytes, actual_hash
                    ));
                }
            }
            Ok(())
        }
        .await;

        if let Err(error) = verification {
            db::mark_storage_transfer_item_state(
                &state.db_path,
                batch_id,
                &item.item_type,
                &item.source_key,
                "error",
                Some(&error),
                now_ms(),
            )
            .map_err(|db_error| format!("记录目标核验失败状态失败: {db_error}"))?;
            return Err(error);
        }
        verified_count += 1;
    }

    if verified_count != expected_count {
        return Err(format!(
            "远端记录数量不一致: 已核验 {verified_count}/{expected_count}"
        ));
    }
    Ok(())
}

fn active_supabase_scope(
    state: &AppState,
) -> Result<(StorageProfile, supabase_auth::SupabaseSession), String> {
    let settings = current_settings(state)?;
    active_supabase_context(state, &settings)?
        .ok_or_else(|| "当前存储空间不是 Supabase".to_string())
}

#[tauri::command]
fn list_pending_operations(
    state: State<'_, AppState>,
) -> Result<Vec<PendingOperationResult>, String> {
    let (profile, session) = active_supabase_scope(&state)?;
    db::list_pending_operations(&state.db_path, &profile.id, &session.user_id)
        .map(|items| {
            items
                .into_iter()
                .map(|item| PendingOperationResult {
                    operation_id: item.operation_id,
                    entity_type: item.entity_type,
                    entity_id: item.entity_id,
                    action: item.action,
                    state: item.state,
                    attempt_count: item.attempt_count,
                    last_error: item.last_error,
                    created_at_ms: item.created_at_ms,
                })
                .collect()
        })
        .map_err(|error| error.to_string())
}

#[tauri::command]
fn list_sync_conflicts(state: State<'_, AppState>) -> Result<Vec<SyncConflictResult>, String> {
    let (profile, session) = active_supabase_scope(&state)?;
    db::list_sync_conflicts(&state.db_path, &profile.id, &session.user_id)
        .map(|items| {
            items
                .into_iter()
                .map(|item| SyncConflictResult {
                    id: item.id,
                    entity_type: item.entity_type,
                    entity_id: item.entity_id,
                    local_payload: serde_json::from_str(&item.local_payload_json)
                        .unwrap_or(serde_json::Value::Null),
                    remote_payload: item
                        .remote_payload_json
                        .and_then(|value| serde_json::from_str(&value).ok()),
                    local_revision: item.local_revision,
                    remote_revision: item.remote_revision,
                    created_at_ms: item.created_at_ms,
                })
                .collect()
        })
        .map_err(|error| error.to_string())
}

#[tauri::command]
async fn retry_pending_operation(
    state: State<'_, AppState>,
    operation_id: String,
) -> Result<SyncStatus, String> {
    let (profile, session) = active_supabase_scope(&state)?;
    if !db::retry_pending_operation(
        &state.db_path,
        &profile.id,
        &session.user_id,
        &operation_id,
        now_ms(),
    )
    .map_err(|error| error.to_string())?
    {
        return Err("待同步操作不存在或已处理".into());
    }
    let _ = sync_supabase_profile(&state, &profile, &session, true).await?;
    refresh_supabase_status(&state, None)
}

#[tauri::command]
async fn retry_all_pending_operations(state: State<'_, AppState>) -> Result<SyncStatus, String> {
    let (profile, session) = active_supabase_scope(&state)?;
    let _guard = state.sync_guard.lock().await;
    db::retry_all_pending_operations(&state.db_path, &profile.id, &session.user_id, now_ms())
        .map_err(|error| error.to_string())?;
    let _ = sync_supabase_profile(&state, &profile, &session, true).await?;
    refresh_supabase_status(&state, None)
}

#[tauri::command]
async fn resolve_sync_conflict(
    state: State<'_, AppState>,
    input: ResolveSyncConflictInput,
) -> Result<SyncStatus, String> {
    let (profile, session) = active_supabase_scope(&state)?;
    let conflict = db::get_sync_conflict(
        &state.db_path,
        input.conflict_id,
        &profile.id,
        &session.user_id,
    )
    .map_err(|error| error.to_string())?
    .ok_or_else(|| "冲突不存在或已处理".to_string())?;
    let resolved = match input.resolution.as_str() {
        "remote" => db::resolve_sync_conflict_use_remote(
            &state.db_path,
            input.conflict_id,
            &profile.id,
            &session.user_id,
            now_ms(),
        ),
        "local" => {
            let payload: serde_json::Value = serde_json::from_str(&conflict.local_payload_json)
                .map_err(|error| format!("冲突本机内容无效: {error}"))?;
            let operation = outbox_operation(
                &profile.id,
                &session.user_id,
                &conflict.entity_type,
                &conflict.entity_id,
                "upsert",
                conflict.remote_revision.unwrap_or(0),
                payload,
            )?;
            db::resolve_sync_conflict_keep_local(
                &state.db_path,
                input.conflict_id,
                &profile.id,
                &session.user_id,
                &operation,
                now_ms(),
            )
        }
        _ => return Err("冲突解决方式无效".into()),
    }
    .map_err(|error| error.to_string())?;
    if !resolved {
        return Err("冲突不存在或已处理".into());
    }
    if input.resolution == "local" {
        let _ = sync_supabase_profile(&state, &profile, &session, true).await?;
    }
    refresh_supabase_status(&state, None)
}

#[tauri::command]
async fn resolve_all_sync_conflicts(
    state: State<'_, AppState>,
    input: ResolveAllSyncConflictsInput,
) -> Result<ResolveAllSyncConflictsResult, String> {
    resolve_all_sync_conflicts_impl(&state, input).await
}

async fn resolve_all_sync_conflicts_impl(
    state: &AppState,
    input: ResolveAllSyncConflictsInput,
) -> Result<ResolveAllSyncConflictsResult, String> {
    let (profile, session) = active_supabase_scope(state)?;
    let _guard = state.sync_guard.lock().await;
    let conflicts = db::list_sync_conflicts(&state.db_path, &profile.id, &session.user_id)
        .map_err(|error| error.to_string())?;
    let found = conflicts.len();
    if found == 0 {
        let status = refresh_supabase_status(state, None)?;
        return Ok(ResolveAllSyncConflictsResult {
            found: 0,
            resolved: 0,
            remaining: status.conflict_count,
            sync_error: None,
            status,
        });
    }
    let conflict_ids = conflicts
        .iter()
        .map(|conflict| conflict.id)
        .collect::<Vec<_>>();
    let mut sync_error = None;
    let resolved = match input.resolution.as_str() {
        "remote" => db::resolve_all_sync_conflicts_use_remote(
            &state.db_path,
            &profile.id,
            &session.user_id,
            now_ms(),
        )
        .map_err(|error| format!("批量采用云端内容失败: {error}"))?,
        "local" => {
            let mut latest = HashMap::new();
            for conflict in conflicts {
                latest.insert(
                    (conflict.entity_type.clone(), conflict.entity_id.clone()),
                    conflict,
                );
            }
            let operations = latest
                .into_values()
                .map(|conflict| {
                    let payload: serde_json::Value =
                        serde_json::from_str(&conflict.local_payload_json)
                            .map_err(|error| format!("冲突本机内容无效: {error}"))?;
                    outbox_operation(
                        &profile.id,
                        &session.user_id,
                        &conflict.entity_type,
                        &conflict.entity_id,
                        "upsert",
                        conflict.remote_revision.unwrap_or(0),
                        payload,
                    )
                })
                .collect::<Result<Vec<_>, String>>()?;
            let resolved = db::resolve_all_sync_conflicts_keep_local(
                &state.db_path,
                &profile.id,
                &session.user_id,
                &conflict_ids,
                &operations,
                now_ms(),
            )
            .map_err(|error| format!("批量保留本机内容失败: {error}"))?;
            if let Err(error) = sync_supabase_profile(state, &profile, &session, true).await {
                sync_error = Some(error);
            }
            resolved
        }
        _ => return Err("冲突解决方式无效".into()),
    };
    let status = refresh_supabase_status(state, None)?;
    Ok(ResolveAllSyncConflictsResult {
        found,
        resolved,
        remaining: status.conflict_count,
        sync_error,
        status,
    })
}

async fn push_supabase_outbox(
    state: &AppState,
    profile: &StorageProfile,
    session: &supabase_auth::SupabaseSession,
    manual: bool,
    import_batch_id: Option<&str>,
) -> Result<usize, String> {
    db::recover_all_outbox_claims(&state.db_path, now_ms())
        .map_err(|error| format!("恢复 Supabase 同步任务失败: {error}"))?;
    db::repair_stale_attachment_dependencies(
        &state.db_path,
        &profile.id,
        &session.user_id,
        now_ms(),
    )
    .map_err(|error| format!("修复附件同步依赖失败: {error}"))?;
    let config = profile
        .supabase
        .as_ref()
        .ok_or_else(|| "Supabase 存储空间配置不完整".to_string())?;
    supabase_sync::validate_space_access(&state.http, config, session).await?;
    let worker_id = uuid::Uuid::new_v4().to_string();
    let mut applied = 0;
    loop {
        let claimed = if let Some(batch_id) = import_batch_id {
            db::claim_storage_import_outbox_operations(
                &state.db_path,
                &profile.id,
                &session.user_id,
                batch_id,
                &worker_id,
                now_ms(),
                60_000,
                1,
            )
        } else {
            db::claim_outbox_operations(
                &state.db_path,
                &profile.id,
                &session.user_id,
                &worker_id,
                now_ms(),
                60_000,
                1,
                manual,
            )
        }
        .map_err(|error| format!("领取 Supabase 同步任务失败: {error}"))?;
        let Some(mut operation) = claimed.into_iter().next() else {
            break;
        };
        if operation.entity_type == "attachment" && operation.action == "upsert" {
            let upload_result = async {
                let mut attachment = db::get_attachment_sync_record(
                    &state.db_path,
                    &profile.id,
                    &session.user_id,
                    &operation.entity_id,
                )
                .map_err(|error| format!("读取本地附件状态失败: {error}"))?
                .ok_or_else(|| "附件本地原件不存在".to_string())?;
                let local_path = attachment
                    .local_path
                    .clone()
                    .filter(|value| !value.trim().is_empty());
                let mut object_path = attachment.object_path.clone().unwrap_or_default();
                let expected_prefix = format!(
                    "{}/{}/{}/",
                    session.user_id, config.space_id, operation.entity_id
                );
                if !object_path.starts_with(&expected_prefix) {
                    object_path = supabase_attachment_object_path(
                        &session.user_id,
                        &config.space_id,
                        &operation.entity_id,
                        &attachment.original_name,
                    );
                    let mut payload: serde_json::Value =
                        serde_json::from_str(&operation.payload_json)
                            .map_err(|error| format!("修复附件同步信息失败: {error}"))?;
                    payload["objectPath"] = serde_json::Value::String(object_path.clone());
                    let payload_json = serde_json::to_string(&payload)
                        .map_err(|error| format!("修复附件同步信息失败: {error}"))?;
                    let payload_hash = format!("{:x}", Sha256::digest(payload_json.as_bytes()));
                    let repaired = db::repair_claimed_attachment_object_path(
                        &state.db_path,
                        &operation.operation_id,
                        &worker_id,
                        &profile.id,
                        &session.user_id,
                        &operation.entity_id,
                        &object_path,
                        &payload_json,
                        &payload_hash,
                        now_ms(),
                    )
                    .map_err(|error| format!("修复附件 Storage 路径失败: {error}"))?;
                    if !repaired {
                        return Err(
                            "修复附件 Storage 路径失败：同步任务已被其他进程接管".to_string()
                        );
                    }
                    operation.payload_json = payload_json;
                    operation.payload_hash = payload_hash;
                    attachment.object_path = Some(object_path.clone());
                }
                if attachment.upload_state != "uploaded" {
                    let local_path = local_path
                        .as_deref()
                        .ok_or_else(|| "附件本地原件不存在".to_string())?;
                    supabase_sync::upload_storage_object_path(
                        &state.http,
                        config,
                        session,
                        &object_path,
                        Path::new(local_path),
                        attachment
                            .mime_type
                            .as_deref()
                            .unwrap_or("application/octet-stream"),
                        attachment.sha256.as_deref(),
                    )
                    .await?;
                }

                let preview_already_published = attachment.upload_state == "uploaded"
                    && attachment
                        .preview_object_path
                        .as_deref()
                        .is_some_and(|value| !value.trim().is_empty());
                if !preview_already_published
                    && media_preview::media_preview_kind(&attachment.original_name).is_some()
                {
                    let preview_object_path = supabase_attachment_preview_object_path(
                        &session.user_id,
                        &config.space_id,
                        &operation.entity_id,
                    );
                    let preview_path = media_preview::isolated_preview_cache_path(
                        &endpoint_files_dir(state, &profile.id),
                        &session.user_id,
                        &operation.entity_id,
                        &preview_object_path,
                    );
                    let generated = if preview_path.is_file() {
                        Ok(true)
                    } else {
                        generate_preview_file(
                            PathBuf::from(
                                local_path
                                    .as_deref()
                                    .ok_or_else(|| "附件本地原件不存在".to_string())?,
                            ),
                            attachment.original_name.clone(),
                            preview_path.clone(),
                        )
                        .await
                    };
                    match generated {
                        Ok(true) => {
                            if let Err(error) = supabase_sync::upload_storage_object_path(
                                &state.http,
                                config,
                                session,
                                &preview_object_path,
                                &preview_path,
                                "image/jpeg",
                                None,
                            )
                            .await
                            {
                                log::warn!(
                                    "upload Supabase preview failed for {}: {}",
                                    operation.entity_id,
                                    error
                                );
                            } else {
                                let mut payload: serde_json::Value = serde_json::from_str(
                                    &operation.payload_json,
                                )
                                .map_err(|error| format!("修复附件预览同步信息失败: {error}"))?;
                                payload["previewObjectPath"] =
                                    serde_json::Value::String(preview_object_path.clone());
                                let payload_json =
                                    serde_json::to_string(&payload).map_err(|error| {
                                        format!("修复附件预览同步信息失败: {error}")
                                    })?;
                                let payload_hash =
                                    format!("{:x}", Sha256::digest(payload_json.as_bytes()));
                                let repaired = db::repair_claimed_attachment_preview_path(
                                    &state.db_path,
                                    &operation.operation_id,
                                    &worker_id,
                                    &profile.id,
                                    &session.user_id,
                                    &operation.entity_id,
                                    Some(&preview_object_path),
                                    &payload_json,
                                    &payload_hash,
                                    None,
                                    now_ms(),
                                )
                                .map_err(|error| {
                                    format!("修复附件预览 Storage 路径失败: {error}")
                                })?;
                                if !repaired {
                                    return Err(
                                        "修复附件预览 Storage 路径失败：同步任务已被其他进程接管"
                                            .to_string(),
                                    );
                                }
                                operation.payload_json = payload_json;
                                operation.payload_hash = payload_hash;
                            }
                        }
                        Ok(false) => {}
                        Err(error) => log::warn!(
                            "generate Supabase preview failed for {}: {}",
                            operation.entity_id,
                            error
                        ),
                    }
                }
                Ok(())
            }
            .await;
            if let Err(error) = upload_result {
                let retry_at = now_ms() + db::outbox_retry_delay_ms(operation.attempt_count);
                db::release_outbox_operation(
                    &state.db_path,
                    &operation.operation_id,
                    &worker_id,
                    retry_at,
                    &error,
                    now_ms(),
                )
                .map_err(|db_error| db_error.to_string())?;
                if import_batch_id.is_some() {
                    db::mark_storage_import_operation_error(
                        &state.db_path,
                        &operation.operation_id,
                        &error,
                        now_ms(),
                    )
                    .map_err(|db_error| db_error.to_string())?;
                }
                return Err(error);
            }
        }
        match supabase_sync::push_operation(&state.http, config, session, &operation).await {
            Ok(supabase_sync::PushResult::Applied { revision, .. }) => {
                db::apply_outbox_success(
                    &state.db_path,
                    &operation,
                    &worker_id,
                    revision,
                    now_ms(),
                )
                .map_err(|error| format!("确认 Supabase 同步任务失败: {error}"))?;
                applied += 1;
            }
            Ok(supabase_sync::PushResult::Missing) if operation.action == "delete" => {
                db::apply_outbox_success(
                    &state.db_path,
                    &operation,
                    &worker_id,
                    operation.base_revision,
                    now_ms(),
                )
                .map_err(|error| format!("确认 Supabase 删除任务失败: {error}"))?;
                applied += 1;
            }
            Ok(supabase_sync::PushResult::Conflict {
                remote_revision,
                remote,
            }) => {
                let remote_payload = serde_json::to_string(&remote)
                    .map_err(|error| format!("保存远端冲突版本失败: {error}"))?;
                db::record_outbox_conflict(
                    &state.db_path,
                    &operation,
                    &worker_id,
                    remote_revision,
                    Some(&remote_payload),
                    now_ms(),
                )
                .map_err(|error| format!("记录 Supabase 冲突失败: {error}"))?;
                break;
            }
            Ok(supabase_sync::PushResult::Missing) => {
                let error = "远端实体不存在";
                let retry_at = now_ms() + db::outbox_retry_delay_ms(operation.attempt_count);
                db::release_outbox_operation(
                    &state.db_path,
                    &operation.operation_id,
                    &worker_id,
                    retry_at,
                    error,
                    now_ms(),
                )
                .map_err(|db_error| format!("恢复 Supabase 同步任务失败: {db_error}"))?;
                if import_batch_id.is_some() {
                    db::mark_storage_import_operation_error(
                        &state.db_path,
                        &operation.operation_id,
                        error,
                        now_ms(),
                    )
                    .map_err(|db_error| db_error.to_string())?;
                }
                return Err(error.to_string());
            }
            Err(error) => {
                if operation.entity_type == "attachment"
                    && operation.action == "upsert"
                    && error.contains("MESSAGE_NOT_FOUND")
                {
                    let payload: serde_json::Value = serde_json::from_str(&operation.payload_json)
                        .map_err(|parse_error| format!("解析附件关联消息失败: {parse_error}"))?;
                    let message_id = payload["messageId"]
                        .as_str()
                        .ok_or_else(|| "附件关联消息 ID 缺失".to_string())?;
                    let (message, _) = db::get_message_by_id_for_scope(
                        &state.db_path,
                        &profile.id,
                        &session.user_id,
                        message_id,
                    )
                    .map_err(|db_error| format!("读取待恢复消息失败: {db_error}"))?
                    .ok_or_else(|| "附件关联消息的本地记录不存在".to_string())?;
                    let message_operation = outbox_operation(
                        &profile.id,
                        &session.user_id,
                        "message",
                        message_id,
                        "upsert",
                        0,
                        supabase_message_payload(&message),
                    )?;
                    if db::repair_missing_attachment_message(
                        &state.db_path,
                        &operation.operation_id,
                        &worker_id,
                        &message_operation,
                        now_ms(),
                    )
                    .map_err(|db_error| format!("恢复附件关联消息失败: {db_error}"))?
                    {
                        continue;
                    }
                }
                if operation.entity_type == "tag"
                    && operation.action == "upsert"
                    && error.contains("tags_active_name_idx")
                {
                    let payload: serde_json::Value = serde_json::from_str(&operation.payload_json)
                        .map_err(|parse_error| format!("解析重复标签信息失败: {parse_error}"))?;
                    let tag_name = payload["name"]
                        .as_str()
                        .ok_or_else(|| "重复标签名称缺失".to_string())?;
                    if let Some(snapshot) =
                        supabase_sync::fetch_tag_by_name(&state.http, config, session, tag_name)
                            .await?
                    {
                        if let (Some(id), Some(name), Some(revision)) = (
                            snapshot["id"].as_str(),
                            snapshot["name"].as_str(),
                            snapshot["revision"].as_i64(),
                        ) {
                            db::reconcile_duplicate_tag_operation(
                                &state.db_path,
                                &operation,
                                &MarkedTag {
                                    id: id.to_string(),
                                    name: name.to_string(),
                                },
                                revision,
                                &worker_id,
                                now_ms(),
                            )
                            .map_err(|db_error| {
                                format!("合并 Supabase 同名标签失败: {db_error}")
                            })?;
                            continue;
                        }
                    }
                }
                let retry_at = now_ms() + db::outbox_retry_delay_ms(operation.attempt_count);
                db::release_outbox_operation(
                    &state.db_path,
                    &operation.operation_id,
                    &worker_id,
                    retry_at,
                    &error,
                    now_ms(),
                )
                .map_err(|db_error| format!("恢复 Supabase 同步任务失败: {db_error}"))?;
                if import_batch_id.is_some() {
                    db::mark_storage_import_operation_error(
                        &state.db_path,
                        &operation.operation_id,
                        &error,
                        now_ms(),
                    )
                    .map_err(|db_error| db_error.to_string())?;
                }
                return Err(error);
            }
        }
    }
    Ok(applied)
}

async fn pull_supabase_changes(
    state: &AppState,
    profile: &StorageProfile,
    session: &supabase_auth::SupabaseSession,
) -> Result<usize, String> {
    let config = profile
        .supabase
        .as_ref()
        .ok_or_else(|| "Supabase 存储空间配置不完整".to_string())?;
    let mut checkpoint = db::get_sync_checkpoint(&state.db_path, &profile.id, &session.user_id)
        .map_err(|error| format!("读取 Supabase 同步游标失败: {error}"))?;
    let mut applied = 0;
    loop {
        let remote =
            supabase_sync::pull_changes(&state.http, config, session, checkpoint, 200).await?;
        if remote.is_empty() {
            break;
        }
        let mut changes = Vec::with_capacity(remote.len());
        for change in &remote {
            let snapshot = supabase_sync::fetch_entity_snapshot(
                &state.http,
                config,
                session,
                &change.entity_type,
                &change.entity_id,
            )
            .await?;
            changes.push(db::PulledChange {
                change_seq: change.change_seq,
                entity_type: change.entity_type.clone(),
                entity_id: change.entity_id.clone(),
                change_type: change.change_type.clone(),
                revision: change.revision,
                snapshot,
            });
        }
        let next_checkpoint = changes
            .last()
            .map(|change| change.change_seq)
            .unwrap_or(checkpoint);
        db::apply_pulled_changes(
            &state.db_path,
            &profile.id,
            &session.user_id,
            &changes,
            next_checkpoint,
            now_ms(),
        )
        .map_err(|error| format!("应用 Supabase 增量变化失败: {error}"))?;
        checkpoint = next_checkpoint;
        applied += changes.len();
        if remote.len() < 200 {
            break;
        }
    }
    Ok(applied)
}

async fn refresh_supabase_recent_message_page(
    state: &AppState,
    profile: &StorageProfile,
    session: &supabase_auth::SupabaseSession,
    limit: usize,
) -> Result<usize, String> {
    let config = profile
        .supabase
        .as_ref()
        .ok_or_else(|| "Supabase 存储空间配置不完整".to_string())?;
    let page = supabase_sync::fetch_message_page(&state.http, config, session, None, limit).await?;
    let count = page.messages.len();
    db::apply_supabase_message_page(
        &state.db_path,
        &profile.id,
        &session.user_id,
        &page.messages,
        &page.tags,
        &page.attachments,
        page.has_more,
        false,
        now_ms(),
    )
    .map_err(|error| format!("刷新 Supabase 最近消息失败: {error}"))?;
    Ok(count)
}

async fn sync_supabase_profile(
    state: &AppState,
    profile: &StorageProfile,
    session: &supabase_auth::SupabaseSession,
    manual: bool,
) -> Result<(usize, usize), String> {
    let pushed = push_supabase_outbox(state, profile, session, manual, None).await?;
    let pulled = pull_supabase_changes(state, profile, session).await?;
    let _ = cleanup_supabase_orphan_objects(state, profile, session).await;
    Ok((pushed, pulled))
}

async fn cleanup_supabase_orphan_objects(
    state: &AppState,
    profile: &StorageProfile,
    session: &supabase_auth::SupabaseSession,
) -> Result<usize, String> {
    const GRACE_MS: i64 = 24 * 60 * 60 * 1000;
    const LIMIT: usize = 50;
    let candidates = db::list_orphan_attachment_candidates(
        &state.db_path,
        &profile.id,
        &session.user_id,
        now_ms() - GRACE_MS,
        LIMIT,
    )
    .map_err(|error| error.to_string())?;
    if candidates.is_empty() {
        return Ok(0);
    }
    let config = profile
        .supabase
        .as_ref()
        .ok_or_else(|| "Supabase 配置不完整".to_string())?;
    let paths = candidates
        .iter()
        .flat_map(|candidate| {
            std::iter::once(candidate.object_path.clone())
                .chain(candidate.preview_object_path.clone())
        })
        .collect::<Vec<_>>();
    supabase_sync::delete_storage_objects(&state.http, config, session, &paths).await?;
    for candidate in &candidates {
        db::mark_attachment_object_cleaned(
            &state.db_path,
            &profile.id,
            &session.user_id,
            &candidate.attachment_id,
            now_ms(),
        )
        .map_err(|error| error.to_string())?;
    }
    Ok(candidates.len())
}

fn supabase_send_result(profile_id: &str, message: &DbMessage) -> SendMessageResult {
    SendMessageResult {
        marked_tag_ids: message.marked_tag_ids.clone(),
        filename: message.filename.clone(),
        original_name: message.original_name.clone(),
        endpoint_id: profile_id.to_string(),
        transcript_source: message.transcript_source.clone(),
        source_audio_mime_type: message.source_audio_mime_type.clone(),
        transcript_text: message
            .transcript_source
            .as_ref()
            .and_then(|_| message.content.clone()),
        transcript_raw_text: message.transcript_raw_text.clone(),
    }
}

#[derive(Clone)]
struct IntegrationTargetContext {
    generation: Option<u64>,
    provider: storage_provider::ProviderConfig,
    owner_scope: String,
    session: Option<supabase_auth::SupabaseSession>,
}

impl IntegrationTargetContext {
    fn profile_id(&self) -> &str {
        self.provider.profile_id()
    }

    fn provider_kind(&self) -> &'static str {
        self.provider.provider_kind()
    }
}

#[derive(Clone)]
struct ExternalSourceIdentity {
    kind: String,
    channel_id: String,
    message_id: String,
}

fn external_source_uuid(source: &ExternalSourceIdentity, entity_kind: &str) -> String {
    uuid::Uuid::new_v5(
        &uuid::Uuid::NAMESPACE_URL,
        format!(
            "transfer-genie:{entity_kind}:{}:{}:{}",
            source.kind, source.channel_id, source.message_id
        )
        .as_bytes(),
    )
    .to_string()
}

fn external_source_filename(
    sender: &str,
    original_name: &str,
    timestamp_ms: i64,
    source: &ExternalSourceIdentity,
) -> String {
    let nonce = &external_source_uuid(source, "filename")[..8];
    format!(
        "{}__{}__{}__{}",
        timestamp_ms,
        encode_component(sender),
        nonce,
        encode_component(original_name)
    )
}

fn integration_context_matches(state: &AppState, context: &IntegrationTargetContext) -> bool {
    if let Some(generation) = context.generation {
        if state
            .telegram_bridge_generation
            .load(std::sync::atomic::Ordering::SeqCst)
            != generation
        {
            return false;
        }
    }
    let current = current_settings(state)
        .ok()
        .and_then(|settings| storage_provider::resolve_active_provider(&settings).ok());
    let Some(current) = current else {
        return false;
    };
    if current.profile_id() != context.profile_id()
        || current.provider_kind() != context.provider_kind()
    {
        return false;
    }
    match (&context.provider, &current, context.session.as_ref()) {
        (
            storage_provider::ProviderConfig::Webdav(expected),
            storage_provider::ProviderConfig::Webdav(actual),
            _,
        ) => expected == actual,
        (
            storage_provider::ProviderConfig::Supabase(expected),
            storage_provider::ProviderConfig::Supabase(actual),
            Some(session),
        ) => {
            expected == actual
                && context.owner_scope == session.user_id
                && state
                    .supabase_sessions
                    .lock()
                    .ok()
                    .and_then(|sessions| sessions.get(&expected.id).cloned())
                    .is_some_and(|current| current.user_id == session.user_id)
        }
        _ => false,
    }
}

fn ensure_integration_context(
    state: &AppState,
    context: &IntegrationTargetContext,
) -> Result<(), String> {
    integration_context_matches(state, context)
        .then_some(())
        .ok_or_else(|| "目标存储空间已切换，已拒绝旧任务写入".to_string())
}

fn resolve_send_target_context(
    state: &AppState,
    settings: &Settings,
) -> Result<IntegrationTargetContext, String> {
    let provider = storage_provider::resolve_active_provider(settings)?;
    match provider {
        storage_provider::ProviderConfig::Webdav(endpoint) => Ok(IntegrationTargetContext {
            generation: None,
            provider: storage_provider::ProviderConfig::Webdav(endpoint),
            owner_scope: String::new(),
            session: None,
        }),
        storage_provider::ProviderConfig::Supabase(profile) => {
            let config = profile
                .supabase
                .as_ref()
                .ok_or_else(|| "Supabase 存储空间配置不完整".to_string())?;
            if config.space_id.trim().is_empty() {
                return Err("当前 Supabase 存储空间尚未完成绑定".to_string());
            }
            let session = state
                .supabase_sessions
                .lock()
                .map_err(|_| "读取 Supabase 会话失败".to_string())?
                .get(&profile.id)
                .cloned()
                .ok_or_else(|| "请先登录当前 Supabase 存储空间".to_string())?;
            Ok(IntegrationTargetContext {
                generation: None,
                owner_scope: session.user_id.clone(),
                provider: storage_provider::ProviderConfig::Supabase(profile),
                session: Some(session),
            })
        }
    }
}

async fn ingest_external_text(
    state: &AppState,
    context: &IntegrationTargetContext,
    sender: &str,
    timestamp_ms: i64,
    text: String,
    source: ExternalSourceIdentity,
) -> Result<(), String> {
    ensure_integration_context(state, context)?;
    if db::find_message_by_source_for_scope(
        &state.db_path,
        context.profile_id(),
        &context.owner_scope,
        &source.kind,
        &source.channel_id,
        &source.message_id,
    )
    .map_err(|error| error.to_string())?
    .is_some()
    {
        return Ok(());
    }
    let filename = external_source_filename(sender, "message.txt", timestamp_ms, &source);
    let remote_path = message_remote_path(&filename, timestamp_ms);
    let message = DbMessage {
        endpoint_id: context.profile_id().to_string(),
        filename: filename.clone(),
        sender: sender.to_string(),
        timestamp_ms,
        size: text.len() as i64,
        kind: "text".into(),
        original_name: "message.txt".into(),
        etag: None,
        mtime: None,
        content: Some(text.clone()),
        local_path: None,
        remote_path: None,
        file_hash: None,
        marked: false,
        marked_tag_ids: Vec::new(),
        marked_pinned: false,
        marked_due_date: None,
        format: "text".into(),
        transcript_source: None,
        source_audio_mime_type: None,
        transcript_raw_text: None,
        source_kind: Some(source.kind.clone()),
        source_channel_id: Some(source.channel_id.clone()),
        source_message_id: Some(source.message_id.clone()),
    };
    match &context.provider {
        storage_provider::ProviderConfig::Supabase(profile) => {
            let session = context
                .session
                .as_ref()
                .ok_or_else(|| "请先登录当前 Supabase 存储空间".to_string())?;
            let message_id = external_source_uuid(&source, "message");
            let operation = outbox_operation(
                &profile.id,
                &session.user_id,
                "message",
                &message_id,
                "upsert",
                0,
                supabase_message_payload(&message),
            )?;
            db::save_message_and_enqueue(&state.db_path, &message, &operation)
                .map_err(|error| format!("保存 Telegram Supabase 文本失败: {error}"))?;
            notify_supabase_outbox_pending(state);
        }
        storage_provider::ProviderConfig::Webdav(endpoint) => {
            webdav::upload_file_ensuring_parent(
                &state.http,
                endpoint,
                &remote_path,
                text.into_bytes(),
            )
            .await?;
            ensure_integration_context(state, context)?;
            let mut message = message;
            message.remote_path = Some(remote_path);
            db::upsert_message(&state.db_path, &message).map_err(|error| error.to_string())?;
            crate::history::upsert_history_entries(
                &state.http,
                endpoint,
                vec![message_to_history(&message)],
            )
            .await?;
        }
    }
    Ok(())
}

async fn ingest_external_file(
    state: &AppState,
    context: &IntegrationTargetContext,
    sender: &str,
    timestamp_ms: i64,
    original_name: String,
    bytes: Vec<u8>,
    source: ExternalSourceIdentity,
) -> Result<(), String> {
    ensure_integration_context(state, context)?;
    if db::find_message_by_source_for_scope(
        &state.db_path,
        context.profile_id(),
        &context.owner_scope,
        &source.kind,
        &source.channel_id,
        &source.message_id,
    )
    .map_err(|error| error.to_string())?
    .is_some()
    {
        return Ok(());
    }
    let filename = external_source_filename(sender, &original_name, timestamp_ms, &source);
    let remote_path = message_remote_path(&filename, timestamp_ms);
    let file_hash = format!("{:x}", Sha256::digest(&bytes));
    match &context.provider {
        storage_provider::ProviderConfig::Supabase(profile) => {
            let session = context
                .session
                .as_ref()
                .ok_or_else(|| "请先登录当前 Supabase 存储空间".to_string())?;
            let message_id = external_source_uuid(&source, "message");
            let attachment_id = external_source_uuid(&source, "attachment");
            let local_dir = endpoint_files_dir(state, &profile.id)
                .join(&session.user_id)
                .join("attachments")
                .join(&attachment_id);
            fs::create_dir_all(&local_dir)
                .map_err(|error| format!("创建 Telegram 附件缓存失败: {error}"))?;
            let local_path = local_dir.join(&original_name);
            fs::write(&local_path, &bytes)
                .map_err(|error| format!("保存 Telegram 附件原件失败: {error}"))?;
            ensure_integration_context(state, context)?;
            let config = profile
                .supabase
                .as_ref()
                .ok_or_else(|| "Supabase 存储空间配置不完整".to_string())?;
            let object_path = supabase_attachment_object_path(
                &session.user_id,
                &config.space_id,
                &attachment_id,
                &original_name,
            );
            let message = DbMessage {
                endpoint_id: profile.id.clone(),
                filename,
                sender: sender.to_string(),
                timestamp_ms,
                size: bytes.len() as i64,
                kind: "file".into(),
                original_name: original_name.clone(),
                etag: None,
                mtime: None,
                content: None,
                local_path: Some(local_path.to_string_lossy().to_string()),
                remote_path: Some(object_path.clone()),
                file_hash: Some(file_hash.clone()),
                marked: false,
                marked_tag_ids: Vec::new(),
                marked_pinned: false,
                marked_due_date: None,
                format: "text".into(),
                transcript_source: None,
                source_audio_mime_type: None,
                transcript_raw_text: None,
                source_kind: Some(source.kind.clone()),
                source_channel_id: Some(source.channel_id.clone()),
                source_message_id: Some(source.message_id.clone()),
            };
            let message_operation = outbox_operation(
                &profile.id,
                &session.user_id,
                "message",
                &message_id,
                "upsert",
                0,
                supabase_message_payload(&message),
            )?;
            let mime_type = attachment_mime_type(&original_name);
            let attachment_operation = outbox_operation(
                &profile.id,
                &session.user_id,
                "attachment",
                &attachment_id,
                "upsert",
                0,
                serde_json::json!({
                    "messageId":message_id,"originalName":original_name,"objectPath":object_path,
                    "previewObjectPath":null,"mimeType":mime_type,"size":bytes.len(),"sha256":file_hash,"uploadStatus":"uploaded"
                }),
            )?;
            db::save_file_message_and_enqueue(
                &state.db_path,
                &message,
                &message_operation,
                &attachment_id,
                &object_path,
                Some(mime_type),
                &attachment_operation,
            )
            .map_err(|error| format!("保存 Telegram Supabase 附件失败: {error}"))?;
            notify_supabase_outbox_pending(state);
        }
        storage_provider::ProviderConfig::Webdav(endpoint) => {
            let local_dir = endpoint_files_dir(state, &endpoint.id);
            fs::create_dir_all(&local_dir).map_err(|error| error.to_string())?;
            let local_path = local_dir.join(&filename);
            fs::write(&local_path, &bytes).map_err(|error| error.to_string())?;
            ensure_integration_context(state, context)?;
            webdav::upload_file_ensuring_parent(&state.http, endpoint, &remote_path, bytes.clone())
                .await?;
            ensure_integration_context(state, context)?;
            let message = DbMessage {
                endpoint_id: endpoint.id.clone(),
                filename,
                sender: sender.to_string(),
                timestamp_ms,
                size: bytes.len() as i64,
                kind: "file".into(),
                original_name,
                etag: None,
                mtime: None,
                content: None,
                local_path: Some(local_path.to_string_lossy().to_string()),
                remote_path: Some(remote_path),
                file_hash: Some(file_hash),
                marked: false,
                marked_tag_ids: Vec::new(),
                marked_pinned: false,
                marked_due_date: None,
                format: "text".into(),
                transcript_source: None,
                source_audio_mime_type: None,
                transcript_raw_text: None,
                source_kind: Some(source.kind),
                source_channel_id: Some(source.channel_id),
                source_message_id: Some(source.message_id),
            };
            db::upsert_message(&state.db_path, &message).map_err(|error| error.to_string())?;
            crate::history::upsert_history_entries(
                &state.http,
                endpoint,
                vec![message_to_history(&message)],
            )
            .await?;
        }
    }
    Ok(())
}

async fn telegram_outbound_file_bytes(
    state: &AppState,
    context: &IntegrationTargetContext,
    message: &Message,
) -> Result<Vec<u8>, String> {
    if let Some(path) = message
        .local_path
        .as_deref()
        .map(Path::new)
        .filter(|path| path.is_file())
    {
        return fs::read(path).map_err(|error| format!("读取 Telegram 待发送附件失败: {error}"));
    }
    match &context.provider {
        storage_provider::ProviderConfig::Webdav(endpoint) => {
            let remote_path = resolved_remote_path(
                message.remote_path.as_deref(),
                &message.filename,
                Some(message.timestamp_ms),
            );
            webdav::download_file(&state.http, endpoint, &remote_path).await
        }
        storage_provider::ProviderConfig::Supabase(profile) => {
            let session = context
                .session
                .as_ref()
                .ok_or_else(|| "请先登录当前 Supabase 存储空间".to_string())?;
            let config = profile
                .supabase
                .as_ref()
                .ok_or_else(|| "Supabase 存储空间配置不完整".to_string())?;
            let object_path = message
                .remote_path
                .as_deref()
                .ok_or_else(|| "Supabase 附件尚未上传".to_string())?;
            supabase_sync::download_storage_object(&state.http, config, session, object_path).await
        }
    }
}

async fn resolve_telegram_integration_context(
    state: &AppState,
    generation: u64,
) -> Result<IntegrationTargetContext, String> {
    let settings = current_settings(state)?;
    let provider = storage_provider::resolve_active_provider(&settings)?;
    match provider {
        storage_provider::ProviderConfig::Webdav(endpoint) => {
            webdav::ensure_directory(&state.http, &endpoint, "files").await?;
            Ok(IntegrationTargetContext {
                generation: Some(generation),
                provider: storage_provider::ProviderConfig::Webdav(endpoint),
                owner_scope: String::new(),
                session: None,
            })
        }
        storage_provider::ProviderConfig::Supabase(profile) => {
            let config = profile
                .supabase
                .as_ref()
                .ok_or_else(|| "Supabase 存储空间配置不完整".to_string())?;
            if config.space_id.trim().is_empty() {
                return Err("当前 Supabase 存储空间尚未完成绑定".to_string());
            }
            let session = verified_supabase_session(state, &profile.id)
                .await
                .map_err(|error| error.message)?
                .ok_or_else(|| "请先登录当前 Supabase 存储空间".to_string())?;
            supabase_sync::validate_space_access(&state.http, config, &session).await?;
            Ok(IntegrationTargetContext {
                generation: Some(generation),
                owner_scope: session.user_id.clone(),
                provider: storage_provider::ProviderConfig::Supabase(profile),
                session: Some(session),
            })
        }
    }
}

fn telegram_managed_config(
    settings: &Settings,
) -> Result<telegram_bridge::ManagedTelegramConfig, String> {
    let telegram = &settings.telegram;
    let bot_token = telegram.bot_token.trim();
    if bot_token.is_empty() {
        return Err("请先填写 Telegram Bot Token".to_string());
    }
    let allowed_chat_id = telegram
        .chat_id
        .trim()
        .parse::<i64>()
        .map_err(|_| "Telegram Chat ID 格式无效".to_string())?;
    if allowed_chat_id == 0 {
        return Err("Telegram Chat ID 不能为 0".to_string());
    }
    Ok(telegram_bridge::ManagedTelegramConfig {
        device_sender_name: settings.sender_name.clone(),
        telegram_sender_name: telegram.sender_name.clone(),
        bot_token: bot_token.to_string(),
        allowed_chat_id,
        proxy_url: if telegram.proxy_enabled {
            telegram.proxy_url.clone()
        } else {
            String::new()
        },
        poll_interval_secs: telegram.poll_interval_secs.max(1),
    })
}

fn telegram_binding_key(context: &IntegrationTargetContext, chat_id: i64) -> String {
    format!(
        "{}:{}:{}:{}",
        context.provider_kind(),
        context.profile_id(),
        context.owner_scope,
        chat_id
    )
}

fn telegram_delivery_is_terminal(status: &str) -> bool {
    matches!(
        status,
        "sent" | "delivery_unconfirmed" | "permanent_failure" | "sending"
    )
}

fn telegram_message_is_external_source(message: &Message) -> bool {
    message.source_kind.as_deref() == Some("telegram")
}

async fn run_managed_telegram_bridge(
    app_handle: AppHandle,
    generation: u64,
    mut cancel: oneshot::Receiver<()>,
) -> Result<(), String> {
    let state = app_handle.state::<AppState>();
    let settings = current_settings(&state)?;
    let telegram = telegram_managed_config(&settings)?;
    let mut context = resolve_telegram_integration_context(&state, generation).await?;
    ensure_integration_context(&state, &context)?;
    let client = telegram_bridge::build_managed_telegram_client(&telegram)?;
    let binding_key = telegram_binding_key(&context, telegram.allowed_chat_id);
    db::recover_telegram_sending_deliveries(&state.db_path, &binding_key, now_ms())
        .map_err(|error| format!("恢复 Telegram 本机投递状态失败: {error}"))?;
    let existing = db::telegram_bridge_binding_state(&state.db_path, &binding_key)
        .map_err(|error| error.to_string())?;
    let mut last_update_id = existing.as_ref().map(|state| state.0).unwrap_or(0);
    let mut watermark_ms = now_ms();
    let mut watermark_key = String::new();
    db::upsert_telegram_bridge_binding_state(
        &state.db_path,
        &binding_key,
        context.profile_id(),
        &context.owner_scope,
        context.provider_kind(),
        last_update_id,
        watermark_ms,
        &watermark_key,
        now_ms(),
    )
    .map_err(|error| error.to_string())?;

    loop {
        if let storage_provider::ProviderConfig::Supabase(profile) = &context.provider {
            let session = valid_supabase_session(&state, &profile.id, false)
                .await
                .map_err(|error| error.message)?
                .ok_or_else(|| "请先登录当前 Supabase 存储空间".to_string())?;
            if session.user_id != context.owner_scope {
                return Err("Supabase 登录账号已变化，请重新登录".to_string());
            }
            context.session = Some(session);
        }
        ensure_integration_context(&state, &context)?;
        tokio::select! {
            _ = &mut cancel => return Ok(()),
            updates = telegram_bridge::fetch_managed_updates(&client, &telegram, last_update_id) => {
                let updates = updates?;
                for update in updates {
                    ensure_integration_context(&state, &context)?;
                    if let Some(payload) = update.payload {
                        let source = ExternalSourceIdentity {
                            kind: "telegram".into(), channel_id: update.chat_id.to_string(),
                            message_id: update.message_id.to_string(),
                        };
                        let exists = db::find_message_by_source_for_scope(
                            &state.db_path, context.profile_id(), &context.owner_scope,
                            &source.kind, &source.channel_id, &source.message_id,
                        ).map_err(|error| error.to_string())?.is_some();
                        if !exists {
                            match payload {
                                telegram_bridge::ManagedInboundPayload::Text(text) => {
                                    ingest_external_text(&state, &context, &update.sender, update.timestamp_ms, text, source).await?;
                                }
                                telegram_bridge::ManagedInboundPayload::File { file_id, original_name, size_hint } => {
                                    let bytes = telegram_bridge::download_managed_file(&client, &telegram, &file_id, size_hint).await?;
                                    ensure_integration_context(&state, &context)?;
                                    ingest_external_file(&state, &context, &update.sender, update.timestamp_ms, original_name, bytes, source).await?;
                                }
                            }
                        }
                    }
                    last_update_id = last_update_id.max(update.update_id);
                    db::upsert_telegram_bridge_binding_state(
                        &state.db_path, &binding_key, context.profile_id(), &context.owner_scope, context.provider_kind(),
                        last_update_id, watermark_ms, &watermark_key, now_ms(),
                    ).map_err(|error| error.to_string())?;
                }
            }
        }

        let provider_sync_result = if matches!(
            context.provider,
            storage_provider::ProviderConfig::Supabase(_)
        ) {
            if let (storage_provider::ProviderConfig::Supabase(profile), Some(session)) =
                (&context.provider, context.session.as_ref())
            {
                pull_supabase_changes(&state, profile, session)
                    .await
                    .map(|_| ())
            } else {
                Err("Supabase Bridge 缺少本机会话".to_string())
            }
        } else {
            sync_once(&state, false).await.map(|_| ())
        };
        if let Err(error) = provider_sync_result {
            return Err(format!("刷新 Telegram Bridge 绑定空间失败: {error}"));
        }

        let messages = db::list_messages_after_for_scope(
            &state.db_path,
            context.profile_id(),
            &context.owner_scope,
            watermark_ms,
            &watermark_key,
            100,
            false,
        )
        .map_err(|error| format!("读取 Telegram 待投递消息失败: {error}"))?;
        for message in messages {
            ensure_integration_context(&state, &context)?;
            let stable_key = message
                .message_id
                .clone()
                .unwrap_or_else(|| message.filename.clone());
            if telegram_message_is_external_source(&message) {
                watermark_ms = message.timestamp_ms;
                watermark_key = stable_key.clone();
                continue;
            }
            if let Some(record) =
                db::get_telegram_delivery_record(&state.db_path, &binding_key, &stable_key)
                    .map_err(|error| error.to_string())?
            {
                if telegram_delivery_is_terminal(&record.status) {
                    watermark_ms = message.timestamp_ms;
                    watermark_key = stable_key.clone();
                    continue;
                }
            }
            let attempt_ms = now_ms();
            db::upsert_telegram_delivery_record(
                &state.db_path,
                &binding_key,
                &db::TelegramDeliveryRecord {
                    message_key: stable_key.clone(),
                    status: "sending".into(),
                    telegram_message_id: None,
                    last_error: None,
                    last_attempt_ms: Some(attempt_ms),
                },
            )
            .map_err(|error| error.to_string())?;
            let result = if message.kind == "text" {
                telegram_bridge::send_managed_text(
                    &client,
                    &telegram,
                    &message.sender,
                    message.content.as_deref().unwrap_or_default(),
                )
                .await
            } else {
                match telegram_outbound_file_bytes(&state, &context, &message).await {
                    Ok(bytes) => {
                        telegram_bridge::send_managed_file(
                            &client,
                            &telegram,
                            &message.sender,
                            &message.original_name,
                            bytes,
                        )
                        .await
                    }
                    Err(error) => Err(error),
                }
            };
            let record = match result {
                Ok(message_id) => db::TelegramDeliveryRecord {
                    message_key: stable_key.clone(),
                    status: "sent".into(),
                    telegram_message_id: Some(message_id),
                    last_error: None,
                    last_attempt_ms: Some(attempt_ms),
                },
                Err(error) => db::TelegramDeliveryRecord {
                    message_key: stable_key.clone(),
                    status: telegram_bridge::managed_delivery_error_status(&error).into(),
                    telegram_message_id: None,
                    last_error: Some(error),
                    last_attempt_ms: Some(attempt_ms),
                },
            };
            let delivery_status = record.status.clone();
            db::upsert_telegram_delivery_record(&state.db_path, &binding_key, &record)
                .map_err(|error| error.to_string())?;
            if record.status == "delivery_unconfirmed" || record.status == "permanent_failure" {
                if let Ok(mut manager) = state.telegram_bridge.lock() {
                    crate::telegram_bridge_runtime::record_managed_task_error(
                        &mut manager,
                        context.generation.unwrap_or_default(),
                        record
                            .last_error
                            .clone()
                            .unwrap_or_else(|| record.status.clone()),
                    );
                }
            }
            if delivery_status == "retryable_error" {
                break;
            }
            watermark_ms = message.timestamp_ms;
            watermark_key = stable_key;
        }
        db::upsert_telegram_bridge_binding_state(
            &state.db_path,
            &binding_key,
            context.profile_id(),
            &context.owner_scope,
            context.provider_kind(),
            last_update_id,
            watermark_ms,
            &watermark_key,
            now_ms(),
        )
        .map_err(|error| error.to_string())?;
    }
}

#[tauri::command]
async fn supabase_sign_in(
    state: State<'_, AppState>,
    input: SupabaseSignInInput,
) -> Result<SupabaseAccountStatus, supabase_auth::SupabaseAuthError> {
    let config = current_settings(&state)
        .and_then(|settings| supabase_profile_config(&settings, &input.profile_id))
        .map_err(|message| supabase_auth::SupabaseAuthError {
            kind: supabase_auth::SupabaseAuthErrorKind::InvalidResponse,
            message,
        })?;
    let session = supabase_auth::sign_in(
        &state.http,
        &config.api_url,
        &config.anon_key,
        &input.email,
        &input.password,
    )
    .await?;
    let status = account_status(&input.profile_id, Some(&session));
    credential_store::save_session(&input.profile_id, &session).map_err(|message| {
        supabase_auth::SupabaseAuthError {
            kind: supabase_auth::SupabaseAuthErrorKind::Service,
            message,
        }
    })?;
    state
        .supabase_sessions
        .lock()
        .map_err(|_| supabase_auth::SupabaseAuthError {
            kind: supabase_auth::SupabaseAuthErrorKind::Service,
            message: "保存 Supabase 会话失败".to_string(),
        })?
        .insert(input.profile_id, session);
    signal_sync_loop_reset(&state);
    Ok(status)
}

#[tauri::command]
async fn supabase_refresh_session(
    state: State<'_, AppState>,
    profile_id: String,
) -> Result<SupabaseAccountStatus, supabase_auth::SupabaseAuthError> {
    let session = valid_supabase_session(&state, &profile_id, true)
        .await?
        .ok_or_else(|| {
            auth_error(
                supabase_auth::SupabaseAuthErrorKind::SessionRevoked,
                "Supabase 会话不存在",
            )
        })?;
    Ok(account_status(&profile_id, Some(&session)))
}

#[tauri::command]
async fn supabase_current_user(
    state: State<'_, AppState>,
    profile_id: String,
) -> Result<SupabaseAccountStatus, supabase_auth::SupabaseAuthError> {
    let session = verified_supabase_session(&state, &profile_id).await?;
    let Some(session) = session else {
        return Ok(account_status(&profile_id, None));
    };
    Ok(account_status(&profile_id, Some(&session)))
}

#[tauri::command]
async fn list_supabase_spaces(
    state: State<'_, AppState>,
    profile_id: String,
) -> Result<Vec<SupabaseSpaceOption>, String> {
    list_supabase_spaces_impl(&state, &profile_id).await
}

async fn list_supabase_spaces_impl(
    state: &AppState,
    profile_id: &str,
) -> Result<Vec<SupabaseSpaceOption>, String> {
    let settings = current_settings(&state)?;
    let profile = match storage_provider::resolve_provider_by_id(&settings, profile_id)? {
        storage_provider::ProviderConfig::Supabase(profile) => profile,
        storage_provider::ProviderConfig::Webdav(_) => {
            return Err("该存储空间不是 Supabase".to_string())
        }
    };
    let config = profile
        .supabase
        .as_ref()
        .ok_or_else(|| "Supabase 存储空间配置不完整".to_string())?;
    let session = verified_supabase_session(state, profile_id)
        .await
        .map_err(|error| error.message)?
        .ok_or_else(|| "请先登录当前 Supabase 账号".to_string())?;
    let spaces = supabase_sync::list_spaces(&state.http, config, &session).await?;
    Ok(spaces
        .into_iter()
        .map(|space| {
            let local_profile_id = settings.storage_profiles.iter().find_map(|candidate| {
                let candidate_config = candidate.supabase.as_ref()?;
                (candidate.provider_kind == StorageProviderKind::Supabase
                    && candidate_config.api_url.trim_end_matches('/')
                        == config.api_url.trim_end_matches('/')
                    && candidate_config.space_id == space.id)
                    .then(|| candidate.id.clone())
            });
            let current =
                local_profile_id.as_deref() == settings.active_storage_profile_id.as_deref();
            SupabaseSpaceOption {
                current,
                id: space.id,
                name: space.name,
                message_count: space.message_count,
                updated_at: space.updated_at,
                local_profile_id,
            }
        })
        .collect())
}

#[tauri::command]
async fn switch_supabase_space(
    state: State<'_, AppState>,
    input: SwitchSupabaseSpaceInput,
) -> Result<Settings, String> {
    switch_supabase_space_impl(&state, input).await
}

async fn switch_supabase_space_impl(
    state: &AppState,
    input: SwitchSupabaseSpaceInput,
) -> Result<Settings, String> {
    let mut settings = current_settings(&state)?;
    let source =
        match storage_provider::resolve_provider_by_id(&settings, &input.source_profile_id)? {
            storage_provider::ProviderConfig::Supabase(profile) => profile,
            storage_provider::ProviderConfig::Webdav(_) => {
                return Err("当前存储空间不是 Supabase".to_string())
            }
        };
    let source_config = source
        .supabase
        .as_ref()
        .ok_or_else(|| "Supabase 存储空间配置不完整".to_string())?;
    let session = verified_supabase_session(&state, &source.id)
        .await
        .map_err(|error| error.message)?
        .ok_or_else(|| "请先登录当前 Supabase 账号".to_string())?;
    let spaces = supabase_sync::list_spaces(&state.http, source_config, &session).await?;
    let remote = spaces
        .into_iter()
        .find(|space| space.id == input.space_id)
        .ok_or_else(|| "所选 Supabase 空间不存在或当前账号无权访问".to_string())?;
    if source_config.space_id == remote.id {
        return Ok(settings);
    }
    if db::has_pending_profile_work(&state.db_path, &source.id)
        .map_err(|error| format!("检查存储空间未完成任务失败: {error}"))?
    {
        return Err(
            "当前存储空间仍有待上传、同步冲突或未完成的数据传输，请先处理后再切换".to_string(),
        );
    }

    cancel_active_sync(state)?;
    db::reset_profile_local_state_for_destination_change(&state.db_path, &source.id)
        .map_err(|error| format!("重置原存储空间本地缓存失败: {error}"))?;
    let profile = settings
        .storage_profiles
        .iter_mut()
        .find(|profile| profile.id == source.id)
        .ok_or_else(|| "Supabase 存储空间不存在".to_string())?;
    profile
        .supabase
        .as_mut()
        .ok_or_else(|| "Supabase 存储空间配置不完整".to_string())?
        .space_id = remote.id;
    settings.active_storage_profile_id = Some(source.id.clone());
    settings.active_webdav_id = None;
    let settings = normalize_settings(settings, &state.default_download_dir)?;
    write_settings_audited(&state.settings_path, &settings)?;
    *state
        .settings
        .lock()
        .map_err(|_| "写入设置失败".to_string())? = settings.clone();
    signal_sync_loop_reset(state);
    Ok(settings)
}

#[tauri::command]
async fn supabase_logout(
    state: State<'_, AppState>,
    profile_id: String,
) -> Result<SupabaseAccountStatus, supabase_auth::SupabaseAuthError> {
    supabase_logout_impl(&state, profile_id).await
}

async fn supabase_logout_impl(
    state: &AppState,
    profile_id: String,
) -> Result<SupabaseAccountStatus, supabase_auth::SupabaseAuthError> {
    let config = current_settings(state)
        .and_then(|settings| supabase_profile_config(&settings, &profile_id))
        .map_err(|message| supabase_auth::SupabaseAuthError {
            kind: supabase_auth::SupabaseAuthErrorKind::InvalidResponse,
            message,
        })?;
    let session = state
        .supabase_sessions
        .lock()
        .map_err(|_| supabase_auth::SupabaseAuthError {
            kind: supabase_auth::SupabaseAuthErrorKind::Service,
            message: "读取 Supabase 会话失败".to_string(),
        })?
        .get(&profile_id)
        .cloned();
    if let Some(session) = session {
        if let Err(error) = supabase_auth::logout(
            &state.http,
            &config.api_url,
            &config.anon_key,
            &session.access_token,
        )
        .await
        {
            log::warn!(
                "Supabase remote logout failed; local session will still be removed: {}",
                error.message
            );
        }
    }
    remove_supabase_session(state, &profile_id)?;
    signal_sync_loop_reset(state);
    Ok(account_status(&profile_id, None))
}

#[tauri::command]
async fn test_supabase_connection(
    state: State<'_, AppState>,
    profile_id: String,
) -> Result<supabase_connection::SupabaseConnectionCheck, String> {
    let config = current_settings(&state)
        .and_then(|settings| supabase_profile_config(&settings, &profile_id))?;
    let access_token = valid_supabase_session(&state, &profile_id, false)
        .await
        .map_err(|error| error.message)?
        .map(|session| session.access_token);
    Ok(supabase_connection::check(
        &state.http,
        &config.api_url,
        &config.anon_key,
        access_token.as_deref(),
    )
    .await)
}

#[tauri::command]
async fn test_supabase_draft_connection(
    state: State<'_, AppState>,
    input: SupabaseDraftConnectionInput,
) -> Result<supabase_connection::SupabaseConnectionCheck, String> {
    let api_url = input.api_url.trim().trim_end_matches('/');
    let anon_key = input.anon_key.trim();
    if api_url.is_empty() || anon_key.is_empty() {
        return Err("请填写 Supabase API URL 和公开 Key".to_string());
    }
    let access_token = input
        .profile_id
        .as_deref()
        .map(str::trim)
        .filter(|profile_id| !profile_id.is_empty())
        .and_then(|profile_id| {
            state
                .supabase_sessions
                .lock()
                .ok()?
                .get(profile_id)
                .map(|session| session.access_token.clone())
        });
    Ok(supabase_connection::check(&state.http, api_url, anon_key, access_token.as_deref()).await)
}

fn normalize_supabase_draft_config(
    api_url: &str,
    anon_key: &str,
) -> Result<SupabaseStorageConfig, String> {
    let api_url = api_url.trim().trim_end_matches('/').to_string();
    let anon_key = anon_key.trim().to_string();
    if api_url.is_empty() || anon_key.is_empty() {
        return Err("请填写 Supabase API URL 和公开 Key".to_string());
    }
    Ok(SupabaseStorageConfig {
        api_url,
        anon_key,
        space_id: String::new(),
    })
}

fn binding_flow_status(flow_id: &str, flow: &SupabaseBindingFlow) -> SupabaseAccountStatus {
    account_status(flow_id, Some(&flow.session))
}

#[tauri::command]
async fn supabase_draft_sign_in(
    state: State<'_, AppState>,
    input: SupabaseDraftSignInInput,
) -> Result<SupabaseAccountStatus, supabase_auth::SupabaseAuthError> {
    let config =
        normalize_supabase_draft_config(&input.api_url, &input.anon_key).map_err(|message| {
            auth_error(
                supabase_auth::SupabaseAuthErrorKind::InvalidResponse,
                message,
            )
        })?;
    if input.email.trim().is_empty() || input.password.is_empty() {
        return Err(auth_error(
            supabase_auth::SupabaseAuthErrorKind::InvalidCredentials,
            "请输入 Supabase 登录邮箱和密码",
        ));
    }
    let session = supabase_auth::sign_in(
        &state.http,
        &config.api_url,
        &config.anon_key,
        input.email.trim(),
        &input.password,
    )
    .await?;
    let flow_id = input
        .flow_id
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_string)
        .unwrap_or_else(|| uuid::Uuid::new_v4().to_string());
    let flow = SupabaseBindingFlow {
        api_url: config.api_url,
        anon_key: config.anon_key,
        session,
        updated_at_ms: now_ms(),
    };
    let status = binding_flow_status(&flow_id, &flow);
    state
        .supabase_binding_flows
        .lock()
        .map_err(|_| {
            auth_error(
                supabase_auth::SupabaseAuthErrorKind::Service,
                "保存临时登录状态失败",
            )
        })?
        .insert(flow_id, flow);
    Ok(status)
}

fn binding_flow(state: &AppState, flow_id: &str) -> Result<SupabaseBindingFlow, String> {
    let flow_id = flow_id.trim();
    if flow_id.is_empty() {
        return Err("Supabase 绑定流程已失效，请重新登录".to_string());
    }
    let mut flows = state
        .supabase_binding_flows
        .lock()
        .map_err(|_| "读取临时登录状态失败".to_string())?;
    flows.retain(|_, flow| now_ms().saturating_sub(flow.updated_at_ms) < 30 * 60 * 1000);
    flows
        .get_mut(flow_id)
        .map(|flow| {
            flow.updated_at_ms = now_ms();
            flow.clone()
        })
        .ok_or_else(|| "Supabase 绑定流程已过期，请重新登录".to_string())
}

#[tauri::command]
async fn list_supabase_draft_spaces(
    state: State<'_, AppState>,
    input: SupabaseBindingFlowInput,
) -> Result<Vec<SupabaseSpaceOption>, String> {
    let flow = binding_flow(&state, &input.flow_id)?;
    let config = SupabaseStorageConfig {
        api_url: flow.api_url,
        anon_key: flow.anon_key,
        space_id: String::new(),
    };
    let spaces = supabase_sync::list_spaces(&state.http, &config, &flow.session).await?;
    Ok(spaces
        .into_iter()
        .map(|space| SupabaseSpaceOption {
            id: space.id,
            name: space.name,
            message_count: space.message_count,
            updated_at: space.updated_at,
            local_profile_id: None,
            current: false,
        })
        .collect())
}

#[tauri::command]
fn cancel_supabase_binding_flow(
    state: State<'_, AppState>,
    input: SupabaseBindingFlowInput,
) -> Result<(), String> {
    state
        .supabase_binding_flows
        .lock()
        .map_err(|_| "清理临时登录状态失败".to_string())?
        .remove(input.flow_id.trim());
    Ok(())
}

#[tauri::command]
async fn create_supabase_space(
    state: State<'_, AppState>,
    input: CreateSupabaseSpaceInput,
) -> Result<SupabaseSpaceOption, String> {
    let name = input.name.trim();
    if name.is_empty() {
        return Err("请输入新空间名称".to_string());
    }
    let (mut config, session) = if let Some(flow_id) = input
        .flow_id
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
    {
        let flow = binding_flow(&state, flow_id)?;
        (
            SupabaseStorageConfig {
                api_url: flow.api_url,
                anon_key: flow.anon_key,
                space_id: String::new(),
            },
            flow.session,
        )
    } else {
        let profile_id = input.profile_id.as_deref().unwrap_or_default().trim();
        let settings = current_settings(&state)?;
        let config = supabase_profile_config(&settings, profile_id)?;
        let session = verified_supabase_session(&state, profile_id)
            .await
            .map_err(|error| error.message)?
            .ok_or_else(|| "请先登录当前 Supabase 账号".to_string())?;
        (config, session)
    };
    config.space_id = uuid::Uuid::new_v4().to_string();
    supabase_sync::create_space(&state.http, &config, &session, name).await?;
    Ok(SupabaseSpaceOption {
        id: config.space_id,
        name: name.to_string(),
        message_count: 0,
        updated_at: None,
        local_profile_id: None,
        current: false,
    })
}

#[tauri::command]
async fn complete_supabase_binding(
    state: State<'_, AppState>,
    input: CompleteSupabaseBindingInput,
) -> Result<Settings, String> {
    let flow = binding_flow(&state, &input.flow_id)?;
    let mut profile = input.profile;
    if profile.provider_kind != StorageProviderKind::Supabase {
        return Err("只能完成 Supabase 存储空间绑定".to_string());
    }
    let config = profile
        .supabase
        .as_mut()
        .ok_or_else(|| "Supabase 存储空间配置不完整".to_string())?;
    if config.api_url.trim().trim_end_matches('/') != flow.api_url
        || config.anon_key.trim() != flow.anon_key
    {
        return Err("Supabase 连接配置已改变，请重新登录".to_string());
    }
    config.space_id = input.space_id.trim().to_string();
    if uuid::Uuid::parse_str(&config.space_id).is_err() {
        return Err("请选择有效的 Supabase 空间".to_string());
    }
    let available = supabase_sync::list_spaces(&state.http, config, &flow.session).await?;
    if !available.iter().any(|space| space.id == config.space_id) {
        return Err("所选 Supabase 空间不存在或当前账号无权访问".to_string());
    }
    let updated = save_storage_profile_impl(
        &state,
        SaveStorageProfileInput {
            original_profile_id: input.original_profile_id.clone(),
            profile: profile.clone(),
        },
    )?;
    let saved_profile_id = input
        .original_profile_id
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .unwrap_or(&profile.id)
        .to_string();
    if let Err(error) = credential_store::save_session(&saved_profile_id, &flow.session) {
        if input.original_profile_id.is_none() {
            let _ = remove_storage_profile_impl(&state, &saved_profile_id, true);
        }
        return Err(error);
    }
    state
        .supabase_sessions
        .lock()
        .map_err(|_| "保存 Supabase 会话失败".to_string())?
        .insert(saved_profile_id, flow.session);
    state
        .supabase_binding_flows
        .lock()
        .map_err(|_| "清理临时登录状态失败".to_string())?
        .remove(input.flow_id.trim());
    signal_sync_loop_reset(&state);
    Ok(updated)
}

#[tauri::command]
fn get_telegram_bridge_status(state: State<'_, AppState>) -> Result<TelegramBridgeStatus, String> {
    TelegramBridgeRuntimeAdapter::new(&state).status()
}

