#[tauri::command]
async fn process_text_with_ai_stream(
    app: AppHandle,
    state: State<'_, AppState>,
    request_id: String,
    request: AiTextProcessRequest,
) -> Result<(), String> {
    let text = if request.speech_polish {
        request.text.as_str()
    } else {
        request.text.trim()
    };
    if !request.speech_polish && text.is_empty() {
        return Err("请先输入或选中需要处理的文本".to_string());
    }
    let settings = current_settings(&state)?;
    if !settings.ai.enabled {
        return Err("AI 功能未启用，请先在设置中开启".to_string());
    }
    let mut ai_settings = settings.ai.clone();
    normalize_ai_settings(&mut ai_settings)?;
    let speech_settings = if request.speech_polish {
        let mut speech_settings = settings.speech_to_text.clone();
        normalize_speech_to_text_settings(&mut speech_settings)?;
        Some(speech_settings)
    } else {
        None
    };
    let action = resolve_ai_text_process_action(&ai_settings, speech_settings.as_ref(), &request)?;
    let format = normalize_draft_format(request.format.as_deref());
    let request_options =
        resolve_ai_text_request_options(&ai_settings, speech_settings.as_ref(), text)?;
    emit_ai_stream_event(
        &app,
        AiTextStreamEvent {
            request_id: request_id.clone(),
            event_type: "start".to_string(),
            action_id: Some(action.id.clone()),
            action_name: Some(action.name.clone()),
            output_mode: Some(action.output_mode.clone()),
            delta: None,
            error: None,
        },
    );
    let result = match ai_settings.provider.kind.as_str() {
        "openai_compatible" => {
            stream_openai_compatible_text_action(
                &app,
                &state.http,
                &ai_settings,
                &action,
                &request_id,
                text,
                &format,
                &request_options,
            )
            .await
        }
        other => Err(format!("不支持的 AI Provider: {other}")),
    };
    match result {
        Ok(()) => {
            emit_ai_stream_event(
                &app,
                AiTextStreamEvent {
                    request_id,
                    event_type: "done".to_string(),
                    action_id: None,
                    action_name: None,
                    output_mode: None,
                    delta: None,
                    error: None,
                },
            );
            Ok(())
        }
        Err(err) => {
            emit_ai_stream_event(
                &app,
                AiTextStreamEvent {
                    request_id,
                    event_type: "error".to_string(),
                    action_id: None,
                    action_name: None,
                    output_mode: None,
                    delta: None,
                    error: Some(err.clone()),
                },
            );
            Err(err)
        }
    }
}

