#[tauri::command]
fn paste_dictation_text(text: String) -> Result<SystemDictationPasteResult, String> {
    let value = text.trim().to_string();
    if value.is_empty() {
        eprintln!("[system-dictation] paste skipped: empty text");
        return Ok(SystemDictationPasteResult {
            focus_detected: false,
            pasted: false,
        });
    }
    eprintln!(
        "[system-dictation] paste command received: text_chars={}",
        value.chars().count()
    );
    let paste_result = write_system_clipboard(&value).and_then(|()| {
        eprintln!("[system-dictation] clipboard write done");
        dispatch_system_paste()
    });
    paste_result.map(system_dictation_paste_result)
}

#[tauri::command]
fn copy_dictation_text(text: String) -> Result<(), String> {
    let value = text.trim().to_string();
    if value.is_empty() {
        return Ok(());
    }
    write_system_clipboard(&value)
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize)]
#[serde(rename_all = "camelCase")]
struct SystemDictationPasteResult {
    focus_detected: bool,
    pasted: bool,
}

#[derive(Debug, PartialEq, Eq)]
enum SystemPasteDispatchOutcome {
    Pasted,
    NoFocusedInput,
}

fn system_dictation_paste_result(
    outcome: SystemPasteDispatchOutcome,
) -> SystemDictationPasteResult {
    SystemDictationPasteResult {
        focus_detected: !matches!(outcome, SystemPasteDispatchOutcome::NoFocusedInput),
        // `pasted` describes successful OS shortcut dispatch, not confirmation that a
        // third-party control accepted and inserted the clipboard contents.
        pasted: matches!(outcome, SystemPasteDispatchOutcome::Pasted),
    }
}

fn write_system_clipboard(text: &str) -> Result<(), String> {
    #[cfg(target_os = "windows")]
    {
        write_windows_clipboard(text)
    }
    #[cfg(target_os = "macos")]
    {
        write_macos_clipboard(text)
    }
    #[cfg(all(unix, not(target_os = "macos")))]
    {
        let mut child = std::process::Command::new("sh")
            .args([
                "-c",
                "command -v wl-copy >/dev/null 2>&1 && wl-copy || xclip -selection clipboard",
            ])
            .stdin(std::process::Stdio::piped())
            .stdout(std::process::Stdio::null())
            .stderr(std::process::Stdio::piped())
            .spawn()
            .map_err(|err| format!("写入剪贴板失败: {err}"))?;
        if let Some(mut stdin) = child.stdin.take() {
            stdin
                .write_all(text.as_bytes())
                .map_err(|err| format!("写入剪贴板内容失败: {err}"))?;
        }
        let output = child
            .wait_with_output()
            .map_err(|err| format!("等待剪贴板写入失败: {err}"))?;
        if !output.status.success() {
            return Err("写入剪贴板失败，需要 wl-copy 或 xclip".to_string());
        }
        Ok(())
    }
}

#[cfg(target_os = "macos")]
fn write_macos_clipboard(text: &str) -> Result<(), String> {
    use objc2_app_kit::{NSPasteboard, NSPasteboardTypeString};
    use objc2_foundation::NSString;

    let pasteboard = NSPasteboard::generalPasteboard();
    pasteboard.clearContents();
    let string_type = unsafe { NSPasteboardTypeString };

    let value = NSString::from_str(text);
    if !pasteboard.setString_forType(&value, string_type) {
        return Err("写入剪贴板失败: NSPasteboard 拒绝写入文本".to_string());
    }

    let confirmed = pasteboard
        .stringForType(string_type)
        .map(|value| value.to_string())
        .ok_or_else(|| "写入剪贴板失败: 无法读取已写入的文本".to_string())?;
    if confirmed != text {
        return Err("写入剪贴板失败: 剪贴板内容校验不一致".to_string());
    }
    Ok(())
}

#[cfg(target_os = "windows")]
fn write_windows_clipboard(text: &str) -> Result<(), String> {
    use std::ptr::{copy_nonoverlapping, null_mut};
    use windows_sys::Win32::System::DataExchange::{
        CloseClipboard, EmptyClipboard, OpenClipboard, SetClipboardData,
    };
    use windows_sys::Win32::System::Memory::{
        GlobalAlloc, GlobalLock, GlobalUnlock, GMEM_MOVEABLE,
    };
    use windows_sys::Win32::System::Ole::CF_UNICODETEXT;

    let mut wide: Vec<u16> = text.encode_utf16().collect();
    wide.push(0);
    let byte_len = wide.len() * std::mem::size_of::<u16>();

    unsafe {
        if OpenClipboard(null_mut()) == 0 {
            return Err("打开剪贴板失败".to_string());
        }
        let clipboard_guard = ClipboardCloseGuard;
        if EmptyClipboard() == 0 {
            return Err("清空剪贴板失败".to_string());
        }
        let handle = GlobalAlloc(GMEM_MOVEABLE, byte_len);
        if handle.is_null() {
            return Err("分配剪贴板内存失败".to_string());
        }
        let locked = GlobalLock(handle) as *mut u8;
        if locked.is_null() {
            return Err("锁定剪贴板内存失败".to_string());
        }
        copy_nonoverlapping(wide.as_ptr() as *const u8, locked, byte_len);
        GlobalUnlock(handle);
        if SetClipboardData(CF_UNICODETEXT.into(), handle).is_null() {
            return Err("写入剪贴板失败".to_string());
        }
        std::mem::forget(clipboard_guard);
        let _ = CloseClipboard();
    }
    Ok(())
}

#[cfg(target_os = "windows")]
struct ClipboardCloseGuard;

#[cfg(target_os = "windows")]
impl Drop for ClipboardCloseGuard {
    fn drop(&mut self) {
        unsafe {
            let _ = windows_sys::Win32::System::DataExchange::CloseClipboard();
        }
    }
}

fn dispatch_system_paste() -> Result<SystemPasteDispatchOutcome, String> {
    std::thread::sleep(Duration::from_millis(90));
    #[cfg(target_os = "windows")]
    {
        dispatch_windows_paste_shortcut()
    }
    #[cfg(target_os = "macos")]
    {
        let target_pid = resolve_macos_system_dictation_paste_target_pid();
        dispatch_macos_paste_command(target_pid).or_else(|err| {
            eprintln!(
                "[system-dictation] mac paste command failed, falling back to shortcut: {err}"
            );
            dispatch_macos_paste_shortcut("cmd+v", target_pid)
        })
    }
    #[cfg(all(unix, not(target_os = "macos")))]
    {
        let output = std::process::Command::new("xdotool")
            .args(["key", "ctrl+v"])
            .stdout(std::process::Stdio::null())
            .stderr(std::process::Stdio::piped())
            .output()
            .map_err(|err| format!("触发粘贴失败，需要 xdotool: {err}"))?;
        if !output.status.success() {
            return Err("触发粘贴失败，需要 xdotool".to_string());
        }
        Ok(SystemPasteDispatchOutcome::Pasted)
    }
}

#[cfg(target_os = "macos")]
fn dispatch_macos_paste_command(
    target_pid: Option<i32>,
) -> Result<SystemPasteDispatchOutcome, String> {
    ensure_macos_accessibility_permission("粘贴听写结果")?;
    restore_macos_system_dictation_target_app_before_paste(target_pid);

    let process_selector = target_pid
        .map(|pid| format!("whose unix id is {pid}"))
        .unwrap_or_else(|| "whose frontmost is true".to_string());
    let script = format!(
        r#"
tell application "System Events"
  set targetApp to first application process {process_selector}
  set frontmost of targetApp to true
  try
    click menu item "Paste" of menu "Edit" of menu bar 1 of targetApp
  on error firstError
    try
      click menu item "粘贴" of menu "编辑" of menu bar 1 of targetApp
    on error secondError
      error (firstError & " / " & secondError)
    end try
  end try
end tell
"#
    );

    eprintln!(
        "[system-dictation] paste command dispatching: app menu Paste target_pid={:?}",
        target_pid
    );
    let output = std::process::Command::new("osascript")
        .arg("-e")
        .arg(script)
        .stdout(std::process::Stdio::null())
        .stderr(std::process::Stdio::piped())
        .output()
        .map_err(|err| format!("触发系统粘贴命令失败: {err}"))?;
    if !output.status.success() {
        let stderr = String::from_utf8_lossy(&output.stderr).trim().to_string();
        return Err(if stderr.is_empty() {
            "触发系统粘贴命令失败".to_string()
        } else {
            format!("触发系统粘贴命令失败: {stderr}")
        });
    }
    eprintln!("[system-dictation] paste command dispatched: app menu Paste");
    Ok(SystemPasteDispatchOutcome::Pasted)
}

#[cfg(target_os = "macos")]
fn dispatch_macos_paste_shortcut(
    shortcut: &str,
    target_pid: Option<i32>,
) -> Result<SystemPasteDispatchOutcome, String> {
    use core_graphics::event::{CGEvent, CGEventTapLocation};
    use core_graphics::event_source::{CGEventSource, CGEventSourceStateID};

    ensure_macos_accessibility_permission("粘贴听写结果")?;
    restore_macos_system_dictation_target_app_before_paste(target_pid);

    let shortcut = normalize_macos_keyboard_shortcut(shortcut)
        .ok_or_else(|| "系统听写结果粘贴快捷键格式无效".to_string())?;

    let source = CGEventSource::new(CGEventSourceStateID::CombinedSessionState)
        .map_err(|_| "触发粘贴失败：无法创建键盘事件源".to_string())?;
    let key_down = CGEvent::new_keyboard_event(source.clone(), shortcut.key_code, true)
        .map_err(|_| "触发粘贴失败：无法创建按键事件".to_string())?;
    let key_up = CGEvent::new_keyboard_event(source, shortcut.key_code, false)
        .map_err(|_| "触发粘贴失败：无法创建按键释放事件".to_string())?;
    key_down.set_flags(shortcut.flags);
    key_up.set_flags(shortcut.flags);
    eprintln!(
        "[system-dictation] paste shortcut dispatching: {}",
        shortcut.label
    );
    key_down.post(CGEventTapLocation::HID);
    std::thread::sleep(Duration::from_millis(20));
    key_up.post(CGEventTapLocation::HID);
    eprintln!(
        "[system-dictation] paste shortcut dispatched: {}",
        shortcut.label
    );
    Ok(SystemPasteDispatchOutcome::Pasted)
}

#[cfg(target_os = "macos")]
struct MacosKeyboardShortcut {
    flags: core_graphics::event::CGEventFlags,
    key_code: u16,
    label: String,
}

#[cfg(target_os = "macos")]
fn normalize_macos_keyboard_shortcut(raw: &str) -> Option<MacosKeyboardShortcut> {
    use core_graphics::event::CGEventFlags;

    let normalized = normalize_global_hotkey(raw).unwrap_or_else(|| "cmd+v".to_string());
    let mut flags = CGEventFlags::CGEventFlagNull;
    let mut key_code = None;
    for part in normalized
        .split('+')
        .map(str::trim)
        .filter(|part| !part.is_empty())
    {
        match part {
            "ctrl" | "control" => flags |= CGEventFlags::CGEventFlagControl,
            "alt" | "option" => flags |= CGEventFlags::CGEventFlagAlternate,
            "shift" => flags |= CGEventFlags::CGEventFlagShift,
            "cmd" | "command" | "meta" | "super" => flags |= CGEventFlags::CGEventFlagCommand,
            value => key_code = macos_key_code_for_shortcut_key(value),
        }
    }
    Some(MacosKeyboardShortcut {
        flags,
        key_code: key_code?,
        label: normalized,
    })
}

#[cfg(target_os = "macos")]
fn macos_key_code_for_shortcut_key(key: &str) -> Option<u16> {
    match key {
        "a" => Some(0x00),
        "s" => Some(0x01),
        "d" => Some(0x02),
        "f" => Some(0x03),
        "h" => Some(0x04),
        "g" => Some(0x05),
        "z" => Some(0x06),
        "x" => Some(0x07),
        "c" => Some(0x08),
        "v" => Some(0x09),
        "b" => Some(0x0B),
        "q" => Some(0x0C),
        "w" => Some(0x0D),
        "e" => Some(0x0E),
        "r" => Some(0x0F),
        "y" => Some(0x10),
        "t" => Some(0x11),
        "1" => Some(0x12),
        "2" => Some(0x13),
        "3" => Some(0x14),
        "4" => Some(0x15),
        "6" => Some(0x16),
        "5" => Some(0x17),
        "=" | "equal" => Some(0x18),
        "9" => Some(0x19),
        "7" => Some(0x1A),
        "-" | "minus" => Some(0x1B),
        "8" => Some(0x1C),
        "0" => Some(0x1D),
        "]" | "bracketright" => Some(0x1E),
        "o" => Some(0x1F),
        "u" => Some(0x20),
        "[" | "bracketleft" => Some(0x21),
        "i" => Some(0x22),
        "p" => Some(0x23),
        "l" => Some(0x25),
        "j" => Some(0x26),
        "'" | "quote" => Some(0x27),
        "k" => Some(0x28),
        ";" | "semicolon" => Some(0x29),
        "\\" | "backslash" => Some(0x2A),
        "," | "comma" => Some(0x2B),
        "/" | "slash" => Some(0x2C),
        "n" => Some(0x2D),
        "m" => Some(0x2E),
        "." | "period" => Some(0x2F),
        "space" => Some(0x31),
        "enter" | "return" => Some(0x24),
        "tab" => Some(0x30),
        "escape" | "esc" => Some(0x35),
        _ => None,
    }
}

#[cfg(target_os = "macos")]
fn current_macos_frontmost_app_pid() -> Option<i32> {
    let workspace = objc2_app_kit::NSWorkspace::sharedWorkspace();
    workspace
        .frontmostApplication()
        .map(|application| application.processIdentifier() as i32)
        .filter(|pid| *pid > 0)
}

#[cfg(target_os = "macos")]
fn record_macos_system_dictation_target_app() {
    use std::sync::atomic::Ordering;

    let current_pid = std::process::id() as i32;
    let Some(frontmost_pid) = current_macos_frontmost_app_pid() else {
        return;
    };
    if frontmost_pid != current_pid {
        SYSTEM_DICTATION_TARGET_APP_PID.store(frontmost_pid, Ordering::SeqCst);
        eprintln!("[system-dictation] mac target app pid recorded: {frontmost_pid}");
    }
}

#[cfg(target_os = "macos")]
fn take_macos_system_dictation_target_app_pid() -> Option<i32> {
    use std::sync::atomic::Ordering;

    let target_pid = SYSTEM_DICTATION_TARGET_APP_PID.swap(0, Ordering::SeqCst);
    (target_pid > 0).then_some(target_pid)
}

#[cfg(target_os = "macos")]
fn resolve_macos_system_dictation_paste_target_pid() -> Option<i32> {
    use std::sync::atomic::Ordering;

    let current_pid = std::process::id() as i32;
    if let Some(frontmost_pid) = current_macos_frontmost_app_pid() {
        if frontmost_pid != current_pid {
            SYSTEM_DICTATION_TARGET_APP_PID.store(0, Ordering::SeqCst);
            eprintln!(
                "[system-dictation] mac paste target resolved from current frontmost app: pid={frontmost_pid}"
            );
            return Some(frontmost_pid);
        }
    }

    let fallback_pid = take_macos_system_dictation_target_app_pid();
    eprintln!(
        "[system-dictation] mac paste target resolved from recorded fallback: pid={:?}",
        fallback_pid
    );
    fallback_pid
}

#[cfg(target_os = "macos")]
fn restore_macos_system_dictation_target_app_before_paste(target_pid: Option<i32>) {
    use objc2_app_kit::{NSApplicationActivationOptions, NSRunningApplication};

    let Some(target_pid) = target_pid else {
        return;
    };
    if let Some(application) =
        NSRunningApplication::runningApplicationWithProcessIdentifier(target_pid)
    {
        #[allow(deprecated)]
        let options = NSApplicationActivationOptions::ActivateAllWindows
            | NSApplicationActivationOptions::ActivateIgnoringOtherApps;
        let activated = application.activateWithOptions(options);
        eprintln!("[system-dictation] mac target app restored before paste: pid={target_pid} activated={activated}");
        std::thread::sleep(Duration::from_millis(220));
    }
}

#[cfg(target_os = "macos")]
fn ensure_macos_accessibility_permission(action: &str) -> Result<(), String> {
    if check_macos_accessibility_permission(false) {
        return Ok(());
    }
    use std::sync::atomic::Ordering;
    if !MACOS_ACCESSIBILITY_PROMPT_SHOWN.swap(true, Ordering::SeqCst) {
        let _ = check_macos_accessibility_permission(true);
    }
    if check_macos_accessibility_permission(false) {
        Ok(())
    } else {
        Err(format!(
            "{action}需要辅助功能权限。请在系统设置 > 隐私与安全性 > 辅助功能中允许 Transfer Genie，然后重试。"
        ))
    }
}

#[cfg(target_os = "macos")]
fn check_macos_accessibility_permission(prompt: bool) -> bool {
    use core_foundation::base::{CFTypeRef, TCFType};
    use core_foundation::boolean::CFBoolean;
    use core_foundation::dictionary::CFDictionary;
    use core_foundation::string::{CFString, CFStringRef};
    use std::ffi::c_void;

    #[link(name = "ApplicationServices", kind = "framework")]
    extern "C" {
        static kAXTrustedCheckOptionPrompt: CFStringRef;
        fn AXIsProcessTrustedWithOptions(options: CFTypeRef) -> u8;
    }

    let prompt_key = unsafe { CFString::wrap_under_get_rule(kAXTrustedCheckOptionPrompt) };
    let prompt_value = CFBoolean::from(prompt);
    let options =
        CFDictionary::<CFString, CFBoolean>::from_CFType_pairs(&[(prompt_key, prompt_value)]);
    unsafe { AXIsProcessTrustedWithOptions(options.as_CFTypeRef() as *const c_void) != 0 }
}

#[cfg(target_os = "windows")]
fn dispatch_windows_paste_shortcut() -> Result<SystemPasteDispatchOutcome, String> {
    use windows_sys::Win32::UI::Input::KeyboardAndMouse::{
        SendInput, INPUT, INPUT_0, INPUT_KEYBOARD, KEYBDINPUT, KEYEVENTF_KEYUP, VIRTUAL_KEY,
        VK_CONTROL, VK_V,
    };
    use windows_sys::Win32::UI::WindowsAndMessaging::GetForegroundWindow;

    let foreground = unsafe { GetForegroundWindow() };
    if foreground.is_null() {
        eprintln!("[system-dictation] paste shortcut skipped: no current foreground window");
        return Ok(SystemPasteDispatchOutcome::NoFocusedInput);
    }
    // Read the foreground window immediately before injection so users can redirect output
    // while recording, transcribing, or polishing is still in progress.
    eprintln!("[system-dictation] paste shortcut dispatching: ctrl+v");

    fn keyboard_input(vk: VIRTUAL_KEY, flags: u32) -> INPUT {
        INPUT {
            r#type: INPUT_KEYBOARD,
            Anonymous: INPUT_0 {
                ki: KEYBDINPUT {
                    wVk: vk,
                    wScan: 0,
                    dwFlags: flags,
                    time: 0,
                    dwExtraInfo: 0,
                },
            },
        }
    }

    let inputs = [
        keyboard_input(VK_CONTROL, 0),
        keyboard_input(VK_V, 0),
        keyboard_input(VK_V, KEYEVENTF_KEYUP),
        keyboard_input(VK_CONTROL, KEYEVENTF_KEYUP),
    ];
    let sent = unsafe {
        SendInput(
            inputs.len() as u32,
            inputs.as_ptr(),
            std::mem::size_of::<INPUT>() as i32,
        )
    };
    if sent != inputs.len() as u32 {
        return Err("触发粘贴失败".to_string());
    }
    eprintln!("[system-dictation] paste shortcut dispatched: inputs={sent}");
    Ok(SystemPasteDispatchOutcome::Pasted)
}

#[tauri::command]
fn show_system_dictation_window(app: AppHandle, request_id: Option<u64>) -> Result<(), String> {
    eprintln!("[system-dictation] show window command received");
    let request_id = register_system_dictation_overlay_request(request_id);
    let app_for_task = app.clone();
    app.run_on_main_thread(move || {
        if !is_current_system_dictation_overlay_request(request_id) {
            eprintln!("[system-dictation] stale show window request skipped");
            return;
        }
        if let Err(err) = show_system_dictation_window_impl(&app_for_task, request_id, true) {
            eprintln!("[system-dictation] show window failed: {err}");
        }
    })
    .map_err(|err| format!("调度系统听写窗口显示失败: {err}"))
}

#[tauri::command]
fn hide_system_dictation_window(app: AppHandle, request_id: Option<u64>) -> Result<(), String> {
    eprintln!("[system-dictation] hide window command received");
    let request_id = register_system_dictation_overlay_request(request_id);
    let app_for_task = app.clone();
    app.run_on_main_thread(move || {
        if !is_current_system_dictation_overlay_request(request_id) {
            eprintln!("[system-dictation] stale hide window request skipped");
            return;
        }
        hide_system_dictation_window_impl(&app_for_task, request_id);
    })
    .map_err(|err| format!("调度系统听写窗口隐藏失败: {err}"))
}

fn register_system_dictation_overlay_request(request_id: Option<u64>) -> Option<u64> {
    request_id.map(|id| {
        SYSTEM_DICTATION_OVERLAY_REQUEST_ID.fetch_max(id, std::sync::atomic::Ordering::SeqCst);
        id
    })
}

fn is_current_system_dictation_overlay_request(request_id: Option<u64>) -> bool {
    request_id.is_none_or(|id| {
        SYSTEM_DICTATION_OVERLAY_REQUEST_ID.load(std::sync::atomic::Ordering::SeqCst) == id
    })
}

#[tauri::command]
fn set_system_dictation_level(app: AppHandle, level: f64) {
    let normalized = level.clamp(0.0, 1.0);
    let app_for_task = app.clone();
    let _ = app.run_on_main_thread(move || {
        emit_system_dictation_overlay_level(&app_for_task, normalized);
    });
}

#[tauri::command]
fn system_dictation_action(app: AppHandle, action: String) -> Result<(), String> {
    let normalized = action.trim().to_lowercase();
    match normalized.as_str() {
        "confirm" => {
            let _ = app.emit("system-dictation-confirm", ());
            Ok(())
        }
        "cancel" => {
            let _ = app.emit("system-dictation-cancel", ());
            Ok(())
        }
        _ => Err("无效的系统听写操作".to_string()),
    }
}

fn system_dictation_window_url() -> WebviewUrl {
    WebviewUrl::App("system-dictation.html".into())
}

fn ensure_system_dictation_window_impl(app: &AppHandle) -> Result<(), String> {
    if let Some(window) = app.get_webview_window(SYSTEM_DICTATION_WINDOW_LABEL) {
        eprintln!("[system-dictation] ensure window existing");
        let _ = window.set_focusable(false);
        let _ = window.set_always_on_top(true);
        let _ = window.set_skip_taskbar(true);
        return Ok(());
    }

    eprintln!("[system-dictation] ensure window building");
    let window = WebviewWindowBuilder::new(
        app,
        SYSTEM_DICTATION_WINDOW_LABEL,
        system_dictation_window_url(),
    )
    .title("Transfer Genie")
    .inner_size(
        SYSTEM_DICTATION_WINDOW_WIDTH,
        SYSTEM_DICTATION_WINDOW_HEIGHT,
    )
    .resizable(false)
    .decorations(false)
    .shadow(false)
    .transparent(true)
    .skip_taskbar(true)
    .always_on_top(true)
    .focusable(false)
    .focused(false)
    .visible(false)
    .build()
    .map_err(|err| format!("创建系统听写窗口失败: {err}"))?;

    let _ = window.set_focusable(false);
    let _ = window.set_shadow(false);
    let _ = window.set_always_on_top(true);
    let _ = window.set_skip_taskbar(true);
    eprintln!("[system-dictation] ensure window built");
    Ok(())
}

fn show_system_dictation_window_impl(
    app: &AppHandle,
    request_id: Option<u64>,
    show_recording_capsule: bool,
) -> Result<(), String> {
    SYSTEM_DICTATION_OVERLAY_GENERATION.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
    eprintln!("[system-dictation] show window start");
    ensure_system_dictation_window_impl(app)?;
    if let Some(window) = app.get_webview_window(SYSTEM_DICTATION_WINDOW_LABEL) {
        position_system_dictation_window(app, &window);
        let _ = window.show();
        if show_recording_capsule {
            let _ = window.emit("system-dictation-show", request_id.unwrap_or_default());
            let _ = window.eval("window.__transferGenieShowDictationCapsule?.();");
        }
        let _ = window.set_focusable(false);
        let _ = window.set_shadow(false);
        let _ = window.set_always_on_top(true);
        let _ = window.set_skip_taskbar(true);
    }
    eprintln!("[system-dictation] show window done");
    Ok(())
}

fn position_system_dictation_window(app: &AppHandle, window: &tauri::WebviewWindow) {
    let monitor = window
        .current_monitor()
        .ok()
        .flatten()
        .or_else(|| app.primary_monitor().ok().flatten());
    let Some(monitor) = monitor else {
        eprintln!("[system-dictation] position skipped: no monitor");
        return;
    };
    let monitor_position = monitor.position();
    let monitor_size = monitor.size();
    let scale_factor = monitor.scale_factor();
    let window_width = (SYSTEM_DICTATION_WINDOW_WIDTH * scale_factor).round() as i32;
    let window_height = (SYSTEM_DICTATION_WINDOW_HEIGHT * scale_factor).round() as i32;
    let x = monitor_position.x + ((monitor_size.width as i32 - window_width) / 2);
    let y = monitor_position.y + monitor_size.height as i32
        - window_height
        - SYSTEM_DICTATION_WINDOW_BOTTOM_MARGIN;
    let _ = window.set_position(PhysicalPosition::new(x.max(monitor_position.x), y));
    eprintln!("[system-dictation] positioned window x={x} y={y}");
}

fn hide_system_dictation_window_impl(app: &AppHandle, request_id: Option<u64>) {
    eprintln!("[system-dictation] hide window start");
    if let Some(window) = app.get_webview_window(SYSTEM_DICTATION_WINDOW_LABEL) {
        let generation = SYSTEM_DICTATION_OVERLAY_GENERATION
            .fetch_add(1, std::sync::atomic::Ordering::SeqCst)
            + 1;
        let _ = window.emit("system-dictation-hide", request_id.unwrap_or_default());
        let _ = window.eval("window.__transferGenieHideDictationCapsule?.();");
        let app_for_hide = app.clone();
        std::thread::spawn(move || {
            std::thread::sleep(Duration::from_millis(150));
            if SYSTEM_DICTATION_OVERLAY_GENERATION.load(std::sync::atomic::Ordering::SeqCst)
                != generation
            {
                eprintln!("[system-dictation] stale hide skipped");
                return;
            }
            let app_for_lookup = app_for_hide.clone();
            let _ = app_for_hide.run_on_main_thread(move || {
                if let Some(window) =
                    app_for_lookup.get_webview_window(SYSTEM_DICTATION_WINDOW_LABEL)
                {
                    let _ = window.hide();
                }
            });
        });
    }
    eprintln!("[system-dictation] hide window done");
}

fn emit_system_dictation_overlay_level(app: &AppHandle, level: f64) {
    if let Some(window) = app.get_webview_window(SYSTEM_DICTATION_WINDOW_LABEL) {
        let normalized = level.clamp(0.0, 1.0);
        let _ = window.emit("system-dictation-level", normalized);
        let _ = window.eval(format!(
            "window.__transferGenieSetDictationLevel?.({normalized});"
        ));
    }
}

#[tauri::command]
fn set_system_dictation_status(
    app: AppHandle,
    text: String,
    copy_text: Option<String>,
    request_id: Option<u64>,
) -> Result<(), String> {
    let message = text.trim().to_string();
    let copy_text = copy_text.unwrap_or_default();
    let request_id = if message.is_empty() && request_id.is_none() {
        Some(
            SYSTEM_DICTATION_OVERLAY_REQUEST_ID.fetch_add(1, std::sync::atomic::Ordering::SeqCst)
                + 1,
        )
    } else {
        register_system_dictation_overlay_request(request_id)
    };
    let app_for_task = app.clone();
    app.run_on_main_thread(move || {
        if !is_current_system_dictation_overlay_request(request_id) {
            eprintln!("[system-dictation] stale status request skipped");
            return;
        }
        if !message.is_empty() {
            if let Err(err) = show_system_dictation_window_impl(&app_for_task, request_id, false) {
                eprintln!("[system-dictation] show status window failed: {err}");
                return;
            }
        }
        if let Some(window) = app_for_task.get_webview_window(SYSTEM_DICTATION_WINDOW_LABEL) {
            let payload = serde_json::json!({
                "text": message,
                "copyText": copy_text,
                "requestId": request_id,
            });
            let _ = window.emit("system-dictation-status", payload.clone());
            let escaped = serde_json::to_string(&payload).unwrap_or_else(|_| "{}".to_string());
            let _ = window.eval(format!(
                "window.__transferGenieSetDictationStatus?.({escaped});"
            ));
        }
        if message.is_empty() {
            hide_system_dictation_window_impl(&app_for_task, request_id);
        }
    })
    .map_err(|err| format!("调度系统听写状态失败: {err}"))
}

#[tauri::command]
