fn generate_marked_tag_id() -> String {
    format!("tag-{}-{}", now_ms(), OsRng.gen::<u32>())
}

fn normalize_marked_tag_name(name: &str) -> Result<String, String> {
    let normalized = name.trim();
    if normalized.is_empty() {
        return Err("标签名不能为空".to_string());
    }
    Ok(normalized.to_string())
}

fn ensure_unique_marked_tag_name(
    tags: &[MarkedTag],
    name: &str,
    excluding_id: Option<&str>,
) -> Result<(), String> {
    let target = name.trim().to_lowercase();
    let duplicated = tags.iter().any(|tag| {
        if excluding_id.is_some() && excluding_id == Some(tag.id.as_str()) {
            return false;
        }
        tag.name.trim().to_lowercase() == target
    });
    if duplicated {
        return Err("标签名已存在".to_string());
    }
    Ok(())
}

fn sanitize_marked_tag_ids(tags: &[MarkedTag], tag_ids: Vec<String>) -> Vec<String> {
    let mut valid_tag_ids: Vec<String> = tag_ids
        .into_iter()
        .filter(|tag_id| tags.iter().any(|tag| tag.id == *tag_id))
        .collect();
    valid_tag_ids.sort();
    valid_tag_ids.dedup();
    valid_tag_ids
}

fn sanitize_existing_marked_tag_ids(tags: &[MarkedTag], tag_ids: Vec<String>) -> Vec<String> {
    sanitize_marked_tag_ids(tags, tag_ids)
}

fn sanitize_deleted_marked_tag_ids(tags: &[MarkedTag], tag_ids: Vec<String>) -> Vec<String> {
    sanitize_marked_tag_ids(tags, tag_ids)
}

fn normalize_marked_due_date(value: Option<String>) -> Result<Option<String>, String> {
    let Some(value) = value else {
        return Ok(None);
    };
    let value = value.trim().to_string();
    if value.is_empty() {
        return Ok(None);
    }
    if is_valid_marked_due_date(&value) {
        Ok(Some(value))
    } else {
        Err("处理日期格式必须为 YYYY-MM-DD".to_string())
    }
}

fn is_valid_marked_due_date(value: &str) -> bool {
    let bytes = value.as_bytes();
    bytes.len() == 10
        && bytes[4] == b'-'
        && bytes[7] == b'-'
        && bytes
            .iter()
            .enumerate()
            .all(|(index, byte)| index == 4 || index == 7 || byte.is_ascii_digit())
}

fn today_due_date_string() -> String {
    let date = OffsetDateTime::now_local()
        .unwrap_or_else(|_| OffsetDateTime::now_utc())
        .date();
    format!(
        "{:04}-{:02}-{:02}",
        date.year(),
        u8::from(date.month()),
        date.day()
    )
}

fn count_unfinished_marked_messages(state: &AppState, endpoint_id: &str) -> Result<i64, String> {
    let today = today_due_date_string();
    db::count_unfinished_marked_messages(&state.db_path, endpoint_id, &today)
        .map_err(|err| err.to_string())
}

async fn load_and_apply_send_marked_options(
    state: &AppState,
    endpoint: &WebDavEndpoint,
    options: SendMarkedOptionsInput,
) -> Result<AppliedSendMarkedOptions, String> {
    let mut tags =
        db::list_marked_tags(&state.db_path, &endpoint.id).map_err(|err| err.to_string())?;
    let deleted_tag_ids = sanitize_deleted_marked_tag_ids(&tags, options.deleted_tag_ids);
    let deleted_set: HashSet<&str> = deleted_tag_ids.iter().map(String::as_str).collect();
    let mut cleanup_targets = Vec::new();
    let tags_changed = !deleted_set.is_empty() || !options.created_tags.is_empty();
    if !deleted_set.is_empty() {
        tags.retain(|tag| !deleted_set.contains(tag.id.as_str()));
        let marked_messages = db::list_marked_messages(&state.db_path, &endpoint.id, None, None)
            .map_err(|err| err.to_string())?;
        for message in marked_messages {
            if !message
                .marked_tag_ids
                .iter()
                .any(|tag_id| deleted_set.contains(tag_id.as_str()))
            {
                continue;
            }
            let mut db_message = db::get_message(&state.db_path, &endpoint.id, &message.filename)
                .map_err(|err| err.to_string())?
                .ok_or_else(|| "未找到消息".to_string())?;
            db_message
                .marked_tag_ids
                .retain(|tag_id| !deleted_set.contains(tag_id.as_str()));
            db::upsert_message(&state.db_path, &db_message).map_err(|err| err.to_string())?;
            cleanup_targets.push((db_message.filename.clone(), db_message.timestamp_ms));
        }
    }

    let mut selected_created_tag_ids = Vec::new();
    for created_tag in options.created_tags {
        let normalized = normalize_marked_tag_name(&created_tag.name)?;
        ensure_unique_marked_tag_name(&tags, &normalized, None)?;
        let tag = MarkedTag {
            id: generate_marked_tag_id(),
            name: normalized,
        };
        if created_tag.selected {
            selected_created_tag_ids.push(tag.id.clone());
        }
        tags.push(tag);
    }
    tags.sort_by(|left, right| left.name.cmp(&right.name));

    let mut final_tag_ids = sanitize_existing_marked_tag_ids(&tags, options.selected_tag_ids);
    final_tag_ids.extend(selected_created_tag_ids);
    final_tag_ids.sort();
    final_tag_ids.dedup();
    if !options.marked {
        final_tag_ids.clear();
    }
    let due_date = if options.marked {
        normalize_marked_due_date(options.due_date)?
    } else {
        None
    };

    Ok(AppliedSendMarkedOptions {
        marked: options.marked,
        tag_ids: final_tag_ids,
        due_date,
        tags,
        tags_changed,
        cleanup_targets,
    })
}

fn apply_supabase_send_marked_options(
    state: &AppState,
    profile: &StorageProfile,
    session: &supabase_auth::SupabaseSession,
    message: &mut DbMessage,
    options: SendMarkedOptionsInput,
) -> Result<SupabaseSendMarkedChanges, String> {
    let existing = db::list_tags_for_scope(&state.db_path, &profile.id, &session.user_id)
        .map_err(|error| error.to_string())?;
    let existing_tags = existing
        .iter()
        .map(|(tag, _)| tag.clone())
        .collect::<Vec<_>>();
    let deleted_tag_ids = sanitize_deleted_marked_tag_ids(&existing_tags, options.deleted_tag_ids);
    let deleted_set = deleted_tag_ids.iter().cloned().collect::<HashSet<_>>();
    let mut available_tags = existing_tags
        .iter()
        .filter(|tag| !deleted_set.contains(&tag.id))
        .cloned()
        .collect::<Vec<_>>();
    let mut created_tags = Vec::new();
    let mut selected_created_tag_ids = Vec::new();
    for created in options.created_tags {
        let normalized = normalize_marked_tag_name(&created.name)?;
        ensure_unique_marked_tag_name(&available_tags, &normalized, None)?;
        let tag = MarkedTag {
            id: generate_marked_tag_id(),
            name: normalized,
        };
        if created.selected {
            selected_created_tag_ids.push(tag.id.clone());
        }
        let operation = outbox_operation(
            &profile.id,
            &session.user_id,
            "tag",
            &tag.id,
            "upsert",
            0,
            serde_json::json!({"name":tag.name}),
        )?;
        available_tags.push(tag.clone());
        created_tags.push((tag, operation));
    }
    let mut selected_tag_ids = sanitize_existing_marked_tag_ids(
        &available_tags,
        options
            .selected_tag_ids
            .into_iter()
            .filter(|tag_id| !deleted_set.contains(tag_id))
            .collect(),
    );
    selected_tag_ids.extend(selected_created_tag_ids);
    selected_tag_ids.sort();
    selected_tag_ids.dedup();
    message.marked = options.marked;
    message.marked_tag_ids = if options.marked {
        selected_tag_ids
    } else {
        Vec::new()
    };
    message.marked_pinned = false;
    message.marked_due_date = if options.marked {
        normalize_marked_due_date(options.due_date)?
    } else {
        None
    };

    let mut cleaned_messages = Vec::new();
    if !deleted_set.is_empty() {
        let marked_messages = db::list_marked_messages_for_scope(
            &state.db_path,
            &profile.id,
            &session.user_id,
            None,
            None,
            None,
            None,
            None,
        )
        .map_err(|error| error.to_string())?;
        for marked_message in marked_messages {
            if !marked_message
                .marked_tag_ids
                .iter()
                .any(|tag_id| deleted_set.contains(tag_id))
            {
                continue;
            }
            let Some(mut existing_message) = db::get_message_for_scope(
                &state.db_path,
                &profile.id,
                &session.user_id,
                &marked_message.filename,
            )
            .map_err(|error| error.to_string())?
            else {
                continue;
            };
            let (message_id, revision) = db::get_message_sync_identity(
                &state.db_path,
                &profile.id,
                &session.user_id,
                &existing_message.filename,
            )
            .map_err(|error| error.to_string())?
            .ok_or_else(|| "消息同步标识不存在".to_string())?;
            existing_message
                .marked_tag_ids
                .retain(|tag_id| !deleted_set.contains(tag_id));
            let operation = outbox_operation(
                &profile.id,
                &session.user_id,
                "message",
                &message_id,
                "upsert",
                revision,
                supabase_message_payload(&existing_message),
            )?;
            cleaned_messages.push((
                existing_message.filename,
                existing_message.marked_tag_ids,
                operation,
            ));
        }
    }
    let deleted_at_ms = now_ms();
    let mut deleted_tags = Vec::new();
    for (tag, revision) in existing {
        if !deleted_set.contains(&tag.id) {
            continue;
        }
        let operation = outbox_operation(
            &profile.id,
            &session.user_id,
            "tag",
            &tag.id,
            "delete",
            revision,
            serde_json::json!({}),
        )?;
        deleted_tags.push((tag, revision, deleted_at_ms, operation));
    }
    Ok(SupabaseSendMarkedChanges {
        created_tags,
        cleaned_messages,
        deleted_tags,
    })
}

async fn persist_sent_message_with_marked_options(
    state: &AppState,
    endpoint: &WebDavEndpoint,
    message: &mut DbMessage,
    marked_options: Option<SendMarkedOptionsInput>,
) -> Result<SendMessageResult, String> {
    let _guard = state.sync_guard.lock().await;
    let applied_options =
        load_and_apply_send_marked_options(state, endpoint, marked_options.unwrap_or_default())
            .await?;

    message.marked = applied_options.marked;
    message.marked_tag_ids = applied_options.tag_ids.clone();
    message.marked_pinned = false;
    message.marked_due_date = applied_options.due_date.clone();

    db::upsert_message(&state.db_path, message).map_err(|err| err.to_string())?;
    let history_result = crate::history::upsert_history_entries(
        &state.http,
        endpoint,
        vec![message_to_history(message)],
    )
    .await?;
    invalidate_history_cache_for_paths(state, &endpoint.id, &history_result.touched_paths)?;
    if applied_options.tags_changed {
        crate::history::save_marked_tags(&state.http, endpoint, &applied_options.tags).await?;
        invalidate_history_cache_for_paths(
            state,
            &endpoint.id,
            &[crate::history::HISTORY_TAGS_PATH.to_string()],
        )?;
        db::replace_marked_tags(&state.db_path, &endpoint.id, &applied_options.tags)
            .map_err(|err| err.to_string())?;
    }
    if !applied_options.cleanup_targets.is_empty() {
        let history_result = crate::history::mutate_history_entries_by_targets(
            &state.http,
            endpoint,
            &applied_options.cleanup_targets,
            |entry| {
                let before_len = entry.marked_tag_ids.len();
                entry
                    .marked_tag_ids
                    .retain(|tag_id| applied_options.tags.iter().any(|tag| tag.id == *tag_id));
                before_len != entry.marked_tag_ids.len()
            },
        )
        .await?;
        invalidate_history_cache_for_paths(state, &endpoint.id, &history_result.touched_paths)?;
    }

    Ok(SendMessageResult {
        marked_tag_ids: applied_options.tag_ids,
        filename: message.filename.clone(),
        original_name: message.original_name.clone(),
        endpoint_id: endpoint.id.clone(),
        transcript_source: message.transcript_source.clone(),
        source_audio_mime_type: message.source_audio_mime_type.clone(),
        transcript_text: message
            .transcript_source
            .as_ref()
            .and_then(|_| message.content.clone()),
        transcript_raw_text: message.transcript_raw_text.clone(),
    })
}

#[cfg(test)]
fn apply_marked_tag_ids_to_entries(
    history_entries: &mut [HistoryEntry],
    filenames: &[String],
    tag_ids: &[String],
) -> usize {
    if filenames.is_empty() {
        return 0;
    }

    let filename_set: HashSet<&str> = filenames.iter().map(String::as_str).collect();
    let mut changed = 0;

    for entry in history_entries.iter_mut() {
        if !entry.marked || !filename_set.contains(entry.filename.as_str()) {
            continue;
        }
        if entry.marked_tag_ids == tag_ids {
            continue;
        }
        entry.marked_tag_ids = tag_ids.to_vec();
        changed += 1;
    }

    changed
}

fn apply_marked_state(
    marked_flag: &mut bool,
    marked_tag_ids: &mut Vec<String>,
    marked_pinned: &mut bool,
    marked_due_date: &mut Option<String>,
    marked: bool,
    tag_ids: &[String],
    due_date: Option<String>,
) {
    *marked_flag = marked;
    if marked {
        *marked_tag_ids = tag_ids.to_vec();
        *marked_due_date = due_date;
    } else {
        marked_tag_ids.clear();
        *marked_pinned = false;
        *marked_due_date = None;
    }
}

#[tauri::command]
async fn mark_message(
    state: State<'_, AppState>,
    filename: String,
    tag_ids: Option<Vec<String>>,
    due_date: Option<String>,
) -> Result<(), String> {
    set_message_marked(
        &state,
        filename,
        true,
        tag_ids.unwrap_or_default(),
        due_date,
    )
    .await
}

#[tauri::command]
async fn unmark_message(state: State<'_, AppState>, filename: String) -> Result<(), String> {
    set_message_marked(&state, filename, false, Vec::new(), None).await
}

async fn set_message_marked(
    state: &AppState,
    filename: String,
    marked: bool,
    tag_ids: Vec<String>,
    due_date: Option<String>,
) -> Result<(), String> {
    let settings = current_settings(state)?;
    if let Some((profile, session)) = active_supabase_context(state, &settings)? {
        let _guard = state.sync_guard.lock().await;
        let tags = db::list_tags_for_scope(&state.db_path, &profile.id, &session.user_id)
            .map_err(|error| error.to_string())?
            .into_iter()
            .map(|(tag, _)| tag)
            .collect::<Vec<_>>();
        let valid_tag_ids = sanitize_marked_tag_ids(&tags, tag_ids);
        let valid_due_date = if marked {
            normalize_marked_due_date(due_date)?
        } else {
            None
        };
        let mut message =
            db::get_message_for_scope(&state.db_path, &profile.id, &session.user_id, &filename)
                .map_err(|error| error.to_string())?
                .ok_or_else(|| "未找到消息".to_string())?;
        let (message_id, base_revision) =
            db::get_message_sync_identity(&state.db_path, &profile.id, &session.user_id, &filename)
                .map_err(|error| error.to_string())?
                .ok_or_else(|| "消息同步标识不存在".to_string())?;
        apply_marked_state(
            &mut message.marked,
            &mut message.marked_tag_ids,
            &mut message.marked_pinned,
            &mut message.marked_due_date,
            marked,
            &valid_tag_ids,
            valid_due_date.clone(),
        );
        let operation = outbox_operation(
            &profile.id,
            &session.user_id,
            "message",
            &message_id,
            "upsert",
            base_revision,
            supabase_message_payload(&message),
        )?;
        let changed = db::set_message_marked_and_enqueue(
            &state.db_path,
            &profile.id,
            &session.user_id,
            &filename,
            message.marked,
            &message.marked_tag_ids,
            message.marked_pinned,
            valid_due_date.as_deref(),
            &operation,
        )
        .map_err(|error| error.to_string())?;
        return if changed {
            notify_supabase_outbox_pending(state);
            Ok(())
        } else {
            Err("未找到消息".to_string())
        };
    }
    let endpoint = resolve_active_endpoint(&settings)?;
    let _guard = state.sync_guard.lock().await;
    let tags = db::list_marked_tags(&state.db_path, &endpoint.id).map_err(|err| err.to_string())?;
    let valid_tag_ids = sanitize_marked_tag_ids(&tags, tag_ids);
    let valid_due_date = if marked {
        normalize_marked_due_date(due_date)?
    } else {
        None
    };

    let mut changed = false;
    let existing =
        db::get_message(&state.db_path, &endpoint.id, &filename).map_err(|err| err.to_string())?;
    let mut local_message = existing.ok_or_else(|| "未找到消息".to_string())?;

    if local_message.marked != marked
        || local_message.marked_tag_ids != valid_tag_ids
        || local_message.marked_pinned
            != (if marked {
                local_message.marked_pinned
            } else {
                false
            })
        || local_message.marked_due_date != valid_due_date
    {
        apply_marked_state(
            &mut local_message.marked,
            &mut local_message.marked_tag_ids,
            &mut local_message.marked_pinned,
            &mut local_message.marked_due_date,
            marked,
            &valid_tag_ids,
            valid_due_date,
        );
        db::upsert_message(&state.db_path, &local_message).map_err(|err| err.to_string())?;
        changed = true;
    }

    if changed {
        let pending = PendingMarkedSync {
            endpoint_id: local_message.endpoint_id.clone(),
            filename: local_message.filename.clone(),
            timestamp_ms: local_message.timestamp_ms,
            marked: local_message.marked,
            marked_tag_ids: local_message.marked_tag_ids.clone(),
            marked_pinned: local_message.marked_pinned,
            marked_due_date: local_message.marked_due_date.clone(),
            updated_at_ms: now_ms(),
        };
        db::upsert_pending_marked_sync(&state.db_path, &pending).map_err(|err| err.to_string())?;
        schedule_marked_history_sync(state, endpoint, pending);
    }

    Ok(())
}

fn schedule_marked_history_sync(
    state: &AppState,
    endpoint: WebDavEndpoint,
    pending: PendingMarkedSync,
) {
    let http = state.http.clone();
    let db_path = state.db_path.clone();
    let cache_dir = history_cache_dir(state, &endpoint.id);
    let sync_guard = Arc::clone(&state.sync_guard);
    tauri::async_runtime::spawn(async move {
        let _guard = sync_guard.lock().await;
        if let Err(err) =
            flush_marked_history_entries(&http, &endpoint, &db_path, &cache_dir, &[pending.clone()])
                .await
        {
            log::warn!(
                "后台同步标记状态失败 endpoint={} filename={}: {}",
                pending.endpoint_id,
                pending.filename,
                err
            );
        }
    });
}

async fn flush_marked_history_entries(
    http: &Client,
    endpoint: &WebDavEndpoint,
    db_path: &Path,
    cache_dir: &Path,
    pending_entries: &[PendingMarkedSync],
) -> Result<(), String> {
    if pending_entries.is_empty() {
        return Ok(());
    }
    let targets: Vec<crate::history::HistoryEntryTarget> = pending_entries
        .iter()
        .map(|pending| (pending.filename.clone(), pending.timestamp_ms))
        .collect();
    let by_filename: HashMap<String, PendingMarkedSync> = pending_entries
        .iter()
        .cloned()
        .map(|pending| (pending.filename.clone(), pending))
        .collect();

    let history_result =
        crate::history::mutate_history_entries_by_targets(http, endpoint, &targets, |entry| {
            let Some(pending) = by_filename.get(&entry.filename) else {
                return false;
            };
            let before = (
                entry.marked,
                entry.marked_tag_ids.clone(),
                entry.marked_pinned,
                entry.marked_due_date.clone(),
            );
            entry.marked = pending.marked;
            entry.marked_tag_ids = pending.marked_tag_ids.clone();
            entry.marked_tag_ids.sort();
            entry.marked_pinned = pending.marked_pinned;
            entry.marked_due_date = pending.marked_due_date.clone();
            before
                != (
                    entry.marked,
                    entry.marked_tag_ids.clone(),
                    entry.marked_pinned,
                    entry.marked_due_date.clone(),
                )
        })
        .await?;
    crate::history::invalidate_history_cache_paths(cache_dir, &history_result.touched_paths)?;
    let cleared: Vec<(String, i64, i64)> = pending_entries
        .iter()
        .map(|pending| {
            (
                pending.filename.clone(),
                pending.timestamp_ms,
                pending.updated_at_ms,
            )
        })
        .collect();
    db::clear_pending_marked_sync_exact(db_path, &endpoint.id, &cleared)
        .map_err(|err| err.to_string())
}

fn apply_pending_marked_sync_to_message(message: &mut DbMessage, pending: &PendingMarkedSync) {
    message.marked = pending.marked;
    message.marked_tag_ids = pending.marked_tag_ids.clone();
    message.marked_pinned = pending.marked_pinned;
    message.marked_due_date = pending.marked_due_date.clone();
}

fn apply_pending_marked_sync_to_history(history: &mut HistoryEntry, pending: &PendingMarkedSync) {
    history.marked = pending.marked;
    history.marked_tag_ids = pending.marked_tag_ids.clone();
    history.marked_tag_ids.sort();
    history.marked_pinned = pending.marked_pinned;
    history.marked_due_date = pending.marked_due_date.clone();
}

fn pending_marked_sync_map(pending: &[PendingMarkedSync]) -> HashMap<String, PendingMarkedSync> {
    pending
        .iter()
        .cloned()
        .map(|entry| (entry.filename.clone(), entry))
        .collect()
}

#[tauri::command]
async fn set_marked_messages_tags(
    state: State<'_, AppState>,
    filenames: Vec<String>,
    tag_ids: Vec<String>,
) -> Result<usize, String> {
    set_marked_messages_tags_impl(&state, filenames, tag_ids).await
}

async fn set_marked_messages_tags_impl(
    state: &AppState,
    filenames: Vec<String>,
    tag_ids: Vec<String>,
) -> Result<usize, String> {
    let settings = current_settings(state)?;
    if let Some((profile, session)) = active_supabase_context(state, &settings)? {
        let _guard = state.sync_guard.lock().await;
        let mut unique_filenames: Vec<String> = filenames
            .into_iter()
            .map(|filename| filename.trim().to_string())
            .filter(|filename| !filename.is_empty())
            .collect();
        unique_filenames.sort();
        unique_filenames.dedup();
        if unique_filenames.is_empty() {
            return Ok(0);
        }
        let tags = db::list_tags_for_scope(&state.db_path, &profile.id, &session.user_id)
            .map_err(|error| error.to_string())?
            .into_iter()
            .map(|(tag, _)| tag)
            .collect::<Vec<_>>();
        let valid_tag_ids = sanitize_marked_tag_ids(&tags, tag_ids);
        let mut updates = Vec::new();
        for filename in unique_filenames {
            let Some(mut message) =
                db::get_message_for_scope(&state.db_path, &profile.id, &session.user_id, &filename)
                    .map_err(|error| error.to_string())?
            else {
                continue;
            };
            if !message.marked || message.marked_tag_ids == valid_tag_ids {
                continue;
            }
            let (message_id, base_revision) = db::get_message_sync_identity(
                &state.db_path,
                &profile.id,
                &session.user_id,
                &filename,
            )
            .map_err(|error| error.to_string())?
            .ok_or_else(|| "消息同步标识不存在".to_string())?;
            message.marked_tag_ids = valid_tag_ids.clone();
            let operation = outbox_operation(
                &profile.id,
                &session.user_id,
                "message",
                &message_id,
                "upsert",
                base_revision,
                supabase_message_payload(&message),
            )?;
            updates.push((filename, valid_tag_ids.clone(), operation));
        }
        let changed = db::set_messages_marked_tags_and_enqueue(
            &state.db_path,
            &profile.id,
            &session.user_id,
            &updates,
        )
        .map_err(|error| error.to_string())?;
        if changed > 0 {
            notify_supabase_outbox_pending(state);
        }
        return Ok(changed);
    }
    let endpoint = resolve_active_endpoint(&settings)?;
    let _guard = state.sync_guard.lock().await;

    let mut unique_filenames: Vec<String> = filenames
        .into_iter()
        .map(|filename| filename.trim().to_string())
        .filter(|filename| !filename.is_empty())
        .collect();
    unique_filenames.sort();
    unique_filenames.dedup();
    if unique_filenames.is_empty() {
        return Ok(0);
    }

    let tags = db::list_marked_tags(&state.db_path, &endpoint.id).map_err(|err| err.to_string())?;
    let valid_tag_ids = sanitize_marked_tag_ids(&tags, tag_ids);
    let mut pending_entries = Vec::new();
    for filename in &unique_filenames {
        if let Some(mut message) = db::get_message(&state.db_path, &endpoint.id, filename)
            .map_err(|err| err.to_string())?
        {
            if !message.marked || message.marked_tag_ids == valid_tag_ids {
                continue;
            }
            message.marked_tag_ids = valid_tag_ids.clone();
            db::upsert_message(&state.db_path, &message).map_err(|err| err.to_string())?;
            let pending = PendingMarkedSync {
                endpoint_id: message.endpoint_id.clone(),
                filename: message.filename.clone(),
                timestamp_ms: message.timestamp_ms,
                marked: message.marked,
                marked_tag_ids: message.marked_tag_ids.clone(),
                marked_pinned: message.marked_pinned,
                marked_due_date: message.marked_due_date.clone(),
                updated_at_ms: now_ms(),
            };
            db::upsert_pending_marked_sync(&state.db_path, &pending)
                .map_err(|err| err.to_string())?;
            pending_entries.push(pending);
        }
    }

    if pending_entries.is_empty() {
        return Ok(0);
    }
    for pending in pending_entries.iter().cloned() {
        schedule_marked_history_sync(state, endpoint.clone(), pending);
    }
    Ok(pending_entries.len())
}

#[tauri::command]
fn list_marked_tags(state: State<'_, AppState>) -> Result<Vec<MarkedTag>, String> {
    let settings = current_settings(&state)?;
    if let Some((profile, session)) = active_supabase_context(&state, &settings)? {
        return db::list_tags_for_scope(&state.db_path, &profile.id, &session.user_id)
            .map(|items| items.into_iter().map(|(tag, _)| tag).collect())
            .map_err(|error| error.to_string());
    }
    let endpoint = resolve_active_endpoint(&settings)?;
    db::list_marked_tags(&state.db_path, &endpoint.id).map_err(|err| err.to_string())
}

#[tauri::command]
async fn create_marked_tag(state: State<'_, AppState>, name: String) -> Result<MarkedTag, String> {
    create_marked_tag_impl(&state, name).await
}

async fn create_marked_tag_impl(state: &AppState, name: String) -> Result<MarkedTag, String> {
    let settings = current_settings(state)?;
    if let Some((profile, session)) = active_supabase_context(state, &settings)? {
        let _guard = state.sync_guard.lock().await;
        let normalized = normalize_marked_tag_name(&name)?;
        let existing = db::list_tags_for_scope(&state.db_path, &profile.id, &session.user_id)
            .map_err(|error| error.to_string())?;
        let tags = existing
            .iter()
            .map(|(tag, _)| tag.clone())
            .collect::<Vec<_>>();
        ensure_unique_marked_tag_name(&tags, &normalized, None)?;
        let tag = MarkedTag {
            id: generate_marked_tag_id(),
            name: normalized,
        };
        let operation = outbox_operation(
            &profile.id,
            &session.user_id,
            "tag",
            &tag.id,
            "upsert",
            0,
            serde_json::json!({"name":tag.name}),
        )?;
        db::save_tag_and_enqueue(
            &state.db_path,
            &profile.id,
            &session.user_id,
            &tag,
            0,
            None,
            &operation,
        )
        .map_err(|error| error.to_string())?;
        notify_supabase_outbox_pending(state);
        return Ok(tag);
    }
    let endpoint = resolve_active_endpoint(&settings)?;
    let _guard = state.sync_guard.lock().await;
    let mut tags =
        db::list_marked_tags(&state.db_path, &endpoint.id).map_err(|err| err.to_string())?;
    let normalized = normalize_marked_tag_name(&name)?;
    ensure_unique_marked_tag_name(&tags, &normalized, None)?;
    let tag = MarkedTag {
        id: generate_marked_tag_id(),
        name: normalized,
    };
    tags.push(tag.clone());
    tags.sort_by(|left, right| left.name.cmp(&right.name));
    crate::history::save_marked_tags(&state.http, &endpoint, &tags).await?;
    invalidate_history_cache_for_paths(
        state,
        &endpoint.id,
        &[crate::history::HISTORY_TAGS_PATH.to_string()],
    )?;
    db::replace_marked_tags(&state.db_path, &endpoint.id, &tags).map_err(|err| err.to_string())?;
    Ok(tag)
}

#[tauri::command]
async fn delete_marked_tag(state: State<'_, AppState>, tag_id: String) -> Result<(), String> {
    let settings = current_settings(&state)?;
    if let Some((profile, session)) = active_supabase_context(&state, &settings)? {
        let _guard = state.sync_guard.lock().await;
        let existing = db::list_tags_for_scope(&state.db_path, &profile.id, &session.user_id)
            .map_err(|error| error.to_string())?;
        let (tag, revision) = existing
            .into_iter()
            .find(|(tag, _)| tag.id == tag_id)
            .ok_or_else(|| "未找到标签".to_string())?;
        let mut message_updates = Vec::new();
        let marked_messages = db::list_marked_messages_for_scope(
            &state.db_path,
            &profile.id,
            &session.user_id,
            Some(&tag.id),
            None,
            None,
            None,
            None,
        )
        .map_err(|error| error.to_string())?;
        for marked_message in marked_messages {
            let Some(mut message) = db::get_message_for_scope(
                &state.db_path,
                &profile.id,
                &session.user_id,
                &marked_message.filename,
            )
            .map_err(|error| error.to_string())?
            else {
                continue;
            };
            let (message_id, base_revision) = db::get_message_sync_identity(
                &state.db_path,
                &profile.id,
                &session.user_id,
                &message.filename,
            )
            .map_err(|error| error.to_string())?
            .ok_or_else(|| "消息同步标识不存在".to_string())?;
            message.marked_tag_ids.retain(|item| item != &tag.id);
            let message_operation = outbox_operation(
                &profile.id,
                &session.user_id,
                "message",
                &message_id,
                "upsert",
                base_revision,
                supabase_message_payload(&message),
            )?;
            message_updates.push((
                message.filename.clone(),
                message.marked_tag_ids.clone(),
                message_operation,
            ));
        }
        let operation = outbox_operation(
            &profile.id,
            &session.user_id,
            "tag",
            &tag.id,
            "delete",
            revision,
            serde_json::json!({}),
        )?;
        db::delete_tag_cleanup_messages_and_enqueue(
            &state.db_path,
            &profile.id,
            &session.user_id,
            &tag,
            revision,
            now_ms(),
            &message_updates,
            &operation,
        )
        .map_err(|error| error.to_string())?;
        notify_supabase_outbox_pending(&state);
        return Ok(());
    }
    let endpoint = resolve_active_endpoint(&settings)?;
    let _guard = state.sync_guard.lock().await;
    let mut tags =
        db::list_marked_tags(&state.db_path, &endpoint.id).map_err(|err| err.to_string())?;
    let before = tags.len();
    tags.retain(|tag| tag.id != tag_id);
    if before == tags.len() {
        return Err("未找到标签".to_string());
    }
    let mut targets = Vec::new();
    let marked_messages =
        db::list_marked_messages(&state.db_path, &endpoint.id, Some(&tag_id), None)
            .map_err(|err| err.to_string())?;
    for message in marked_messages {
        if let Some(mut db_message) =
            db::get_message(&state.db_path, &endpoint.id, &message.filename)
                .map_err(|err| err.to_string())?
        {
            db_message
                .marked_tag_ids
                .retain(|entry_tag_id| entry_tag_id != &tag_id);
            db::upsert_message(&state.db_path, &db_message).map_err(|err| err.to_string())?;
            targets.push((db_message.filename.clone(), db_message.timestamp_ms));
        }
    }
    crate::history::save_marked_tags(&state.http, &endpoint, &tags).await?;
    invalidate_history_cache_for_paths(
        state.inner(),
        &endpoint.id,
        &[crate::history::HISTORY_TAGS_PATH.to_string()],
    )?;
    db::replace_marked_tags(&state.db_path, &endpoint.id, &tags).map_err(|err| err.to_string())?;
    if !targets.is_empty() {
        let history_result = crate::history::mutate_history_entries_by_targets(
            &state.http,
            &endpoint,
            &targets,
            |entry| {
                let before_len = entry.marked_tag_ids.len();
                entry
                    .marked_tag_ids
                    .retain(|entry_tag_id| entry_tag_id != &tag_id);
                before_len != entry.marked_tag_ids.len()
            },
        )
        .await?;
        invalidate_history_cache_for_paths(
            state.inner(),
            &endpoint.id,
            &history_result.touched_paths,
        )?;
    }
    Ok(())
}

#[tauri::command]
async fn rename_marked_tag(
    state: State<'_, AppState>,
    tag_id: String,
    name: String,
) -> Result<(), String> {
    let settings = current_settings(&state)?;
    if let Some((profile, session)) = active_supabase_context(&state, &settings)? {
        let _guard = state.sync_guard.lock().await;
        let normalized = normalize_marked_tag_name(&name)?;
        let existing = db::list_tags_for_scope(&state.db_path, &profile.id, &session.user_id)
            .map_err(|error| error.to_string())?;
        let tags = existing
            .iter()
            .map(|(tag, _)| tag.clone())
            .collect::<Vec<_>>();
        ensure_unique_marked_tag_name(&tags, &normalized, Some(&tag_id))?;
        let (_, revision) = existing
            .into_iter()
            .find(|(tag, _)| tag.id == tag_id)
            .ok_or_else(|| "未找到标签".to_string())?;
        let tag = MarkedTag {
            id: tag_id,
            name: normalized,
        };
        let operation = outbox_operation(
            &profile.id,
            &session.user_id,
            "tag",
            &tag.id,
            "upsert",
            revision,
            serde_json::json!({"name":tag.name}),
        )?;
        db::save_tag_and_enqueue(
            &state.db_path,
            &profile.id,
            &session.user_id,
            &tag,
            revision,
            None,
            &operation,
        )
        .map_err(|error| error.to_string())?;
        notify_supabase_outbox_pending(&state);
        return Ok(());
    }
    let endpoint = resolve_active_endpoint(&settings)?;
    let _guard = state.sync_guard.lock().await;
    let mut tags =
        db::list_marked_tags(&state.db_path, &endpoint.id).map_err(|err| err.to_string())?;
    let normalized = normalize_marked_tag_name(&name)?;
    ensure_unique_marked_tag_name(&tags, &normalized, Some(&tag_id))?;
    let mut found = false;
    for tag in tags.iter_mut() {
        if tag.id == tag_id {
            tag.name = normalized.clone();
            found = true;
            break;
        }
    }
    if !found {
        return Err("未找到标签".to_string());
    }
    tags.sort_by(|left, right| left.name.cmp(&right.name));
    crate::history::save_marked_tags(&state.http, &endpoint, &tags).await?;
    invalidate_history_cache_for_paths(
        state.inner(),
        &endpoint.id,
        &[crate::history::HISTORY_TAGS_PATH.to_string()],
    )?;
    db::replace_marked_tags(&state.db_path, &endpoint.id, &tags).map_err(|err| err.to_string())?;
    Ok(())
}

#[tauri::command]
async fn toggle_marked_message_pin(
    state: State<'_, AppState>,
    filename: String,
) -> Result<bool, String> {
    toggle_marked_message_pin_impl(&state, filename).await
}

async fn toggle_marked_message_pin_impl(
    state: &AppState,
    filename: String,
) -> Result<bool, String> {
    let settings = current_settings(state)?;
    if let Some((profile, session)) = active_supabase_context(state, &settings)? {
        let _guard = state.sync_guard.lock().await;
        let mut message =
            db::get_message_for_scope(&state.db_path, &profile.id, &session.user_id, &filename)
                .map_err(|error| error.to_string())?
                .ok_or_else(|| "未找到消息".to_string())?;
        if !message.marked {
            return Err("未标记消息不能置顶".to_string());
        }
        let (message_id, base_revision) =
            db::get_message_sync_identity(&state.db_path, &profile.id, &session.user_id, &filename)
                .map_err(|error| error.to_string())?
                .ok_or_else(|| "消息同步标识不存在".to_string())?;
        message.marked_pinned = !message.marked_pinned;
        let operation = outbox_operation(
            &profile.id,
            &session.user_id,
            "message",
            &message_id,
            "upsert",
            base_revision,
            supabase_message_payload(&message),
        )?;
        let changed = db::set_message_marked_and_enqueue(
            &state.db_path,
            &profile.id,
            &session.user_id,
            &filename,
            message.marked,
            &message.marked_tag_ids,
            message.marked_pinned,
            message.marked_due_date.as_deref(),
            &operation,
        )
        .map_err(|error| error.to_string())?;
        let pinned = changed
            .then_some(message.marked_pinned)
            .ok_or_else(|| "未找到消息".to_string())?;
        notify_supabase_outbox_pending(state);
        return Ok(pinned);
    }
    let endpoint = resolve_active_endpoint(&settings)?;
    let _guard = state.sync_guard.lock().await;
    let mut message = db::get_message(&state.db_path, &endpoint.id, &filename)
        .map_err(|err| err.to_string())?
        .ok_or_else(|| "未找到消息".to_string())?;
    if !message.marked {
        return Err("未标记消息不能置顶".to_string());
    }
    message.marked_pinned = !message.marked_pinned;
    let pinned = message.marked_pinned;
    db::upsert_message(&state.db_path, &message).map_err(|err| err.to_string())?;
    let pending = PendingMarkedSync {
        endpoint_id: message.endpoint_id.clone(),
        filename: message.filename.clone(),
        timestamp_ms: message.timestamp_ms,
        marked: message.marked,
        marked_tag_ids: message.marked_tag_ids.clone(),
        marked_pinned: message.marked_pinned,
        marked_due_date: message.marked_due_date.clone(),
        updated_at_ms: now_ms(),
    };
    db::upsert_pending_marked_sync(&state.db_path, &pending).map_err(|err| err.to_string())?;
    schedule_marked_history_sync(state, endpoint, pending);
    Ok(pinned)
}

#[tauri::command]
fn list_marked_messages(
    state: State<'_, AppState>,
    tag_id: Option<String>,
    search_query: Option<String>,
    limit: Option<i64>,
    offset: Option<i64>,
    pending_only: Option<bool>,
) -> Result<MessagesResult, String> {
    let settings = current_settings(&state)?;
    if let Some((profile, session)) = active_supabase_context(&state, &settings)? {
        let today = today_due_date_string();
        let pending_due_date = pending_only.unwrap_or(false).then_some(today.as_str());
        let marked_count = db::count_unfinished_marked_messages_for_scope(
            &state.db_path,
            &profile.id,
            &session.user_id,
            &today,
        )
        .map_err(|error| error.to_string())?;
        let total = db::count_marked_messages_for_scope(
            &state.db_path,
            &profile.id,
            &session.user_id,
            tag_id.as_deref(),
            search_query.as_deref(),
            pending_due_date,
        )
        .map_err(|error| error.to_string())?;
        let messages = db::list_marked_messages_for_scope(
            &state.db_path,
            &profile.id,
            &session.user_id,
            tag_id.as_deref(),
            search_query.as_deref(),
            limit,
            offset,
            pending_due_date,
        )
        .map_err(|error| error.to_string())?;
        let current_offset = offset.unwrap_or(0).max(0);
        let current_limit = limit.unwrap_or(total).max(0);
        return Ok(MessagesResult {
            messages,
            total,
            has_more: current_offset + current_limit < total,
            marked_count,
        });
    }
    let endpoint = resolve_active_endpoint(&settings)?;
    let marked_count = count_unfinished_marked_messages(&state, &endpoint.id)?;
    let today = today_due_date_string();
    let pending_due_date = pending_only.unwrap_or(false).then_some(today.as_str());
    let total = db::count_marked_messages(
        &state.db_path,
        &endpoint.id,
        tag_id.as_deref(),
        search_query.as_deref(),
        pending_due_date,
    )
    .map_err(|err| err.to_string())?;
    let messages = db::list_marked_messages_paged(
        &state.db_path,
        &endpoint.id,
        tag_id.as_deref(),
        search_query.as_deref(),
        limit,
        offset,
        pending_due_date,
    )
    .map_err(|err| err.to_string())?;
    let current_offset = offset.unwrap_or(0).max(0);
    let current_limit = limit.unwrap_or(total).max(0);
    Ok(MessagesResult {
        messages,
        total,
        has_more: current_offset + current_limit < total,
        marked_count,
    })
}

#[tauri::command]
fn list_messages(
    state: State<'_, AppState>,
    limit: Option<i64>,
    offset: Option<i64>,
    only_marked: Option<bool>,
    search_query: Option<String>,
) -> Result<MessagesResult, String> {
    let settings = current_settings(&state)?;
    if let Some((profile, session)) = active_supabase_context(&state, &settings)? {
        let marked_filter = only_marked.unwrap_or(false);
        let total = db::count_messages_for_scope(
            &state.db_path,
            &profile.id,
            &session.user_id,
            marked_filter,
        )
        .map_err(|error| error.to_string())?;
        let messages = db::list_messages_for_scope(
            &state.db_path,
            &profile.id,
            &session.user_id,
            limit,
            offset,
            marked_filter,
            search_query.as_deref(),
        )
        .map_err(|error| error.to_string())?;
        let current_offset = offset.unwrap_or(0);
        let current_limit = limit.unwrap_or(total);
        return Ok(MessagesResult {
            messages,
            total,
            has_more: current_offset + current_limit < total,
            marked_count: db::count_messages_for_scope(
                &state.db_path,
                &profile.id,
                &session.user_id,
                true,
            )
            .map_err(|error| error.to_string())?,
        });
    }
    let endpoint = resolve_active_endpoint(&settings)?;

    let marked_filter = only_marked.unwrap_or(false);
    let total = db::count_messages(&state.db_path, &endpoint.id, marked_filter)
        .map_err(|err| err.to_string())?;

    let marked_count = count_unfinished_marked_messages(&state, &endpoint.id)?;

    let messages = db::list_messages_paged(
        &state.db_path,
        &endpoint.id,
        limit,
        offset,
        marked_filter,
        search_query.as_deref(),
    )
    .map_err(|err| err.to_string())?;

    let current_offset = offset.unwrap_or(0);
    let current_limit = limit.unwrap_or(total);
    let has_more = current_offset + current_limit < total;

    Ok(MessagesResult {
        messages,
        total,
        has_more,
        marked_count,
    })
}

fn bulk_download_extension(name: &str, mime_type: Option<&str>) -> String {
    let extension = Path::new(name)
        .extension()
        .and_then(|value| value.to_str())
        .unwrap_or("")
        .trim()
        .to_lowercase();
    if !extension.is_empty() {
        return extension;
    }
    mime_type
        .and_then(|value| value.split('/').nth(1))
        .and_then(|value| value.split(';').next())
        .unwrap_or("")
        .trim()
        .to_lowercase()
}

fn bulk_download_category(extension: &str, mime_type: Option<&str>) -> &'static str {
    const IMAGE: &[&str] = &["png", "jpg", "jpeg", "gif", "webp", "bmp", "svg", "avif"];
    const AUDIO: &[&str] = &["mp3", "wav", "m4a", "aac", "flac", "ogg", "opus", "wma"];
    const VIDEO: &[&str] = &["mp4", "mov", "mkv", "avi", "webm", "m4v", "wmv", "flv"];
    if IMAGE.contains(&extension) || mime_type.is_some_and(|value| value.starts_with("image/")) {
        "image"
    } else if AUDIO.contains(&extension)
        || mime_type.is_some_and(|value| value.starts_with("audio/"))
    {
        "audio"
    } else if VIDEO.contains(&extension)
        || mime_type.is_some_and(|value| value.starts_with("video/"))
    {
        "video"
    } else {
        "file"
    }
}

fn bulk_download_status(row: &DbBulkDownloadResource) -> String {
    if row.partial_bytes.unwrap_or(0) > 0 {
        return "resumable".to_string();
    }
    if row.download_status.as_deref() == Some("complete") {
        let exists = row
            .saved_path
            .as_deref()
            .filter(|path| !path.trim().is_empty())
            .map(Path::new)
            .is_some_and(Path::is_file);
        return if exists { "downloaded" } else { "missing" }.to_string();
    }
    if row.download_status.as_deref() == Some("error") {
        return "error".to_string();
    }
    "notDownloaded".to_string()
}

fn map_bulk_download_resource(
    endpoint_id: &str,
    row: DbBulkDownloadResource,
) -> BulkDownloadResource {
    let is_speech_audio = row.transcript_source.as_deref() == Some("speech-to-text");
    let extension =
        bulk_download_extension(&row.original_name, row.source_audio_mime_type.as_deref());
    let category = bulk_download_category(&extension, row.source_audio_mime_type.as_deref());
    let status = bulk_download_status(&row);
    BulkDownloadResource {
        key: format!(
            "{}::{}::{}",
            endpoint_id,
            row.filename,
            if is_speech_audio {
                "speech-audio"
            } else {
                "file"
            }
        ),
        endpoint_id: endpoint_id.to_string(),
        filename: row.filename,
        original_name: row.original_name,
        category: category.to_string(),
        extension,
        size: row.size.max(0),
        timestamp_ms: row.timestamp_ms,
        status,
        is_speech_audio,
    }
}

fn bulk_download_status_counts(resources: &[BulkDownloadResource]) -> BulkDownloadStatusCounts {
    let mut counts = BulkDownloadStatusCounts {
        new_download: 0,
        resumable: 0,
        redownload: 0,
        skipped: 0,
    };
    for resource in resources {
        match resource.status.as_str() {
            "downloaded" => counts.skipped += 1,
            "resumable" => counts.resumable += 1,
            "missing" | "error" => counts.redownload += 1,
            _ => counts.new_download += 1,
        }
    }
    counts
}

fn query_bulk_download_resources(
    state: &AppState,
    endpoint_id: &str,
    owner_scope: &str,
    input: &BulkDownloadQueryInput,
) -> Result<
    (
        Vec<BulkDownloadResource>,
        Vec<BulkDownloadCategoryCount>,
        Vec<String>,
    ),
    String,
> {
    let rows = db::list_bulk_download_candidates(
        &state.db_path,
        endpoint_id,
        owner_scope,
        input.search_query.as_deref(),
    )
    .map_err(|err| format!("读取批量下载资料失败: {err}"))?;
    let resources: Vec<_> = rows
        .into_iter()
        .map(|row| map_bulk_download_resource(endpoint_id, row))
        .collect();
    let mut counts = HashMap::<String, i64>::new();
    counts.insert("all".to_string(), resources.len() as i64);
    for resource in &resources {
        *counts.entry(resource.category.clone()).or_insert(0) += 1;
    }
    let category = input.category.as_deref().unwrap_or("all");
    let category_resources: Vec<_> = resources
        .into_iter()
        .filter(|resource| category == "all" || resource.category == category)
        .collect();
    let mut extensions: Vec<_> = category_resources
        .iter()
        .map(|resource| resource.extension.clone())
        .filter(|value| !value.is_empty())
        .collect::<HashSet<_>>()
        .into_iter()
        .collect();
    extensions.sort();
    let wanted_extension = input
        .extension
        .as_deref()
        .map(str::trim)
        .unwrap_or("")
        .to_lowercase();
    let filtered = category_resources
        .into_iter()
        .filter(|resource| wanted_extension.is_empty() || resource.extension == wanted_extension)
        .collect();
    let category_counts = ["all", "file", "image", "audio", "video"]
        .into_iter()
        .map(|category| BulkDownloadCategoryCount {
            category: category.to_string(),
            count: counts.get(category).copied().unwrap_or(0),
        })
        .collect();
    Ok((filtered, category_counts, extensions))
}

fn active_bulk_download_scope(state: &AppState) -> Result<(String, String), String> {
    let settings = current_settings(state)?;
    match storage_provider::resolve_active_provider(&settings)? {
        storage_provider::ProviderConfig::Webdav(endpoint) => Ok((endpoint.id, String::new())),
        storage_provider::ProviderConfig::Supabase(profile) => {
            let session = state
                .supabase_sessions
                .lock()
                .map_err(|_| "读取 Supabase 会话失败".to_string())?
                .get(&profile.id)
                .cloned()
                .ok_or_else(|| "请先登录当前 Supabase 存储空间".to_string())?;
            Ok((profile.id, session.user_id))
        }
    }
}

#[tauri::command]
fn list_bulk_download_resources(
    state: State<'_, AppState>,
    input: Option<BulkDownloadQueryInput>,
) -> Result<BulkDownloadResourcesResult, String> {
    list_bulk_download_resources_for_state(&state, input.unwrap_or_default())
}

fn list_bulk_download_resources_for_state(
    state: &AppState,
    input: BulkDownloadQueryInput,
) -> Result<BulkDownloadResourcesResult, String> {
    let (profile_id, owner_scope) = active_bulk_download_scope(state)?;
    let page = input.page.unwrap_or(1).max(1);
    let page_size = input.page_size.unwrap_or(60).clamp(10, 200);
    let (resources, category_counts, extensions) =
        query_bulk_download_resources(state, &profile_id, &owner_scope, &input)?;
    let total = resources.len() as i64;
    let total_size = resources.iter().map(|resource| resource.size).sum();
    let status_counts = bulk_download_status_counts(&resources);
    let total_pages = ((total + page_size - 1) / page_size).max(1);
    let bounded_page = page.min(total_pages);
    let offset = ((bounded_page - 1) * page_size) as usize;
    let page_resources = resources
        .into_iter()
        .skip(offset)
        .take(page_size as usize)
        .collect();
    Ok(BulkDownloadResourcesResult {
        resources: page_resources,
        total,
        total_size,
        page: bounded_page,
        page_size,
        total_pages,
        category_counts,
        extensions,
        status_counts,
    })
}

fn resolve_bulk_download_selection_for_state(
    state: &AppState,
    input: BulkDownloadQueryInput,
) -> Result<BulkDownloadSelectionResult, String> {
    let (profile_id, owner_scope) = active_bulk_download_scope(state)?;
    let (resources, _, _) =
        query_bulk_download_resources(state, &profile_id, &owner_scope, &input)?;
    let total = resources.len() as i64;
    let total_size = resources.iter().map(|resource| resource.size).sum();
    let status_counts = bulk_download_status_counts(&resources);
    Ok(BulkDownloadSelectionResult {
        resources,
        total,
        total_size,
        status_counts,
    })
}

#[tauri::command]
fn resolve_bulk_download_selection(
    state: State<'_, AppState>,
    input: Option<BulkDownloadQueryInput>,
) -> Result<BulkDownloadSelectionResult, String> {
    resolve_bulk_download_selection_for_state(&state, input.unwrap_or_default())
}

fn prepare_bulk_download_resources_for_state(
    state: &AppState,
    input: PrepareBulkDownloadInput,
) -> Result<BulkDownloadSelectionResult, String> {
    let (profile_id, owner_scope) = active_bulk_download_scope(state)?;
    let wanted: HashSet<_> = input.keys.into_iter().collect();
    let (resources, _, _) = query_bulk_download_resources(
        state,
        &profile_id,
        &owner_scope,
        &BulkDownloadQueryInput::default(),
    )?;
    let resources: Vec<_> = resources
        .into_iter()
        .filter(|resource| wanted.contains(&resource.key))
        .collect();
    let total = resources.len() as i64;
    let total_size = resources.iter().map(|resource| resource.size).sum();
    let status_counts = bulk_download_status_counts(&resources);
    Ok(BulkDownloadSelectionResult {
        resources,
        total,
        total_size,
        status_counts,
    })
}

#[tauri::command]
fn prepare_bulk_download_resources(
    state: State<'_, AppState>,
    input: PrepareBulkDownloadInput,
) -> Result<BulkDownloadSelectionResult, String> {
    prepare_bulk_download_resources_for_state(&state, input)
}

async fn hydrate_supabase_message_history(
    state: &AppState,
    profile: &StorageProfile,
    session: &supabase_auth::SupabaseSession,
    load_older: bool,
    limit: usize,
) -> Result<(), String> {
    let config = profile
        .supabase
        .as_ref()
        .ok_or_else(|| "Supabase 存储空间配置不完整".to_string())?;
    let mut cursor = db::get_supabase_history_cursor(&state.db_path, &profile.id, &session.user_id)
        .map_err(|error| format!("读取 Supabase 历史游标失败: {error}"))?;

    if !cursor.initialized {
        let page =
            supabase_sync::fetch_message_page(&state.http, config, session, None, limit).await?;
        db::apply_supabase_message_page(
            &state.db_path,
            &profile.id,
            &session.user_id,
            &page.messages,
            &page.tags,
            &page.attachments,
            page.has_more,
            true,
            now_ms(),
        )
        .map_err(|error| format!("保存 Supabase 最近消息失败: {error}"))?;
        cursor = db::get_supabase_history_cursor(&state.db_path, &profile.id, &session.user_id)
            .map_err(|error| format!("读取 Supabase 历史游标失败: {error}"))?;
    } else if !load_older {
        refresh_supabase_recent_message_page(state, profile, session, limit).await?;
    }

    if load_older && cursor.has_more_before {
        let before = cursor
            .oldest_timestamp_ms
            .zip(cursor.oldest_message_id.as_deref())
            .ok_or_else(|| "Supabase 历史游标不完整，请重新打开当前存储空间".to_string())?;
        let page =
            supabase_sync::fetch_message_page(&state.http, config, session, Some(before), limit)
                .await?;
        db::apply_supabase_message_page(
            &state.db_path,
            &profile.id,
            &session.user_id,
            &page.messages,
            &page.tags,
            &page.attachments,
            page.has_more,
            true,
            now_ms(),
        )
        .map_err(|error| format!("保存 Supabase 更早消息失败: {error}"))?;
    }
    Ok(())
}

#[tauri::command]
async fn list_messages_window(
    state: State<'_, AppState>,
    input: Option<ListMessagesWindowInput>,
) -> Result<MessagesWindowResult, String> {
    let settings = current_settings(&state)?;
    let provider = storage_provider::resolve_active_provider(&settings)?;
    let (profile_id, owner_scope, supabase_context) = match &provider {
        storage_provider::ProviderConfig::Webdav(endpoint) => (endpoint.id.clone(), None, None),
        storage_provider::ProviderConfig::Supabase(profile) => {
            let session = state
                .supabase_sessions
                .lock()
                .map_err(|_| "读取 Supabase 会话失败".to_string())?
                .get(&profile.id)
                .cloned()
                .ok_or_else(|| "请先登录当前 Supabase 存储空间".to_string())?;
            (
                profile.id.clone(),
                Some(session.user_id.clone()),
                Some((profile.clone(), session)),
            )
        }
    };
    let input = input.unwrap_or_default();
    let marked_filter = input.only_marked.unwrap_or(false);
    let limit = input.limit.unwrap_or(50).clamp(1, 200);
    let load_older = input.before_timestamp_ms.is_some() && input.before_filename.is_some();
    let load_latest =
        !load_older && input.after_timestamp_ms.is_none() && input.after_filename.is_none();

    if let Some((profile, session)) = supabase_context.as_ref() {
        let local_count = db::count_messages_for_scope(
            &state.db_path,
            &profile.id,
            &session.user_id,
            marked_filter,
        )
        .map_err(|error| error.to_string())?;
        let local_before_count = match (input.before_timestamp_ms, input.before_filename.as_deref())
        {
            (Some(timestamp_ms), Some(boundary)) => db::count_messages_before_for_scope(
                &state.db_path,
                &profile.id,
                &session.user_id,
                timestamp_ms,
                boundary,
                marked_filter,
            )
            .map_err(|error| error.to_string())?,
            _ => 0,
        };
        let should_load_remote_older = load_older && local_before_count < limit;
        if load_latest || should_load_remote_older {
            if let Err(error) = hydrate_supabase_message_history(
                &state,
                profile,
                session,
                should_load_remote_older,
                limit as usize,
            )
            .await
            {
                if local_count == 0 || (load_older && local_before_count == 0) {
                    return Err(error);
                }
            }
        }
    }

    let total = if let Some(owner_scope) = owner_scope.as_deref() {
        db::count_messages_for_scope(&state.db_path, &profile_id, owner_scope, marked_filter)
    } else {
        db::count_messages(&state.db_path, &profile_id, marked_filter)
    }
    .map_err(|err| err.to_string())?;
    let today = today_due_date_string();
    let marked_count = if let Some(owner_scope) = owner_scope.as_deref() {
        db::count_unfinished_marked_messages_for_scope(
            &state.db_path,
            &profile_id,
            owner_scope,
            &today,
        )
    } else {
        db::count_unfinished_marked_messages(&state.db_path, &profile_id, &today)
    }
    .map_err(|err| err.to_string())?;

    let messages = if let (Some(after_timestamp_ms), Some(after_filename)) =
        (input.after_timestamp_ms, input.after_filename.as_deref())
    {
        if let Some(owner_scope) = owner_scope.as_deref() {
            db::list_messages_after_for_scope(
                &state.db_path,
                &profile_id,
                owner_scope,
                after_timestamp_ms,
                after_filename,
                limit,
                marked_filter,
            )
        } else {
            db::list_messages_after(
                &state.db_path,
                &profile_id,
                after_timestamp_ms,
                after_filename,
                limit,
                marked_filter,
            )
        }
        .map_err(|err| err.to_string())?
    } else if let (Some(before_timestamp_ms), Some(before_filename)) =
        (input.before_timestamp_ms, input.before_filename.as_deref())
    {
        if let Some(owner_scope) = owner_scope.as_deref() {
            db::list_messages_before_for_scope(
                &state.db_path,
                &profile_id,
                owner_scope,
                before_timestamp_ms,
                before_filename,
                limit,
                marked_filter,
            )
        } else {
            db::list_messages_before(
                &state.db_path,
                &profile_id,
                before_timestamp_ms,
                before_filename,
                limit,
                marked_filter,
            )
        }
        .map_err(|err| err.to_string())?
    } else if let Some(owner_scope) = owner_scope.as_deref() {
        db::list_latest_messages_window_for_scope(
            &state.db_path,
            &profile_id,
            owner_scope,
            limit,
            marked_filter,
        )
        .map_err(|err| err.to_string())?
    } else {
        db::list_latest_messages_window(&state.db_path, &profile_id, limit, marked_filter)
            .map_err(|err| err.to_string())?
    };

    let local_has_more_before = if let Some(first) = messages.first() {
        if let Some(owner_scope) = owner_scope.as_deref() {
            db::count_messages_before_for_scope(
                &state.db_path,
                &profile_id,
                owner_scope,
                first.timestamp_ms,
                &first.filename,
                marked_filter,
            )
        } else {
            db::count_messages_before(
                &state.db_path,
                &profile_id,
                first.timestamp_ms,
                &first.filename,
                marked_filter,
            )
        }
        .map_err(|err| err.to_string())?
            > 0
    } else {
        false
    };
    let remote_has_more_before = if let Some((profile, session)) = supabase_context.as_ref() {
        db::get_supabase_history_cursor(&state.db_path, &profile.id, &session.user_id)
            .map_err(|error| error.to_string())?
            .has_more_before
    } else {
        false
    };

    Ok(MessagesWindowResult {
        messages,
        total,
        has_more_before: local_has_more_before || remote_has_more_before,
        marked_count,
    })
}

#[tauri::command]
async fn send_text(
    state: State<'_, AppState>,
    text: String,
    format: Option<String>,
    marked_options: Option<SendMarkedOptionsInput>,
) -> Result<SendMessageResult, String> {
    send_text_impl(&state, text, format, marked_options).await
}

fn normalize_send_text_format(format: Option<String>) -> Result<String, String> {
    let normalized = format
        .unwrap_or_else(|| "text".to_string())
        .trim()
        .to_lowercase();
    match normalized.as_str() {
        "" | "text" => Ok("text".to_string()),
        "markdown" => Ok("markdown".to_string()),
        _ => Err("文本格式仅支持 text 或 markdown".to_string()),
    }
}

fn reject_legacy_local_http_marked_option_fields(value: &serde_json::Value) -> Result<(), String> {
    let Some(object) = value.as_object() else {
        return Ok(());
    };
    for legacy_field in ["selectedTagIds", "createdTags", "deletedTagIds"] {
        if object.contains_key(legacy_field) {
            return Err(format!(
                "markedOptions 不再支持 {legacy_field}，请改用 tagNames"
            ));
        }
    }
    Ok(())
}

fn normalize_local_http_tag_names(tag_names: Vec<String>) -> Result<Vec<String>, String> {
    let mut normalized_tag_names = Vec::new();
    let mut seen_names = HashSet::new();

    for tag_name in tag_names {
        let normalized = normalize_marked_tag_name(&tag_name)?;
        let dedupe_key = normalized.to_lowercase();
        if seen_names.insert(dedupe_key) {
            normalized_tag_names.push(normalized);
        }
    }

    Ok(normalized_tag_names)
}

fn build_local_http_marked_options(
    tags: &[MarkedTag],
    options: LocalHttpApiMarkedOptionsInput,
) -> Result<SendMarkedOptionsInput, String> {
    let normalized_tag_names = normalize_local_http_tag_names(options.tag_names)?;
    let due_date = normalize_marked_due_date(options.due_date)?;
    let marked = options.marked || !normalized_tag_names.is_empty();
    let mut selected_tag_ids = Vec::new();
    let mut created_tags = Vec::new();

    for tag_name in normalized_tag_names {
        if let Some(existing_tag) = tags
            .iter()
            .find(|tag| tag.name.trim().to_lowercase() == tag_name.to_lowercase())
        {
            selected_tag_ids.push(existing_tag.id.clone());
        } else {
            created_tags.push(PendingCreatedTagInput {
                name: tag_name,
                selected: true,
            });
        }
    }

    Ok(SendMarkedOptionsInput {
        marked,
        selected_tag_ids,
        due_date: marked.then_some(due_date).flatten(),
        created_tags,
        deleted_tag_ids: Vec::new(),
    })
}

fn parse_local_http_marked_options_json(
    raw: &str,
) -> Result<LocalHttpApiMarkedOptionsInput, String> {
    let trimmed = raw.trim();
    if trimmed.is_empty() {
        return Err("markedOptions 不能为空".to_string());
    }
    let value: serde_json::Value = serde_json::from_str(trimmed)
        .map_err(|err| format!("markedOptions 必须是合法 JSON: {err}"))?;
    reject_legacy_local_http_marked_option_fields(&value)?;
    serde_json::from_value(value).map_err(|err| format!("markedOptions 格式不正确: {err}"))
}

fn parse_local_http_send_text_request_json(
    raw: &[u8],
) -> Result<LocalHttpApiSendTextRequest, String> {
    let value: serde_json::Value =
        serde_json::from_slice(raw).map_err(|err| format!("请求体必须是合法 JSON: {err}"))?;
    if let Some(marked_options) = value.get("markedOptions") {
        reject_legacy_local_http_marked_option_fields(marked_options)?;
    }
    serde_json::from_value(value).map_err(|err| format!("请求体格式不正确: {err}"))
}

async fn resolve_local_http_marked_options(
    state: &AppState,
    marked_options: Option<LocalHttpApiMarkedOptionsInput>,
) -> Result<Option<SendMarkedOptionsInput>, String> {
    let Some(marked_options) = marked_options else {
        return Ok(None);
    };

    let settings = current_settings(state)?;
    if let Some((profile, session)) = active_supabase_context(state, &settings)? {
        let tags = db::list_tags_for_scope(&state.db_path, &profile.id, &session.user_id)
            .map_err(|error| error.to_string())?
            .into_iter()
            .map(|(tag, _)| tag)
            .collect::<Vec<_>>();
        return build_local_http_marked_options(&tags, marked_options).map(Some);
    }
    let endpoint = resolve_active_endpoint(&settings)?;
    let tags = db::list_marked_tags(&state.db_path, &endpoint.id).map_err(|err| err.to_string())?;
    let resolved = build_local_http_marked_options(&tags, marked_options)?;
    Ok(Some(resolved))
}

async fn send_text_impl(
    state: &AppState,
    text: String,
    format: Option<String>,
    marked_options: Option<SendMarkedOptionsInput>,
) -> Result<SendMessageResult, String> {
    let settings = current_settings(&state)?;
    let context = resolve_send_target_context(state, &settings)?;
    let format = normalize_send_text_format(format)?;
    send_text_to_context(
        state,
        &context,
        &settings.sender_name,
        text,
        format,
        marked_options,
    )
    .await
}

async fn send_text_to_context(
    state: &AppState,
    context: &IntegrationTargetContext,
    sender: &str,
    text: String,
    format: String,
    marked_options: Option<SendMarkedOptionsInput>,
) -> Result<SendMessageResult, String> {
    ensure_integration_context(state, context)?;
    let is_markdown = format == "markdown";
    let extension = if is_markdown {
        "message.md"
    } else {
        "message.txt"
    };

    let timestamp_ms = now_ms();
    let filename = build_message_filename(sender, extension, timestamp_ms);
    let remote_path = message_remote_path(&filename, timestamp_ms);
    let data = text.clone().into_bytes();

    if let (storage_provider::ProviderConfig::Supabase(profile), Some(session)) =
        (&context.provider, context.session.as_ref())
    {
        let _guard = state.sync_guard.lock().await;
        ensure_integration_context(state, context)?;
        let message_id = uuid::Uuid::new_v4().to_string();
        let mut message = DbMessage {
            endpoint_id: profile.id.clone(),
            filename: filename.clone(),
            sender: sender.to_string(),
            timestamp_ms,
            size: data.len() as i64,
            kind: MessageKind::Text.as_str().to_string(),
            original_name: extension.to_string(),
            etag: None,
            mtime: None,
            content: Some(text),
            local_path: None,
            remote_path: None,
            file_hash: None,
            marked: false,
            marked_tag_ids: Vec::new(),
            marked_pinned: false,
            marked_due_date: None,
            format,
            transcript_source: None,
            source_audio_mime_type: None,
            transcript_raw_text: None,
            source_kind: None,
            source_channel_id: None,
            source_message_id: None,
        };
        let marked_changes = apply_supabase_send_marked_options(
            state,
            profile,
            session,
            &mut message,
            marked_options.unwrap_or_default(),
        )?;
        let operation = outbox_operation(
            &profile.id,
            &session.user_id,
            "message",
            &message_id,
            "upsert",
            0,
            supabase_message_payload(&message),
        )?;
        db::save_message_with_marked_changes_and_enqueue(
            &state.db_path,
            &message,
            &marked_changes.created_tags,
            &marked_changes.cleaned_messages,
            &operation,
            &marked_changes.deleted_tags,
            None,
        )
        .map_err(|error| format!("保存 Supabase 消息失败: {error}"))?;
        notify_supabase_outbox_pending(state);
        return Ok(supabase_send_result(&profile.id, &message));
    }

    let storage_provider::ProviderConfig::Webdav(endpoint) = &context.provider else {
        return Err("目标存储空间上下文无效".to_string());
    };

    webdav::upload_file_ensuring_parent(&state.http, endpoint, &remote_path, data.clone()).await?;
    ensure_integration_context(state, context)?;

    let mut message = DbMessage {
        endpoint_id: endpoint.id.clone(),
        filename: filename.clone(),
        sender: sender.to_string(),
        timestamp_ms,
        size: data.len() as i64,
        kind: MessageKind::Text.as_str().to_string(),
        original_name: extension.to_string(),
        etag: None,
        mtime: None,
        content: Some(text),
        local_path: None,
        remote_path: Some(remote_path),
        file_hash: None,
        marked: false,
        marked_tag_ids: Vec::new(),
        marked_pinned: false,
        marked_due_date: None,
        format,
        transcript_source: None,
        source_audio_mime_type: None,
        transcript_raw_text: None,
        source_kind: None,
        source_channel_id: None,
        source_message_id: None,
    };

    persist_sent_message_with_marked_options(state, endpoint, &mut message, marked_options).await
}

fn cache_uploaded_bytes(target_path: &Path, data: &[u8]) -> Result<(), String> {
    if let Some(parent) = target_path.parent() {
        fs::create_dir_all(parent).map_err(|err| format!("??????: {err}"))?;
    }
    fs::write(target_path, data).map_err(|err| format!("????????: {err}"))
}

fn cache_uploaded_file(source_path: &Path, target_path: &Path) -> Result<(), String> {
    if let Some(parent) = target_path.parent() {
        fs::create_dir_all(parent).map_err(|err| format!("??????: {err}"))?;
    }
    fs::copy(source_path, target_path).map_err(|err| format!("????????: {err}"))?;
    Ok(())
}

fn create_upload_temp_path(original_name: &str) -> Result<PathBuf, String> {
    let mut rng = rand::thread_rng();
    let temp_dir = std::env::temp_dir().join(format!(
        "transfer-genie-upload-{}-{:016x}",
        now_ms(),
        rng.gen::<u64>()
    ));
    fs::create_dir_all(&temp_dir).map_err(|err| format!("????????: {err}"))?;
    Ok(temp_dir.join(sanitize_filename(original_name)))
}

fn cleanup_upload_temp_path(path: &Path) {
    let _ = fs::remove_file(path);
    if let Some(parent) = path.parent() {
        let _ = fs::remove_dir(parent);
    }
}

fn media_preview_local_path(endpoint_dir: &Path, filename: &str, timestamp_ms: i64) -> PathBuf {
    endpoint_dir
        .join(".previews")
        .join(media_preview_relative_path(filename, timestamp_ms))
}

fn legacy_thumbnail_local_path(endpoint_dir: &Path, filename: &str) -> PathBuf {
    endpoint_dir.join(".thumbs").join(filename)
}

fn delete_local_media_cache_for_entry(
    state: &AppState,
    endpoint_id: &str,
    filename: &str,
    original_name: &str,
    timestamp_ms: i64,
) {
    let endpoint_dir = endpoint_files_dir(state, endpoint_id);
    let preview_path = media_preview_local_path(&endpoint_dir, filename, timestamp_ms);
    let legacy_thumbnail_path = legacy_thumbnail_local_path(&endpoint_dir, filename);
    let playback_path = media_preview::media_playback_cache_path(
        &endpoint_dir,
        endpoint_id,
        filename,
        original_name,
        "file",
    );
    let speech_playback_path = media_preview::media_playback_cache_path(
        &endpoint_dir,
        endpoint_id,
        filename,
        original_name,
        "speech-audio",
    );
    for path in [
        preview_path,
        legacy_thumbnail_path,
        playback_path,
        speech_playback_path,
    ] {
        if path.starts_with(&endpoint_dir) {
            let _ = fs::remove_file(path);
        }
    }
}

fn delete_supabase_attachment_cache(
    state: &AppState,
    profile_id: &str,
    owner_scope: &str,
    attachment: &db::AttachmentSyncRecord,
    remove_original: bool,
) -> Result<(), String> {
    let endpoint_dir = endpoint_files_dir(state, profile_id);
    let preview_dir = media_preview::isolated_preview_attachment_dir(
        &endpoint_dir,
        owner_scope,
        &attachment.attachment_id,
    );
    if preview_dir.starts_with(&endpoint_dir) && preview_dir.is_dir() {
        fs::remove_dir_all(&preview_dir)
            .map_err(|error| format!("删除附件预览缓存失败: {error}"))?;
    }
    if !remove_original || attachment.upload_state != "uploaded" {
        return Ok(());
    }
    if let Some(path) = attachment
        .local_path
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(PathBuf::from)
    {
        delete_local_file(&path, &endpoint_dir)?;
        if let Some(parent) = path.parent() {
            let _ = fs::remove_dir(parent);
        }
    }
    db::clear_uploaded_attachment_local_path(
        &state.db_path,
        profile_id,
        owner_scope,
        &attachment.attachment_id,
        now_ms(),
    )
    .map_err(|error| format!("清理附件本地状态失败: {error}"))?;
    Ok(())
}

async fn delete_remote_media_previews(
    state: &AppState,
    endpoint: &WebDavEndpoint,
    filename: &str,
    original_name: &str,
    remote_path: Option<&str>,
    timestamp_ms: i64,
) {
    let preview_remote_path = media_preview_remote_path(filename, timestamp_ms);
    let legacy_remote_path =
        resolved_thumbnail_remote_path(remote_path, filename, Some(timestamp_ms));
    if let Err(err) = webdav::delete_file(&state.http, endpoint, &preview_remote_path, true).await {
        log::warn!(
            "delete remote media preview failed for {}: {}",
            filename,
            err
        );
    }
    if media_preview::media_preview_kind(original_name)
        == Some(media_preview::MediaPreviewKind::Image)
    {
        if let Err(err) =
            webdav::delete_file(&state.http, endpoint, &legacy_remote_path, true).await
        {
            log::warn!("delete legacy thumbnail failed for {}: {}", filename, err);
        }
    }
}

fn spawn_media_preview_upload(
    http: Client,
    endpoint: WebDavEndpoint,
    endpoint_dir: PathBuf,
    filename: String,
    timestamp_ms: i64,
    original_name: String,
    source_path: PathBuf,
) {
    if media_preview::media_preview_kind(&original_name).is_none() {
        return;
    }
    tokio::spawn(async move {
        let permit = match media_preview::preview_generation_semaphore()
            .acquire_owned()
            .await
        {
            Ok(permit) => permit,
            Err(_) => return,
        };
        let preview_path = media_preview_local_path(&endpoint_dir, &filename, timestamp_ms);
        let generation_path = preview_path.clone();
        let generated = tokio::task::spawn_blocking(move || {
            media_preview::run_preview_generator(|| {
                media_preview::generate_media_preview(
                    &source_path,
                    &original_name,
                    &generation_path,
                )
            })
        })
        .await;
        drop(permit);
        match generated {
            Ok(Ok(true)) => {}
            Ok(Ok(false)) => return,
            Ok(Err(err)) => {
                log::warn!("media preview generation failed for {}: {}", filename, err);
                return;
            }
            Err(err) => {
                log::warn!("media preview task failed for {}: {}", filename, err);
                return;
            }
        }
        let preview_data = match fs::read(&preview_path) {
            Ok(data) => data,
            Err(err) => {
                log::warn!("read media preview failed for {}: {}", filename, err);
                return;
            }
        };
        let preview_remote_path = media_preview_remote_path(&filename, timestamp_ms);
        if let Err(err) = webdav::upload_file_ensuring_parent(
            &http,
            &endpoint,
            &preview_remote_path,
            preview_data,
        )
        .await
        {
            log::warn!("upload media preview failed for {}: {}", filename, err);
        }
    });
}

async fn send_file_data_impl(
    state: &AppState,
    window: Option<&Window>,
    data: Vec<u8>,
    original_name: String,
    client_id: Option<String>,
    marked_options: Option<SendMarkedOptionsInput>,
) -> Result<SendMessageResult, String> {
    let temp_path = create_upload_temp_path(&original_name)?;
    cache_uploaded_bytes(&temp_path, &data)?;
    let result = send_file_path_impl(
        state,
        window,
        &temp_path,
        original_name,
        client_id,
        marked_options,
    )
    .await;
    cleanup_upload_temp_path(&temp_path);
    result
}

async fn send_file_path_impl(
    state: &AppState,
    window: Option<&Window>,
    source_path: &Path,
    original_name: String,
    client_id: Option<String>,
    marked_options: Option<SendMarkedOptionsInput>,
) -> Result<SendMessageResult, String> {
    let settings = current_settings(state)?;
    let context = resolve_send_target_context(state, &settings)?;
    send_file_path_to_context(
        state,
        &context,
        &settings.sender_name,
        window,
        source_path,
        original_name,
        client_id,
        marked_options,
    )
    .await
}

#[allow(clippy::too_many_arguments)]
async fn send_file_path_to_context(
    state: &AppState,
    context: &IntegrationTargetContext,
    sender: &str,
    window: Option<&Window>,
    source_path: &Path,
    original_name: String,
    client_id: Option<String>,
    marked_options: Option<SendMarkedOptionsInput>,
) -> Result<SendMessageResult, String> {
    ensure_integration_context(state, context)?;
    let original_name = original_name.trim().to_string();
    if original_name.is_empty() {
        return Err("???????".to_string());
    }

    let source_path = source_path.to_path_buf();
    let total_bytes = fs::metadata(&source_path)
        .map_err(|err| format!("????????: {err}"))?
        .len();
    let timestamp_ms = now_ms();
    let filename = build_message_filename(sender, &original_name, timestamp_ms);
    let remote_path = message_remote_path(&filename, timestamp_ms);
    if let (storage_provider::ProviderConfig::Supabase(profile), Some(session)) =
        (&context.provider, context.session.as_ref())
    {
        let _guard = state.sync_guard.lock().await;
        ensure_integration_context(state, context)?;
        let message_id = uuid::Uuid::new_v4().to_string();
        let attachment_id = uuid::Uuid::new_v4().to_string();
        let local_dir = endpoint_files_dir(state, &profile.id)
            .join(&session.user_id)
            .join("attachments")
            .join(&attachment_id);
        fs::create_dir_all(&local_dir).map_err(|error| format!("创建附件缓存目录失败: {error}"))?;
        let local_path = local_dir.join(&original_name);
        cache_uploaded_file(&source_path, &local_path)?;
        let hash_path = local_path.clone();
        let file_hash =
            tokio::task::spawn_blocking(move || compute_file_hash_from_path(&hash_path))
                .await
                .map_err(|error| format!("计算附件摘要失败: {error}"))??;
        let object_path = supabase_attachment_object_path(
            &session.user_id,
            profile
                .supabase
                .as_ref()
                .map(|config| config.space_id.as_str())
                .unwrap_or_default(),
            &attachment_id,
            &original_name,
        );
        let mut message = DbMessage {
            endpoint_id: profile.id.clone(),
            filename: filename.clone(),
            sender: sender.to_string(),
            timestamp_ms,
            size: total_bytes as i64,
            kind: MessageKind::File.as_str().into(),
            original_name: original_name.clone(),
            etag: None,
            mtime: None,
            content: None,
            local_path: Some(local_path.to_string_lossy().to_string()),
            remote_path: Some(object_path.clone()),
            file_hash: Some(file_hash.clone()),
            marked: false,
            marked_tag_ids: Vec::new(),
            marked_pinned: false,
            marked_due_date: None,
            format: "text".into(),
            transcript_source: None,
            source_audio_mime_type: None,
            transcript_raw_text: None,
            source_kind: None,
            source_channel_id: None,
            source_message_id: None,
        };
        let marked_changes = apply_supabase_send_marked_options(
            state,
            profile,
            session,
            &mut message,
            marked_options.unwrap_or_default(),
        )?;
        let message_operation = outbox_operation(
            &profile.id,
            &session.user_id,
            "message",
            &message_id,
            "upsert",
            0,
            supabase_message_payload(&message),
        )?;
        let mime_type = attachment_mime_type(&original_name).to_string();
        let attachment_payload = serde_json::json!({"messageId":message_id,"originalName":original_name,
            "objectPath":object_path,"previewObjectPath":null,"mimeType":mime_type,
            "size":total_bytes,"sha256":file_hash,"uploadStatus":"uploaded"});
        let attachment_operation = outbox_operation(
            &profile.id,
            &session.user_id,
            "attachment",
            &attachment_id,
            "upsert",
            0,
            attachment_payload,
        )?;
        db::save_message_with_marked_changes_and_enqueue(
            &state.db_path,
            &message,
            &marked_changes.created_tags,
            &marked_changes.cleaned_messages,
            &message_operation,
            &marked_changes.deleted_tags,
            Some((
                &attachment_id,
                &object_path,
                None,
                Some(&mime_type),
                &attachment_operation,
            )),
        )
        .map_err(|error| format!("保存 Supabase 附件失败: {error}"))?;
        notify_supabase_outbox_pending(state);
        return Ok(supabase_send_result(&profile.id, &message));
    }
    let storage_provider::ProviderConfig::Webdav(endpoint) = &context.provider else {
        return Err("目标存储空间上下文无效".to_string());
    };

    let client_id = client_id
        .and_then(|value| {
            if value.trim().is_empty() {
                None
            } else {
                Some(value)
            }
        })
        .unwrap_or_else(|| filename.clone());

    webdav::ensure_parent_directories(&state.http, endpoint, &remote_path).await?;
    if let Some(window) = window {
        emit_upload_progress(
            window,
            &client_id,
            Some(&filename),
            Some(&original_name),
            0,
            total_bytes,
            "progress",
            None,
        );
    }

    let progress_window = window.cloned();
    let progress_client_id = client_id.clone();
    let progress_filename = filename.clone();
    let progress_original_name = original_name.clone();
    let upload_result = webdav::upload_file_path_with_progress(
        &state.http,
        endpoint,
        &remote_path,
        &source_path,
        move |sent, total| {
            if let Some(progress_window) = progress_window.as_ref() {
                emit_upload_progress(
                    progress_window,
                    &progress_client_id,
                    Some(&progress_filename),
                    Some(&progress_original_name),
                    sent,
                    total,
                    "progress",
                    None,
                );
            }
        },
    )
    .await;

    if let Err(err) = upload_result {
        let _ = persist_upload_history(
            state,
            &endpoint.id,
            &filename,
            &original_name,
            None,
            "error",
            Some(err.clone()),
            total_bytes as i64,
        );
        if let Some(window) = window {
            emit_upload_progress(
                window,
                &client_id,
                Some(&filename),
                Some(&original_name),
                0,
                total_bytes,
                "error",
                Some(err.clone()),
            );
        }
        return Err(err);
    }
    ensure_integration_context(state, context)?;

    let endpoint_dir = endpoint_files_dir(state, &endpoint.id);
    let local_path = endpoint_dir.join(&filename);
    cache_uploaded_file(&source_path, &local_path)?;
    let hash_path = source_path.clone();
    let file_hash = tokio::task::spawn_blocking(move || compute_file_hash_from_path(&hash_path))
        .await
        .map_err(|err| format!("????????: {err}"))??;

    let mut message = DbMessage {
        endpoint_id: endpoint.id.clone(),
        filename: filename.clone(),
        sender: sender.to_string(),
        timestamp_ms,
        size: total_bytes as i64,
        kind: MessageKind::File.as_str().to_string(),
        original_name: original_name.clone(),
        etag: None,
        mtime: None,
        content: None,
        local_path: Some(local_path.to_string_lossy().to_string()),
        remote_path: Some(remote_path),
        file_hash: Some(file_hash),
        marked: false,
        marked_tag_ids: Vec::new(),
        marked_pinned: false,
        marked_due_date: None,
        format: "text".to_string(),
        transcript_source: None,
        source_audio_mime_type: None,
        transcript_raw_text: None,
        source_kind: None,
        source_channel_id: None,
        source_message_id: None,
    };

    let result =
        persist_sent_message_with_marked_options(state, endpoint, &mut message, marked_options)
            .await?;
    persist_upload_history(
        state,
        &endpoint.id,
        &filename,
        &message.original_name,
        Some(&local_path),
        "complete",
        None,
        total_bytes as i64,
    )?;
    spawn_media_preview_upload(
        state.http.clone(),
        endpoint.clone(),
        endpoint_dir,
        filename,
        timestamp_ms,
        message.original_name.clone(),
        local_path,
    );
    if let Some(window) = window {
        emit_upload_progress(
            window,
            &client_id,
            Some(&message.filename),
            Some(&message.original_name),
            total_bytes,
            total_bytes,
            "complete",
            None,
        );
    }
    Ok(result)
}

