    fn test_json_response(
        status: HttpStatusCode,
        value: &serde_json::Value,
        content_range: Option<String>,
    ) -> AxumResponse {
        let mut builder = AxumResponse::builder()
            .status(status)
            .header("content-type", "application/json");
        if let Some(content_range) = content_range {
            builder = builder.header("content-range", content_range);
        }
        builder
            .body(Body::from(value.to_string()))
            .expect("build test Supabase response")
    }

    async fn test_supabase_snapshot(
        TestAxumState(state): TestAxumState<TestSupabaseState>,
        AxumPath(table): AxumPath<String>,
        Query(query): Query<TestHashMap<String, String>>,
    ) -> AxumResponse {
        if table == "spaces" {
            let requested_id = query.get("id").and_then(|value| value.strip_prefix("eq."));
            let mut rows = state
                .snapshots
                .lock()
                .unwrap()
                .iter()
                .filter(|(key, snapshot)| {
                    key.starts_with("spaces/")
                        && requested_id.is_none_or(|id| snapshot["id"].as_str() == Some(id))
                })
                .map(|(_, snapshot)| snapshot.clone())
                .collect::<Vec<_>>();
            rows.sort_by(|left, right| {
                right["updated_at"]
                    .as_str()
                    .cmp(&left["updated_at"].as_str())
                    .then_with(|| left["id"].as_str().cmp(&right["id"].as_str()))
            });
            return test_json_response(HttpStatusCode::OK, &serde_json::json!(rows), None);
        }
        if table == "messages" && !query.contains_key("id") {
            let space_id = query
                .get("space_id")
                .and_then(|value| value.strip_prefix("eq."))
                .unwrap_or_default();
            let rows = state
                .snapshots
                .lock()
                .unwrap()
                .iter()
                .filter(|(key, snapshot)| {
                    key.starts_with("messages/")
                        && snapshot["space_id"].as_str() == Some(space_id)
                        && snapshot["deleted_at"].is_null()
                })
                .map(|(_, snapshot)| snapshot.clone())
                .collect::<Vec<_>>();
            let total = rows.len();
            let body = rows.into_iter().take(1).collect::<Vec<_>>();
            let content_range = if total == 0 {
                "*/0".to_string()
            } else {
                format!("0-0/{total}")
            };
            return test_json_response(
                HttpStatusCode::OK,
                &serde_json::json!(body),
                Some(content_range),
            );
        }
        if table == "tags" {
            if let Some(name) = query
                .get("name")
                .and_then(|value| value.strip_prefix("ilike."))
            {
                let rows: Vec<serde_json::Value> = state
                    .snapshots
                    .lock()
                    .unwrap()
                    .iter()
                    .filter(|(key, snapshot)| {
                        key.starts_with("tags/")
                            && snapshot["name"]
                                .as_str()
                                .is_some_and(|value| value.eq_ignore_ascii_case(name))
                            && snapshot["deleted_at"].is_null()
                    })
                    .map(|(_, snapshot)| snapshot.clone())
                    .collect();
                return test_json_response(HttpStatusCode::OK, &serde_json::json!(rows), None);
            }
        }
        let id = query
            .get("id")
            .and_then(|value| value.strip_prefix("eq."))
            .unwrap_or_default();
        let rows = state
            .snapshots
            .lock()
            .unwrap()
            .get(&format!("{table}/{id}"))
            .cloned()
            .into_iter()
            .collect::<Vec<_>>();
        test_json_response(HttpStatusCode::OK, &serde_json::json!(rows), None)
    }

