    #[test]
    fn test_history_entry_serde() {
        let entry = HistoryEntry {
            filename: "test.txt".to_string(),
            sender: "me".to_string(),
            timestamp_ms: 1234567890,
            size: 100,
            kind: "text".to_string(),
            original_name: "test.txt".to_string(),
            remote_path: Some("files/test.txt".to_string()),
            marked: true,
            marked_tag_ids: Vec::new(),
            marked_pinned: false,
            marked_due_date: None,
            format: "text".to_string(),
            transcript_source: None,
            source_audio_mime_type: None,
            transcript_text: None,
            transcript_raw_text: None,
            source_kind: Some("telegram".to_string()),
            source_channel_id: Some("-1001".to_string()),
            source_message_id: Some("42".to_string()),
        };

        let json = serde_json::to_string(&entry).unwrap();
        assert!(json.contains("\"marked\":true"));

        let deserialized: HistoryEntry = serde_json::from_str(&json).unwrap();
        assert_eq!(deserialized.marked, true);
        assert_eq!(deserialized.format, "text");

        // Test default
        let json_old = r#"{"filename":"test.txt","sender":"me","timestamp_ms":1234567890,"size":100,"kind":"text","original_name":"test.txt"}"#;
        let deserialized_old: HistoryEntry = serde_json::from_str(json_old).unwrap();
        assert_eq!(deserialized_old.marked, false);
        assert_eq!(deserialized_old.format, "");
        assert_eq!(deserialized_old.transcript_source, None);
        assert_eq!(deserialized_old.source_audio_mime_type, None);
        assert_eq!(deserialized_old.transcript_text, None);
        assert_eq!(deserialized_old.source_kind, None);
        assert_eq!(deserialized_old.source_channel_id, None);
        assert_eq!(deserialized_old.source_message_id, None);
    }

