        let sent = send_text_impl(
            &state,
            "marked cloud message".into(),
            None,
            Some(SendMarkedOptionsInput {
                marked: true,
                due_date: Some("2026-12-31".into()),
                created_tags: vec![PendingCreatedTagInput {
                    name: "Cloud Tag".into(),
                    selected: true,
                }],
                ..Default::default()
            }),
        )
        .await
        .expect("save marked message with new tag");

